window.BANK = {"modules": {"IU01": {"questions": [{"topic": "1.1.1 Phần cứng - CPU", "q": "CPU là viết tắt của cụm từ nào?", "options": ["Central Program Unit", "Central Processing Unit", "Computer Peripheral Unit", "Control Processing Utility"], "answer": 1, "explain": "CPU (Central Processing Unit) là bộ xử lý trung tâm, xử lý lệnh và dữ liệu, thường được gọi là bộ não của máy tính (mục 1.1.1)."}, {"topic": "1.1.1 Phần cứng - CPU", "q": "Tốc độ xung nhịp của CPU được đo bằng đơn vị nào?", "options": ["Nano giây (ns)", "Byte", "Bit trên giây (bps)", "Hertz (Hz)"], "answer": 3, "explain": "Hertz (Hz) đo số chu kỳ xung nhịp mỗi giây; CPU hiện nay thường ghi bằng GHz (mục 1.1.1)."}, {"topic": "1.1.1 Phần cứng - Biểu diễn dữ liệu", "q": "Một byte gồm bao nhiêu bit?", "options": ["8 bit", "4 bit", "16 bit", "10 bit"], "answer": 0, "explain": "Theo giáo trình, một nhóm 8 bit tạo thành 1 byte (mục 1.1.1)."}, {"topic": "1.1.1 Phần cứng - Biểu diễn dữ liệu", "q": "Theo cách quy đổi nhị phân của giáo trình, 1 Kilobyte (KB) bằng bao nhiêu byte?", "options": ["1.000 byte", "1.048.576 byte", "1.024 byte", "512 byte"], "answer": 2, "explain": "1 KB = 1.024 byte; 1 MB = 1.048.576 byte (mục 1.1.1)."}, {"topic": "1.1.1 Phần cứng - Biểu diễn dữ liệu", "q": "Theo cách quy đổi nhị phân, 1 Terabyte (TB) bằng bao nhiêu Gigabyte (GB)?", "options": ["512 GB", "1.048.576 GB", "1.024 GB", "2.048 GB"], "answer": 2, "explain": "Mỗi bậc đơn vị lưu trữ gấp 1.024 lần bậc liền trước nên 1 TB = 1.024 GB (mục 1.1.1)."}, {"topic": "1.1.1 Phần cứng - Hệ đếm", "q": "Số nhị phân 1010 có giá trị thập phân là:", "options": ["10", "12", "8", "14"], "answer": 0, "explain": "1010 (nhị phân) = 1×8 + 0×4 + 1×2 + 0×1 = 10."}, {"topic": "1.1.1 Phần cứng - Hệ đếm", "q": "Số thập phân 13 được biểu diễn trong hệ nhị phân là:", "options": ["1011", "1110", "1001", "1101"], "answer": 3, "explain": "13 = 8 + 4 + 1 nên biểu diễn nhị phân là 1101."}, {"topic": "1.1.1 Phần cứng - Hệ đếm", "q": "Số thập lục phân (hexa) 2F có giá trị thập phân là:", "options": ["17", "47", "32", "215"], "answer": 1, "explain": "2F = 2×16 + 15 = 47."}, {"topic": "1.1.1 Phần cứng - Bộ nhớ", "q": "Đặc điểm nào sau đây đúng với bộ nhớ RAM?", "options": ["Chỉ cho phép đọc dữ liệu, không thể ghi", "Giữ nguyên dữ liệu khi tắt nguồn điện", "Mất dữ liệu khi mất nguồn điện (volatile)", "Có dung lượng luôn lớn hơn ổ đĩa cứng"], "answer": 2, "explain": "RAM lưu tạm thời bản sao chương trình và dữ liệu, có tính bay hơi (volatile) nên thông tin mất khi mất điện (mục 1.1.1)."}, {"topic": "1.1.1 Phần cứng - Bộ nhớ", "q": "Loại bộ nhớ nào sau đây vẫn duy trì thông tin khi nguồn điện cấp không còn?", "options": ["ROM", "RAM", "Cache của CPU", "Thanh ghi (register) của CPU"], "answer": 0, "explain": "Khác với RAM, thông tin trên ROM vẫn được giữ khi mất điện; cache và thanh ghi của CPU đều là bộ nhớ khả biến (mục 1.1.1)."}, {"topic": "1.1.1 Phần cứng - Thiết bị lưu trữ", "q": "Thiết bị nào sau đây KHÔNG phải là thiết bị lưu trữ?", "options": ["Ổ đĩa cứng", "Ổ đĩa quang (CD/DVD)", "Thẻ nhớ", "Máy quét (scanner)"], "answer": 3, "explain": "Máy quét là thiết bị nhập dùng để số hóa hình ảnh; ổ cứng, ổ quang, thẻ nhớ là thiết bị lưu trữ (mục 1.1.1)."}, {"topic": "1.1.1 Phần cứng - Thiết bị nhập/xuất", "q": "Thiết bị nào sau đây là thiết bị xuất (output)?", "options": ["Máy quét (scanner)", "Máy chiếu (projector)", "Đầu đọc mã vạch", "Cần điều khiển (joystick)"], "answer": 1, "explain": "Máy chiếu hiển thị thông tin từ máy tính ra bề mặt/màn chiếu nên là thiết bị xuất; các thiết bị còn lại đưa dữ liệu vào máy tính (mục 1.1.1)."}, {"topic": "1.1.1 Phần cứng - Thiết bị nhập/xuất", "q": "Máy in chuyên dụng dùng để in hình ảnh, bản vẽ trên khổ giấy cực lớn được gọi là:", "options": ["Plotter (máy in đồ họa)", "Máy in ảnh", "Máy in kim", "Máy in nhiệt"], "answer": 0, "explain": "Giáo trình mô tả plotter là máy in chuyên dụng được thiết kế để in hình ảnh trên khổ giấy cực lớn (mục 1.1.1)."}, {"topic": "1.1.1 Phần cứng - Cổng kết nối", "q": "Cổng HDMI được dùng chủ yếu để truyền tín hiệu nào?", "options": ["Chỉ tín hiệu âm thanh analog", "Tín hiệu điều khiển ổ đĩa SATA", "Hình ảnh và âm thanh kỹ thuật số độ phân giải cao", "Tín hiệu mạng LAN duy nhất"], "answer": 2, "explain": "HDMI (High-Definition Multimedia Interface) truyền hình ảnh và âm thanh số độ phân giải cao qua một cáp (mục 1.1.1)."}, {"topic": "1.1.1 Phần cứng - Phân loại thiết bị", "q": "Theo giáo trình, thiết bị nào sau đây thuộc nhóm thiết bị cầm tay?", "options": ["Desktop", "Laptop", "Netbook", "Tablet"], "answer": 3, "explain": "Giáo trình xếp Tablet, Smartphone, Smartwatch vào thiết bị cầm tay; Desktop, Laptop, Notebook, Netbook thuộc máy tính cá nhân (mục 1.1.1)."}, {"topic": "1.1.2 Phần mềm máy tính", "q": "Phần mềm nào sau đây là phần mềm hệ thống?", "options": ["Microsoft Word", "Linux", "Adobe Photoshop", "Windows Media Player"], "answer": 1, "explain": "Linux là hệ điều hành thuộc nhóm phần mềm hệ thống; Word, Photoshop, Windows Media Player là phần mềm ứng dụng (mục 1.1.2)."}, {"topic": "1.1.2 Phần mềm máy tính", "q": "Bộ phần mềm văn phòng (Office Software) như Microsoft Word, Excel thuộc nhóm nào?", "options": ["Phần mềm hệ thống", "Firmware", "Phần mềm ứng dụng", "Trình điều khiển thiết bị (driver)"], "answer": 2, "explain": "Office Software là phần mềm ứng dụng, giúp người dùng thực hiện công việc trên máy tính nhanh chóng, dễ dàng (mục 1.1.2)."}, {"topic": "1.1.2 Phần mềm máy tính", "q": "Vai trò chính của phần mềm hệ thống là gì?", "options": ["Điều khiển phần cứng và làm nền để các phần mềm ứng dụng hoạt động", "Hỗ trợ người dùng soạn thảo, định dạng và in các loại văn bản", "Chuyên xử lý hình ảnh, đồ họa và thiết kế bản vẽ kỹ thuật", "Chỉ dùng để phát nhạc, xem phim và giải trí đa phương tiện"], "answer": 0, "explain": "Phần mềm hệ thống điều khiển phần cứng, các thiết bị chuyên dụng và là nền cho các ứng dụng khác hoạt động (mục 1.1.2)."}, {"topic": "1.1.2 Phần mềm máy tính", "q": "Đặc điểm cốt lõi của phần mềm mã nguồn mở (open source) là gì?", "options": ["Bắt buộc trả phí bản quyền cho mỗi máy cài đặt", "Chỉ chạy được trên hệ điều hành Linux", "Chỉ được dùng thử trong một khoảng thời gian nhất định", "Mã nguồn được công khai để người dùng xem, sửa đổi và phân phối theo giấy phép"], "answer": 3, "explain": "Phần mềm mã nguồn mở công khai mã nguồn; quyền xem, sửa, phân phối được quy định bởi giấy phép (mục 1.1.2)."}, {"topic": "1.1.2 Phần mềm máy tính", "q": "Phần mềm cho dùng thử trong thời hạn hoặc với chức năng giới hạn, sau đó phải trả phí để dùng đầy đủ thuộc loại nào?", "options": ["Freeware (phần mềm miễn phí)", "Shareware (phần mềm chia sẻ)", "Phần mềm mã nguồn mở", "Adware"], "answer": 1, "explain": "Shareware cho dùng thử miễn phí có giới hạn về thời gian hoặc tính năng, muốn dùng đầy đủ phải mua bản quyền (mục 1.1.2)."}, {"topic": "1.1.3 Hiệu năng máy tính", "q": "Yếu tố nào sau đây KHÔNG phải là yếu tố trực tiếp quyết định hiệu năng xử lý của máy tính?", "options": ["Kích thước (inch) của màn hình", "Tốc độ bộ xử lý trung tâm (CPU)", "Dung lượng bộ nhớ (RAM)", "Tốc độ ổ cứng"], "answer": 0, "explain": "Giáo trình nêu 4 yếu tố hiệu năng: tốc độ CPU, dung lượng bộ nhớ, tốc độ ổ cứng, tốc độ mạch tăng tốc đồ họa; kích thước màn hình không nằm trong đó (mục 1.1.3)."}, {"topic": "1.1.3 Hiệu năng máy tính", "q": "Thay ổ cứng HDD bằng ổ SSD chủ yếu giúp cải thiện điều gì?", "options": ["Tần số xung nhịp của CPU", "Độ phân giải màn hình", "Tốc độ khởi động và tốc độ đọc/ghi dữ liệu", "Dung lượng bộ nhớ ROM"], "answer": 2, "explain": "SSD không có bộ phận cơ khí nên truy xuất và truyền dữ liệu nhanh hơn HDD, liên quan yếu tố tốc độ ổ cứng (mục 1.1.3)."}, {"topic": "1.1.3 Hiệu năng máy tính", "q": "Khi RAM không đủ cho các chương trình đang chạy, hệ điều hành dùng một phần ổ cứng làm bộ nhớ ảo (swap/pagefile). Hệ quả thường thấy là gì?", "options": ["Tốc độ xung nhịp CPU tăng lên", "Dung lượng ổ cứng tự động tăng", "Các tập tin trên ổ cứng bị xóa", "Máy chạy chậm đi vì ổ cứng chậm hơn RAM đáng kể"], "answer": 3, "explain": "Ổ cứng có tốc độ truy xuất thấp hơn RAM nhiều nên dùng bộ nhớ ảo làm giảm hiệu năng (mục 1.1.3)."}, {"topic": "1.1.4 Mạng máy tính và truyền thông", "q": "Mạng LAN (Local Area Network) là mạng có phạm vi như thế nào?", "options": ["Toàn cầu, kết nối nhiều quốc gia", "Khu vực hẹp như một tòa nhà, văn phòng hoặc khuôn viên", "Liên tỉnh, kết nối các thành phố lớn", "Chỉ trong phạm vi một thiết bị"], "answer": 1, "explain": "LAN là mạng cục bộ trong phạm vi địa lý nhỏ; MAN cỡ đô thị; WAN cỡ quốc gia/quốc tế (mục 1.1.4)."}, {"topic": "1.1.4 Mạng máy tính và truyền thông", "q": "Mạng bao phủ phạm vi địa lý rất rộng (quốc gia, quốc tế), điển hình là Internet, thuộc loại nào?", "options": ["LAN", "MAN", "WAN", "PAN"], "answer": 2, "explain": "WAN (Wide Area Network) là mạng diện rộng, Internet là ví dụ điển hình (mục 1.1.4)."}, {"topic": "1.1.4 Mạng máy tính và truyền thông", "q": "Đường truyền có tốc độ 100 Mbps thì tốc độ tải dữ liệu tối đa lý thuyết xấp xỉ bao nhiêu MB/s? (1 byte = 8 bit)", "options": ["12,5 MB/s", "100 MB/s", "800 MB/s", "1,25 MB/s"], "answer": 0, "explain": "Tốc độ đường truyền tính bằng bit/giây nên 100 Mbps ÷ 8 = 12,5 MB/s (mục 1.1.4)."}, {"topic": "1.1.4 Mạng máy tính và truyền thông", "q": "Thiết bị mạng nào định tuyến gói tin giữa các mạng khác nhau và thường dùng để nối mạng LAN ra Internet?", "options": ["Hub", "Repeater", "Switch (lớp 2)", "Router"], "answer": 3, "explain": "Router chọn đường và chuyển gói tin giữa các mạng khác nhau; hub, repeater và switch lớp 2 hoạt động trong cùng một mạng (mục 1.1.4)."}, {"topic": "1.1.4 Mạng máy tính và truyền thông", "q": "Nhà cung cấp dịch vụ Internet (ISP) là đơn vị nào?", "options": ["Đơn vị sản xuất phần mềm diệt virus", "Đơn vị cung cấp dịch vụ kết nối và truy cập Internet cho người dùng", "Đơn vị duy nhất cấp phát tên miền cho toàn thế giới", "Cơ quan kiểm duyệt nội dung của mọi trang web"], "answer": 1, "explain": "ISP (Internet Service Provider) cung cấp đường truyền và dịch vụ truy cập Internet, ví dụ VNPT, Viettel, FPT (mục 1.1.4)."}, {"topic": "1.2 Ứng dụng của CNTT-TT", "q": "Hoạt động mua bán hàng hóa, dịch vụ thông qua Internet được gọi là gì?", "options": ["E-Government", "E-Banking", "E-Commerce", "Tele-working"], "answer": 2, "explain": "E-Commerce là thương mại điện tử: mua bán hàng hóa, dịch vụ trên môi trường mạng (mục 1.2)."}, {"topic": "1.2 Ứng dụng của CNTT-TT", "q": "Chuyển khoản và tra cứu số dư tài khoản bằng ứng dụng ngân hàng trên điện thoại thuộc loại ứng dụng nào?", "options": ["E-Banking", "E-Government", "Tele-conference", "E-Commerce"], "answer": 0, "explain": "E-Banking (ngân hàng điện tử) cho phép thực hiện giao dịch ngân hàng qua Internet/di động (mục 1.2)."}, {"topic": "1.2 Ứng dụng của CNTT-TT", "q": "Hình thức họp trực tuyến giữa các thành viên ở nhiều địa điểm khác nhau, có cả âm thanh và hình ảnh qua mạng, là gì?", "options": ["Tele-working", "E-Mail", "SMS", "Tele-conference"], "answer": 3, "explain": "Tele-conference là hội nghị từ xa; Tele-working là làm việc từ xa, không nhất thiết là cuộc họp (mục 1.2)."}, {"topic": "1.2 Ứng dụng của CNTT-TT", "q": "VoIP là công nghệ dùng để làm gì?", "options": ["Gửi thư điện tử kèm tập tin", "Truyền thoại (cuộc gọi) qua mạng IP/Internet", "Bảo vệ máy tính trước mã độc", "Nén tập tin âm thanh để lưu trữ"], "answer": 1, "explain": "VoIP (Voice over IP) truyền tín hiệu thoại dưới dạng gói dữ liệu qua mạng IP/Internet (mục 1.2)."}, {"topic": "1.2 Ứng dụng của CNTT-TT", "q": "Công dân nộp hồ sơ, tra cứu thủ tục hành chính qua cổng dịch vụ công trực tuyến là ví dụ của ứng dụng nào?", "options": ["E-Government (chính phủ điện tử)", "E-Commerce", "Tele-working", "VoIP"], "answer": 0, "explain": "E-Government là việc cơ quan nhà nước cung cấp thông tin và dịch vụ công cho người dân, doanh nghiệp qua môi trường mạng (mục 1.2)."}, {"topic": "1.3 An toàn lao động, bảo vệ môi trường", "q": "Bệnh/triệu chứng nào sau đây thường gặp ở người làm việc với máy tính nhiều giờ liên tục và sai tư thế?", "options": ["Bệnh bụi phổi silic", "Nhiễm độc chì", "Mỏi mắt, đau vai gáy và cột sống", "Điếc do tiếng ồn cường độ rất cao"], "answer": 2, "explain": "Làm việc lâu, sai tư thế gây mỏi mắt và các bệnh cơ xương khớp vùng cổ, vai, gáy, lưng; các bệnh còn lại đặc trưng ngành nghề khác (mục 1.3)."}, {"topic": "1.3 An toàn lao động, bảo vệ môi trường", "q": "Để giảm mỏi mắt và đau cổ khi làm việc với máy tính, cạnh trên của màn hình nên được đặt ở vị trí nào so với tầm mắt?", "options": ["Cao hơn tầm mắt khoảng 30 cm", "Cao hơn tầm mắt để phải hơi ngửa cổ", "Thấp hơn tầm ngực", "Ngang hoặc thấp hơn tầm mắt một chút"], "answer": 3, "explain": "Nguyên tắc ergonomics: cạnh trên màn hình ngang hoặc thấp hơn tầm mắt để tránh ngửa cổ và giảm mỏi mắt (mục 1.3)."}, {"topic": "1.3 An toàn lao động, bảo vệ môi trường", "q": "Pin, bo mạch và linh kiện điện tử hỏng chứa kim loại nặng (chì, thủy ngân, cadmium...). Cách xử lý phù hợp là gì?", "options": ["Bỏ chung vào thùng rác sinh hoạt để thu gom cùng lúc", "Thu gom và đưa đến điểm tiếp nhận hoặc đơn vị tái chế chuyên biệt", "Chôn xuống đất trong khuôn viên nhà", "Đốt cùng rác sinh hoạt để giảm thể tích"], "answer": 1, "explain": "Rác thải điện tử chứa chất độc hại nên phải được thu gom và xử lý/tái chế riêng, không thải chung với rác sinh hoạt (mục 1.3)."}, {"topic": "1.3 An toàn lao động, bảo vệ môi trường", "q": "Biện pháp nào sau đây giúp tiết kiệm điện năng khi sử dụng máy tính?", "options": ["Luôn đặt độ sáng màn hình ở mức tối đa", "Để máy chạy liên tục 24/7 ở chế độ hiệu năng cao", "Đặt chế độ tự tắt màn hình/Sleep khi không sử dụng", "Dùng màn hình bảo vệ (screensaver) động thay cho việc tắt màn hình"], "answer": 2, "explain": "Tự tắt màn hình hoặc chuyển Sleep khi nhàn rỗi giảm điện năng tiêu thụ; screensaver động không tiết kiệm điện (mục 1.3)."}, {"topic": "1.4 An toàn thông tin", "q": "Mật khẩu nào sau đây là mật khẩu mạnh nhất?", "options": ["T7#kR!9pLw$e", "P@ssw0rd", "Nguyen1990", "qwerty123"], "answer": 0, "explain": "Mật khẩu mạnh dài, ngẫu nhiên, kết hợp chữ hoa/thường, số, ký hiệu và không chứa từ thông dụng hay thông tin cá nhân (mục 1.4)."}, {"topic": "1.4 An toàn thông tin", "q": "Chức năng chính của tường lửa (firewall) là gì?", "options": ["Tăng tốc độ xử lý của CPU", "Tự động sao lưu dữ liệu lên đám mây", "Nén dữ liệu trước khi truyền qua mạng", "Kiểm soát, lọc lưu lượng mạng vào/ra theo các quy tắc định trước"], "answer": 3, "explain": "Tường lửa (của hệ điều hành hoặc phần mềm) cho phép hay chặn lưu lượng mạng theo quy tắc, bảo vệ máy tính khỏi truy cập trái phép (mục 1.4)."}, {"topic": "1.4 An toàn thông tin", "q": "Quy tắc sao lưu dữ liệu 3-2-1 là gì?", "options": ["3 bản sao trên cùng 1 ổ đĩa, sao lưu 2 lần mỗi ngày", "3 bản sao dữ liệu, trên 2 loại phương tiện lưu trữ khác nhau, trong đó 1 bản đặt ở vị trí khác", "3 ổ cứng, 2 mật khẩu và 1 phần mềm diệt virus", "Sao lưu 3 lần mỗi tuần, 2 lần mỗi tháng, 1 lần mỗi năm"], "answer": 1, "explain": "Quy tắc 3-2-1 là thực hành chuẩn cho sao lưu dự phòng (ổ cứng ngoài, DVD, USB, đám mây) như giáo trình nêu (mục 1.4)."}, {"topic": "1.4 An toàn thông tin", "q": "Loại mã độc có khả năng tự nhân bản và lây lan qua mạng mà không cần gắn vào tập tin chủ là:", "options": ["Spyware", "Adware", "Worm", "Trojan"], "answer": 2, "explain": "Worm tự sao chép và lan truyền qua mạng độc lập; Trojan ngụy trang chứ không tự nhân bản (mục 1.4)."}, {"topic": "1.4 An toàn thông tin", "q": "Phần mềm lén theo dõi hoạt động của người dùng (thói quen duyệt web, thông tin đăng nhập) rồi gửi cho bên thứ ba là:", "options": ["Spyware", "Adware", "Worm", "Virus"], "answer": 0, "explain": "Spyware là phần mềm gián điệp thu thập thông tin người dùng; Adware chủ yếu hiển thị quảng cáo (mục 1.4)."}, {"topic": "1.5 Pháp luật trong sử dụng CNTT", "q": "Theo Luật Sở hữu trí tuệ của Việt Nam, chương trình máy tính được bảo hộ như:", "options": ["Sáng chế", "Nhãn hiệu", "Kiểu dáng công nghiệp", "Tác phẩm văn học (quyền tác giả)"], "answer": 3, "explain": "Luật Sở hữu trí tuệ bảo hộ chương trình máy tính như tác phẩm văn học, dù ở dạng mã nguồn hay mã máy (mục 1.5)."}, {"topic": "1.5 Pháp luật trong sử dụng CNTT", "q": "Cài đặt và sử dụng bản phần mềm thương mại đã bị bẻ khóa (crack) mà không có giấy phép là hành vi gì?", "options": ["Hợp pháp nếu chỉ dùng cá nhân, không kinh doanh", "Vi phạm bản quyền phần mềm", "Được phép nếu phần mềm đã ngừng cập nhật", "Hợp pháp nếu tải từ website nước ngoài"], "answer": 1, "explain": "Sử dụng phần mềm khi không có giấy phép của chủ sở hữu là vi phạm bản quyền, bất kể mục đích hay nguồn tải (mục 1.5)."}, {"topic": "1.5 Pháp luật trong sử dụng CNTT", "q": "Hành vi nào sau đây thể hiện sự tôn trọng dữ liệu của người khác?", "options": ["Mở xem tập tin cá nhân trên máy đồng nghiệp đang bỏ quên chưa khóa", "Chia sẻ danh sách thông tin liên hệ của khách hàng cho người quen khi họ nhờ", "Chỉ truy cập, sao chép hoặc chia sẻ dữ liệu khi được chủ sở hữu cho phép", "Dùng chung tài khoản đăng nhập của người khác cho tiện công việc"], "answer": 2, "explain": "Tôn trọng dữ liệu của người khác nghĩa là không truy cập, sao chép, phát tán khi chưa được phép, phù hợp quy định bảo vệ dữ liệu cá nhân, tổ chức (mục 1.5)."}], "cards": [{"topic": "1.1.1 Phần cứng", "front": "CPU (Central Processing Unit) là gì?", "back": "Bộ xử lý trung tâm, tiếp nhận và xử lý lệnh cùng dữ liệu đầu vào; được gọi là bộ não của máy tính, là bộ phận quan trọng và đắt tiền nhất."}, {"topic": "1.1.1 Phần cứng", "front": "Hertz (Hz) đo đại lượng nào?", "back": "Tốc độ xung nhịp, tức số chu kỳ mỗi giây; CPU thường ghi bằng MHz hoặc GHz."}, {"topic": "1.1.1 Phần cứng", "front": "Bit và byte", "back": "Bit là đơn vị dữ liệu nhỏ nhất (0 hoặc 1); 1 byte = 8 bit."}, {"topic": "1.1.1 Phần cứng", "front": "Bảng quy đổi KB, MB, GB, TB (nhị phân)", "back": "1 KB = 1.024 byte; 1 MB = 1.024 KB; 1 GB = 1.024 MB; 1 TB = 1.024 GB."}, {"topic": "1.1.1 Phần cứng", "front": "Cách đổi số thập phân sang nhị phân", "back": "Chia liên tiếp cho 2, ghi các số dư rồi đọc ngược từ dưới lên. Ví dụ 13 → 1101."}, {"topic": "1.1.1 Phần cứng", "front": "RAM (Random Access Memory)", "back": "Bộ nhớ truy xuất ngẫu nhiên, lưu tạm chương trình và dữ liệu đang chạy; mất dữ liệu khi mất điện (volatile); tốc độ đo bằng nano giây."}, {"topic": "1.1.1 Phần cứng", "front": "ROM (Read Only Memory)", "back": "Bộ nhớ chỉ đọc, giữ thông tin khi mất nguồn điện; một số loại cho xóa và lập trình lại nhiều lần."}, {"topic": "1.1.1 Phần cứng", "front": "Thiết bị nhập và thiết bị xuất", "back": "Nhập: đưa thông tin vào máy tính (bàn phím, chuột, máy quét, webcam, đầu đọc mã vạch). Xuất: hiển thị thông tin từ máy tính (màn hình, máy in, máy chiếu, plotter)."}, {"topic": "1.1.1 Phần cứng", "front": "USB và HDMI viết tắt của gì?", "back": "USB: Universal Serial Bus (cổng nối tiếp đa năng). HDMI: High-Definition Multimedia Interface (truyền hình ảnh và âm thanh số độ phân giải cao)."}, {"topic": "1.1.1 Phần cứng", "front": "IDE, SATA, SCSI, MIDI", "back": "IDE: Integrated Drive Electronics. SATA: Serial Advanced Technology Attachment (eSATA là bản cho ổ ngoài). SCSI: Small Computer System Interface. MIDI: cổng kết nối nhạc cụ điện tử."}, {"topic": "1.1.2 Phần mềm", "front": "Phần mềm hệ thống và phần mềm ứng dụng", "back": "Hệ thống: điều khiển phần cứng, là nền cho ứng dụng (Windows, Linux, UNIX, macOS, MS-DOS). Ứng dụng: giúp người dùng làm việc hiệu quả (Office, đồ họa, đa phương tiện)."}, {"topic": "1.1.2 Phần mềm", "front": "Freeware, Shareware, Open source", "back": "Freeware: dùng miễn phí. Shareware: dùng thử có giới hạn rồi phải trả phí. Open source: công khai mã nguồn, dùng và sửa theo giấy phép."}, {"topic": "1.1.3 Hiệu năng", "front": "Bốn yếu tố quyết định hiệu năng máy tính (theo giáo trình)", "back": "Tốc độ CPU; dung lượng bộ nhớ; tốc độ ổ cứng; tốc độ mạch tăng tốc đồ họa."}, {"topic": "1.1.4 Mạng máy tính", "front": "Phân biệt LAN, MAN, WAN", "back": "LAN: mạng cục bộ (tòa nhà, văn phòng). MAN: mạng đô thị. WAN: mạng diện rộng (quốc gia, quốc tế), Internet là ví dụ điển hình."}, {"topic": "1.1.4 Mạng máy tính", "front": "Đơn vị đo tốc độ đường truyền và cách quy đổi", "back": "bps (bit/giây), Kbps, Mbps, Gbps. Chia 8 để ra byte/giây: 8 Mbps = 1 MB/s."}, {"topic": "1.1.4 Mạng máy tính", "front": "ISP là gì?", "back": "Internet Service Provider, nhà cung cấp dịch vụ Internet: cung cấp kết nối và truy cập Internet (ví dụ VNPT, Viettel, FPT)."}, {"topic": "1.2 Ứng dụng CNTT-TT", "front": "E-Commerce, E-Banking, E-Government", "back": "Thương mại điện tử (mua bán qua mạng); ngân hàng điện tử (giao dịch ngân hàng qua mạng); chính phủ điện tử (dịch vụ công trực tuyến)."}, {"topic": "1.2 Ứng dụng CNTT-TT", "front": "Tele-working và Tele-conference", "back": "Tele-working: làm việc từ xa qua mạng. Tele-conference: hội nghị/họp từ xa có âm thanh, hình ảnh qua mạng."}, {"topic": "1.2 Ứng dụng CNTT-TT", "front": "SMS, IM, VoIP", "back": "SMS: Short Message Service (tin nhắn ngắn qua mạng di động). IM: Instant Messaging (nhắn tin tức thời qua Internet). VoIP: truyền thoại qua mạng IP."}, {"topic": "1.3 An toàn lao động, môi trường", "front": "Bệnh thường gặp khi dùng máy tính và cách phòng ngừa", "back": "Mỏi mắt, đau vai gáy và cột sống, chấn thương do thao tác lặp lại ở tay. Phòng ngừa: ngồi đúng tư thế, nghỉ giải lao, quy tắc 20-20-20 (mỗi 20 phút nhìn vật cách ~6 m trong 20 giây)."}, {"topic": "1.3 An toàn lao động, môi trường", "front": "Rác thải điện tử", "back": "Thiết bị, pin, linh kiện điện tử hỏng/bỏ đi chứa kim loại nặng độc hại; phải thu gom và tái chế riêng, không vứt chung rác sinh hoạt."}, {"topic": "1.3 An toàn lao động, môi trường", "front": "Ô nhiễm ánh sáng, tiếng ồn, nhiệt độ tại nơi làm việc CNTT", "back": "Ba dạng ô nhiễm cần kiểm soát; bố trí chiếu sáng hợp lý, giảm ồn và giữ thông thoáng, làm mát phù hợp."}, {"topic": "1.4 An toàn thông tin", "front": "Virus, Worm, Trojan khác nhau thế nào?", "back": "Virus: gắn vào tập tin chủ để lây. Worm: tự nhân bản, lây qua mạng độc lập. Trojan: ngụy trang thành phần mềm hữu ích để đánh lừa người dùng."}, {"topic": "1.4 An toàn thông tin", "front": "Spyware và Adware", "back": "Spyware: lén thu thập thông tin người dùng gửi đi. Adware: tự hiển thị quảng cáo, thường đi kèm phần mềm khác."}, {"topic": "1.4 An toàn thông tin", "front": "Tường lửa (firewall)", "back": "Kiểm soát lưu lượng mạng vào/ra theo quy tắc; có tường lửa của hệ điều hành và phần mềm tường lửa."}, {"topic": "1.4 An toàn thông tin", "front": "Quy tắc sao lưu 3-2-1", "back": "3 bản sao dữ liệu, trên 2 loại phương tiện khác nhau, 1 bản để ở vị trí khác (off-site) như ổ cứng ngoài, USB hoặc đám mây (Google Drive, OneDrive)."}, {"topic": "1.4 An toàn thông tin", "front": "Mật khẩu mạnh cần đặc điểm gì?", "back": "Dài (nên từ 12 ký tự), kết hợp chữ hoa, chữ thường, số, ký hiệu; không dùng thông tin cá nhân; không dùng lại giữa các tài khoản."}, {"topic": "1.4 An toàn thông tin", "front": "Phishing là gì?", "back": "Hình thức lừa đảo giả mạo email, tin nhắn hoặc trang web uy tín để dụ người dùng tiết lộ mật khẩu và thông tin cá nhân."}, {"topic": "1.5 Pháp luật trong sử dụng CNTT", "front": "Copyright và License", "back": "Copyright: bản quyền/quyền tác giả của người sáng tạo. License: giấy phép quy định quyền và điều kiện người dùng được sử dụng phần mềm."}, {"topic": "1.5 Pháp luật trong sử dụng CNTT", "front": "Chương trình máy tính được bảo hộ theo pháp luật Việt Nam như thế nào?", "back": "Theo Luật Sở hữu trí tuệ, được bảo hộ như tác phẩm văn học (quyền tác giả), dù ở dạng mã nguồn hay mã máy."}]}, "IU02": {"questions": [{"topic": "2.1 Hệ điều hành", "q": "Chức năng nào sau đây thuộc về hệ điều hành?", "options": ["Soạn thảo và định dạng văn bản trên trang in", "Tính toán và lập biểu đồ từ bảng dữ liệu", "Quản lý thiết bị nhập, thiết bị xuất, thiết bị lưu trữ và các tập tin", "Duyệt web và gửi nhận thư điện tử"], "answer": 2, "explain": "Mục 2.1: hệ điều hành điều khiển giao tiếp với người dùng và quản lý thiết bị nhập/xuất/lưu trữ cùng các tập tin; các việc còn lại là của phần mềm ứng dụng."}, {"topic": "2.1 Hệ điều hành", "q": "MS-DOS có đặc điểm nào sau đây?", "options": ["Là phần mềm dựa trên văn bản, thực hiện chức năng bằng các dòng lệnh", "Là hệ điều hành đồ họa, dùng thiết bị trỏ để chọn biểu tượng", "Là hệ điều hành dành riêng cho điện thoại di động", "Là hệ điều hành do Apple phát triển cho máy Mac"], "answer": 0, "explain": "Mục 2.1: MS-DOS dựa trên văn bản và yêu cầu nhập dòng lệnh để thực hiện chức năng."}, {"topic": "2.1 Hệ điều hành", "q": "Giao diện đồ họa người dùng (GUI) cho phép người dùng làm gì?", "options": ["Chỉ điều khiển máy tính bằng cách gõ các dòng lệnh", "Chạy chương trình mà không cần hệ điều hành", "Tự động sao lưu dữ liệu lên Internet", "Dùng thiết bị trỏ để điểm chỉ và chọn chức năng dưới dạng nút hoặc biểu tượng"], "answer": 3, "explain": "Mục 2.1: GUI cho phép dùng thiết bị trỏ để chọn các chức năng hiển thị dưới dạng nút hoặc biểu tượng đại diện cho nhiệm vụ."}, {"topic": "2.1 Hệ điều hành", "q": "Hệ điều hành nào sau đây được thiết kế cho thiết bị di động?", "options": ["MS-DOS", "Android", "Windows Vista", "Mac OS"], "answer": 1, "explain": "Mục 2.1: Symbian, Android, iOS, Windows Phone, Blackberry OS là các hệ điều hành cho thiết bị di động."}, {"topic": "2.1 Hệ điều hành", "q": "Ký tự nào sau đây KHÔNG được dùng khi đặt tên tập tin trên máy PC?", "options": ["Dấu gạch dưới (_)", "Dấu hỏi chấm (?)", "Dấu gạch ngang (-)", "Dấu ngoặc đơn ( )"], "answer": 1, "explain": "Mục 2.1 (Khả năng và hạn chế): trên máy PC không được dùng các ký hiệu \\ ? : < > | trong tên tập tin."}, {"topic": "2.1 Hệ điều hành", "q": "Tình huống nào sau đây có thể gây lỗi hệ điều hành?", "options": ["Sao lưu dữ liệu định kỳ", "Gỡ bỏ chương trình bằng Uninstall a program", "Khởi động lại máy bằng lệnh Restart", "Mất nguồn điện hoặc tắt máy tính không đúng cách"], "answer": 3, "explain": "Mục 2.1 (Các vấn đề chung): mất nguồn điện, tắt máy không chính xác, virus, cài phần mềm quá nhiều hoặc sai cách, xóa tập tin hệ thống đều có thể gây lỗi."}, {"topic": "2.2 Desktop và cửa sổ", "q": "Vùng thông báo (Notification Area) trên Taskbar chứa gì?", "options": ["Các biểu tượng nhỏ báo tình trạng của chương trình hoặc là lối tắt để mở chương trình", "Nút Start và danh sách các chương trình đã cài đặt", "Nội dung của thư mục đang được mở", "Các nút thu nhỏ, phóng to và đóng cửa sổ"], "answer": 0, "explain": "Mục 2.2: Notification Area gồm các biểu tượng nhỏ thông báo tình trạng chương trình hoặc là đường đi tắt để mở chương trình."}, {"topic": "2.2 Desktop và cửa sổ", "q": "Tùy chọn tắt máy nào lưu lại những gì đang có trên màn hình làm việc rồi tắt máy để không tiêu thụ điện; khi bật lại và đăng nhập, màn hình trở về đúng nơi đã rời đi?", "options": ["Sleep", "Lock", "Hibernate", "Switch User"], "answer": 2, "explain": "Mục 2.2: Hibernate lưu trạng thái làm việc rồi tắt máy; Sleep chỉ giảm điện năng tiêu thụ chứ không tắt hoàn toàn."}, {"topic": "2.2 Desktop và cửa sổ", "q": "Lệnh nào cho phép chuyển sang tài khoản người dùng khác mà không cần đăng xuất khỏi tài khoản hiện tại?", "options": ["Log Off", "Lock", "Switch User", "Restart"], "answer": 2, "explain": "Mục 2.2: Switch User chuyển sang tài khoản khác mà không cần đăng xuất khỏi tài khoản hiện tại."}, {"topic": "2.2 Desktop và cửa sổ", "q": "Chọn Log Off trong các tùy chọn tắt máy sẽ có kết quả nào?", "options": ["Đóng tất cả các mục đang mở, thoát khỏi tài khoản hiện hành và trở về màn hình đăng nhập", "Ẩn màn hình làm việc phía sau màn hình đăng nhập nhưng vẫn giữ nguyên các chương trình đang chạy", "Tắt hoàn toàn nguồn điện của máy tính", "Chuyển sang tài khoản khác nhưng vẫn giữ phiên làm việc cũ"], "answer": 0, "explain": "Mục 2.2: Log Off kết thúc phiên người dùng; phương án B mô tả Lock, phương án D mô tả Switch User."}, {"topic": "2.2 Desktop và cửa sổ", "q": "Theo giáo trình, nếu máy đang ở trạng thái Sleep mà xảy ra mất điện thì điều gì xảy ra?", "options": ["Mọi dữ liệu được tự động lưu vào đĩa cứng", "Thông tin chưa lưu sẽ bị mất", "Máy tự chuyển sang Hibernate và lưu lại", "Máy tự khởi động lại và mở lại các chương trình"], "answer": 1, "explain": "Mục 2.2: nếu mất điện khi ở trạng thái Sleep, bất kỳ thông tin nào chưa được lưu sẽ bị mất."}, {"topic": "2.2 Desktop và cửa sổ", "q": "Nút nào trong nhóm nút điều khiển cửa sổ dùng để thu cửa sổ thành một nút trên thanh tác vụ (Taskbar)?", "options": ["Close", "Maximize", "Restore Down", "Minimize"], "answer": 3, "explain": "Mục 2.2: Minimize thu cửa sổ thành nút trên thanh tác vụ; Maximize hiển thị đầy màn hình; Restore khôi phục kích thước trước đó; Close đóng cửa sổ."}, {"topic": "2.2 Desktop và cửa sổ", "q": "Muốn di chuyển một cửa sổ bằng chuột, ta nhấn giữ và kéo tại thành phần nào?", "options": ["Address Bar", "Navigation Pane", "Scroll Box", "Title Bar"], "answer": 3, "explain": "Mục 2.2: đặt con trỏ chuột trên thanh tiêu đề (Title Bar) và kéo đến vị trí mới; chỉ di chuyển được khi cửa sổ không ở chế độ đầy màn hình."}, {"topic": "2.2 Desktop và cửa sổ", "q": "Để thay đổi đồng thời kích thước theo chiều ngang và chiều dọc của cửa sổ bằng chuột, ta đặt con trỏ chuột ở đâu rồi kéo?", "options": ["Ở giữa thanh tiêu đề", "Ở một góc bất kỳ của cửa sổ", "Trên thanh cuộn", "Trên thanh Address Bar"], "answer": 1, "explain": "Mục 2.2: đặt con trỏ ở bất kỳ góc nào của cửa sổ và kéo để đổi cả hai chiều; kéo cạnh chỉ đổi một chiều."}, {"topic": "2.2 Desktop và cửa sổ", "q": "Thành phần nào của cửa sổ Explorer hiển thị danh sách các thư mục và ổ đĩa có thể truy cập để xem nội dung?", "options": ["Navigation Pane", "Details Pane", "Title Bar", "Search box"], "answer": 0, "explain": "Mục 2.2: Navigation Pane hiển thị danh sách thư mục và ổ đĩa; Details Pane hiển thị thuộc tính, chi tiết của mục đang chọn."}, {"topic": "2.2 Desktop và cửa sổ", "q": "Thanh cuộn (Scroll Bars) xuất hiện trên cửa sổ trong trường hợp nào?", "options": ["Khi cửa sổ đang ở chế độ phóng to toàn màn hình", "Khi có từ hai chương trình trở lên đang chạy", "Khi cửa sổ quá nhỏ để hiển thị hết nội dung", "Khi thanh Taskbar bị ẩn"], "answer": 2, "explain": "Mục 2.2: nếu cửa sổ quá nhỏ để hiển thị tất cả nội dung, thanh cuộn xuất hiện ở cạnh phải hoặc cạnh đáy."}, {"topic": "2.3 Chạy ứng dụng", "q": "Nếu một tập tin hoặc lối tắt của chương trình được đặt trong thư mục Startup thì điều gì xảy ra?", "options": ["Chương trình tự động chạy mỗi khi khởi động Windows", "Chương trình chỉ chạy khi được mở từ hộp thoại Run", "Chương trình không bao giờ được chạy", "Chương trình bị gỡ cài đặt sau mỗi lần tắt máy"], "answer": 0, "explain": "Mục 2.3: đặt tập tin trong thư mục Startup nghĩa là chương trình tự động thực thi mỗi khi khởi động Windows."}, {"topic": "2.3 Chạy ứng dụng", "q": "Việc mở và làm việc đồng thời với nhiều chương trình, mỗi chương trình trong một cửa sổ riêng, được gọi là gì?", "options": ["Đa phương tiện", "Đa người dùng", "Đa ngôn ngữ", "Đa nhiệm (multitasking)"], "answer": 3, "explain": "Mục 2.3: làm việc với nhiều cửa sổ chương trình cùng lúc còn được gọi là đa nhiệm (multitasking)."}, {"topic": "2.3 Chạy ứng dụng", "q": "Lệnh Run thường được dùng trong trường hợp nào?", "options": ["Xóa vĩnh viễn một tập tin", "Sao lưu toàn bộ đĩa cứng", "Khởi động chương trình không có trong trình đơn Start", "Đổi tên hàng loạt tập tin"], "answer": 2, "explain": "Mục 2.3: dùng Run để khởi động chương trình khi nó không có trong trình đơn Start."}, {"topic": "2.3 Chạy ứng dụng", "q": "Tổ hợp phím tắt nào mở hộp thoại Run?", "options": ["Windows + E", "Windows + R", "Windows + D", "Windows + L"], "answer": 1, "explain": "Windows + R mở Run; Windows + E mở Explorer, Windows + D hiện Desktop, Windows + L khóa máy."}, {"topic": "2.3 Chạy ứng dụng", "q": "Phím nào được nhấn để mở cửa sổ trợ giúp Help and Support của Windows?", "options": ["F2", "F1", "F5", "F12"], "answer": 1, "explain": "Mục 2.3: mở Help bằng Help and Support từ Start hoặc nhấn F1 (phím trợ giúp chuẩn của Windows)."}, {"topic": "Phím tắt", "q": "Tổ hợp phím nào mở nhanh Task Manager (Trình quản lý tác vụ)?", "options": ["Ctrl + Alt + Tab", "Alt + F4", "Ctrl + Shift + Esc", "Windows + Tab"], "answer": 2, "explain": "Mục 2.2: Task Manager dùng để kiểm tra chương trình đang chạy hoặc đóng chương trình bị sự cố; Ctrl + Shift + Esc mở trực tiếp."}, {"topic": "Phím tắt", "q": "Tổ hợp phím nào dùng để chuyển qua lại giữa các chương trình đang mở?", "options": ["Ctrl + Esc", "Shift + Tab", "Alt + F4", "Alt + Tab"], "answer": 3, "explain": "Mục 2.3: Alt + Tab chuyển giữa các chương trình đang chạy; Alt + F4 đóng cửa sổ, Ctrl + Esc mở trình đơn Start."}, {"topic": "Phím tắt", "q": "Phím tắt nào dùng để chọn tất cả tập tin và thư mục trong cửa sổ đang mở?", "options": ["Ctrl + A", "Ctrl + S", "Ctrl + Z", "Ctrl + P"], "answer": 0, "explain": "Mục 2.4: Select All bằng Ctrl + A; Ctrl + S là Save, Ctrl + Z là Undo, Ctrl + P là Print."}, {"topic": "Phím tắt", "q": "Để di chuyển (move) tập tin sang thư mục khác bằng phím tắt, thao tác nào đúng?", "options": ["Ctrl + C ở vị trí cũ, rồi Ctrl + V ở vị trí mới", "Ctrl + V ở vị trí cũ, rồi Ctrl + X ở vị trí mới", "Ctrl + Z ở vị trí cũ, rồi Ctrl + Y ở vị trí mới", "Ctrl + X ở vị trí cũ, rồi Ctrl + V ở vị trí mới"], "answer": 3, "explain": "Mục 2.4: di chuyển dùng Cut rồi Paste (Ctrl + X, Ctrl + V); Ctrl + C rồi Ctrl + V là sao chép."}, {"topic": "2.4 Tập tin và thư mục", "q": "Loại tập tin nào chứa thông tin do người dùng nhập vào và lưu trong ứng dụng (ví dụ văn bản, bảng tính)?", "options": ["Data File (tập tin dữ liệu)", "Application File (tập tin chương trình)", "System File (tập tin hệ thống)", "Shortcut (biểu tượng tắt)"], "answer": 0, "explain": "Mục 2.4: Data File chứa thông tin được nhập vào và lưu trong ứng dụng; Application File và System File chứa hướng dẫn cho bộ vi xử lý."}, {"topic": "2.4 Tập tin và thư mục", "q": "Các tập tin chương trình (Application File) thường được lưu trong thư mục chương trình nằm trong thư mục nào?", "options": ["Recycle Bin", "Desktop", "Program Files", "Documents"], "answer": 2, "explain": "Mục 2.4: tập tin chương trình được lưu trong thư mục chương trình nằm trong thư mục Program Files."}, {"topic": "2.4 Tập tin và thư mục", "q": "Biểu tượng có mũi tên nhỏ ở góc dưới bên trái là gì?", "options": ["Tập tin bị hỏng", "Biểu tượng tắt (shortcut) đến vị trí lưu của mục gốc", "Tập tin có thuộc tính chỉ đọc", "Tập tin đã bị xóa vào Recycle Bin"], "answer": 1, "explain": "Mục 2.4: mũi tên nhỏ ở góc dưới bên trái đại diện cho biểu tượng tắt (shortcut) đến vị trí lưu mục."}, {"topic": "2.4 Tập tin và thư mục", "q": "Khi xóa một biểu tượng tắt (shortcut) trên Desktop thì điều gì xảy ra?", "options": ["Tập tin hoặc chương trình gốc cũng bị xóa", "Toàn bộ thư mục chứa tập tin gốc bị xóa", "Chỉ shortcut bị xóa, tập tin hoặc chương trình gốc vẫn còn", "Chương trình bị gỡ cài đặt khỏi máy"], "answer": 2, "explain": "Mục 2.4: xóa shortcut chỉ xóa lối tắt, không xóa tập tin thực tế; ngược lại xóa biểu tượng của tập tin thật sẽ xóa tập tin đó."}, {"topic": "2.4 Tập tin và thư mục", "q": "Để hiển thị phần mở rộng (extension) của tập tin, trong Folder and Search Options, tab View, mục Advanced settings, ta bỏ chọn tùy chọn nào?", "options": ["Show hidden files, folders, and drives", "Hide extensions for known file types", "Hide protected operating system files (Recommended)", "Display file size information in folder tips"], "answer": 1, "explain": "Mục 2.4: mặc định Windows ẩn phần mở rộng; bỏ chọn Hide extensions for known file types để hiển thị."}, {"topic": "2.4 Tập tin và thư mục", "q": "Để chọn nhiều tập tin KHÔNG liên tiếp nhau, ta giữ phím nào trong khi nhấp chọn từng tập tin?", "options": ["Ctrl", "Shift", "Alt", "Tab"], "answer": 0, "explain": "Mục 2.4: giữ Ctrl để chọn các mục không liên tiếp; giữ Shift để chọn nhiều mục liên tiếp từ mục đầu đến mục cuối."}, {"topic": "2.4 Tập tin và thư mục", "q": "Khi kéo thả tập tin sang một vị trí khác trên CÙNG ổ đĩa, muốn sao chép (thay vì di chuyển) thì phải giữ phím nào khi kéo?", "options": ["Shift", "Alt", "Tab", "Ctrl"], "answer": 3, "explain": "Mục 2.4: sao chép trong cùng một ổ đĩa thì nhấn Ctrl khi kéo tập tin hoặc thư mục vào vị trí mới."}, {"topic": "2.4 Tập tin và thư mục", "q": "Kéo thả một tập tin từ ổ đĩa này sang ổ đĩa khác thì mặc định Windows sẽ làm gì?", "options": ["Tự động sao chép tập tin", "Di chuyển tập tin và xóa bản gốc", "Tạo shortcut tại vị trí mới", "Không cho phép thực hiện thao tác"], "answer": 0, "explain": "Mục 2.4: kéo giữa các ổ đĩa khác nhau thì Windows tự động sao chép, trừ khi nhấn Shift khi kéo (khi đó là di chuyển)."}, {"topic": "2.4 Tập tin và thư mục", "q": "Phím nào kích hoạt chế độ đổi tên (Rename) cho tập tin hoặc thư mục đang được chọn?", "options": ["F1", "F5", "F2", "F4"], "answer": 2, "explain": "Mục 2.4: chọn tập tin hoặc thư mục rồi nhấn F2 để vào Edit mode; khi đổi tên phải giữ nguyên phần mở rộng."}, {"topic": "2.4 Tập tin và thư mục", "q": "Trong hộp thoại Properties của tập tin, tab nào hiển thị loại tập tin, vị trí, kích thước, ngày tạo, ngày sửa đổi, ngày truy cập và các thuộc tính như Read-only, Hidden?", "options": ["Security", "Details", "Previous Versions", "General"], "answer": 3, "explain": "Mục 2.4: tab General hiển thị loại, vị trí, kích thước, các mốc ngày và thuộc tính chỉ đọc hoặc ẩn; Security nói về quyền truy cập."}, {"topic": "2.4 Tập tin và thư mục", "q": "Tab nào trong Properties của thư mục cho phép chia sẻ thư mục với những người khác trên mạng?", "options": ["Security", "Sharing", "Customize", "General"], "answer": 1, "explain": "Mục 2.4: Sharing chia sẻ thư mục trên mạng; Security cho biết ai có quyền truy cập; Customize thay đổi cách thư mục hiển thị."}, {"topic": "2.4 Tập tin và thư mục", "q": "Chế độ xem nào hiển thị nội dung thư mục kèm thông tin chi tiết (kích thước, loại, ngày sửa đổi) và cho phép sắp xếp bằng cách nhấp tiêu đề cột?", "options": ["Tiles", "List", "Small Icons", "Details"], "answer": 3, "explain": "Mục 2.4: chế độ Details liệt kê nội dung thư mục với thông tin chi tiết; dùng tiêu đề cột để sắp xếp."}, {"topic": "2.4 Tập tin và thư mục", "q": "Khi sao chép tập tin vào thư mục đã có tập tin cùng tên, Windows xử lý thế nào?", "options": ["Tự động ghi đè mà không thông báo", "Hiển thị thông báo để người dùng chọn thay thế, bỏ qua hoặc giữ cả hai bản (Windows thêm số vào cuối tên)", "Tự động xóa tập tin mới sao chép", "Tự động đổi phần mở rộng của tập tin mới"], "answer": 1, "explain": "Mục 2.4: Windows kiểm tra tên trùng và hiện thông báo; có thể giữ cả hai bản và Windows tạo số ở cuối tên để phân biệt."}, {"topic": "2.4 Tập tin và thư mục", "q": "Đường dẫn (path) của một tập tin cho biết điều gì?", "options": ["Dung lượng còn trống của ổ đĩa", "Chương trình dùng để mở tập tin", "Lộ trình chính xác qua các cấp thư mục để đến vị trí của tập tin", "Ngày tạo và ngày sửa đổi cuối cùng của tập tin"], "answer": 2, "explain": "Mục 2.4: đường dẫn nêu rõ lộ trình chính xác cần theo để đến vị trí của tập tin trong cấu trúc phân cấp thư mục."}, {"topic": "2.5 Recycle Bin", "q": "Tập tin bị xóa từ nơi nào sau đây sẽ bị xóa vĩnh viễn, không thể khôi phục từ Recycle Bin?", "options": ["Ổ đĩa mạng hoặc ổ đĩa lưu trữ bên ngoài", "Đĩa cứng cục bộ của máy", "Thư mục Documents trên đĩa cứng cục bộ", "Màn hình Desktop của máy"], "answer": 0, "explain": "Mục 2.5: Recycle Bin chỉ lưu tạm mục xóa từ đĩa cứng cục bộ; mục xóa từ đĩa ngoài hoặc ổ đĩa mạng bị xóa vĩnh viễn."}, {"topic": "2.5 Recycle Bin", "q": "Muốn xóa vĩnh viễn một tập tin và bỏ qua Recycle Bin, ta giữ phím nào khi thực hiện lệnh xóa?", "options": ["Ctrl", "Shift", "Alt", "Tab"], "answer": 1, "explain": "Mục 2.5: nhấn Shift khi xóa (Shift + Delete) để xóa vĩnh viễn, bỏ qua Recycle Bin."}, {"topic": "2.5 Recycle Bin", "q": "Lệnh Restore trong Recycle Bin có tác dụng gì?", "options": ["Xóa vĩnh viễn mục đang chọn", "Chuyển mục đang chọn ra màn hình Desktop", "Khôi phục mục đã xóa về vị trí ban đầu", "Làm rỗng toàn bộ Recycle Bin"], "answer": 2, "explain": "Mục 2.5: có thể khôi phục tập tin hoặc thư mục đã xóa về vị trí ban đầu bằng Restore."}, {"topic": "2.5 Recycle Bin", "q": "Khi Recycle Bin bị đầy, Windows sẽ làm gì?", "options": ["Tự động xóa các tập tin và thư mục cũ để giải phóng chỗ cho các mục mới", "Không cho phép xóa thêm bất kỳ tập tin nào", "Tự động xóa ngay các mục mới nhất vừa đưa vào", "Tự khởi động lại máy tính"], "answer": 0, "explain": "Mục 2.5: nếu Recycle Bin đầy, Windows tự động xóa các tập tin và thư mục cũ để giải phóng đủ không gian cho mục mới."}, {"topic": "2.5 Recycle Bin", "q": "Thao tác nào sau đây chuyển tập tin trên đĩa cứng vào Recycle Bin (còn khôi phục được)?", "options": ["Nhấn Shift + Delete", "Xóa tập tin nằm trên ổ USB", "Chọn Empty Recycle Bin", "Chọn tập tin trên đĩa cứng rồi nhấn Delete"], "answer": 3, "explain": "Mục 2.5: xóa bằng Delete, menu chuột phải hoặc kéo vào Recycle Bin đưa mục từ đĩa cứng cục bộ vào Recycle Bin; các phương án còn lại xóa vĩnh viễn."}, {"topic": "2.6 Control Panel và máy in", "q": "Muốn đổi hình nền Desktop hoặc screen saver, ta vào nhóm nào trong Control Panel?", "options": ["Appearance and Personalization", "Network and Internet", "User Accounts", "Ease of Access"], "answer": 0, "explain": "Mục 2.6: Appearance and Personalization dùng để tùy chỉnh màn hình với screen saver, hình nền máy tính và các thiết lập tương tự."}, {"topic": "2.6 Control Panel và máy in", "q": "Muốn thay đổi định dạng ngày, giờ, tiền tệ hoặc số theo khu vực hay ngôn ngữ, ta vào nhóm nào trong Control Panel?", "options": ["Hardware and Sound", "Programs", "Clock, Language, and Region", "Security"], "answer": 2, "explain": "Mục 2.6: Clock, Language, and Region thay đổi ngày, thời gian, tiền tệ hoặc số theo tiêu chuẩn khu vực hay ngôn ngữ."}, {"topic": "2.6 Control Panel và máy in", "q": "Muốn thay đổi các thiết lập của chuột, ta vào nhóm nào trong Control Panel?", "options": ["Programs", "Hardware and Sound", "Network and Internet", "User Accounts"], "answer": 1, "explain": "Mục 2.6: Start > Control Panel > Hardware and Sound > Mouse."}, {"topic": "2.6 Control Panel và máy in", "q": "Cách nào sau đây mở được cửa sổ Personalization để tùy chỉnh hiển thị Desktop?", "options": ["Nhấp chuột phải vào Taskbar và chọn Properties", "Nhấp chuột phải vào biểu tượng Recycle Bin", "Nhấp đúp vào nút Start", "Nhấp chuột phải vào vùng trống của Desktop và chọn Personalize"], "answer": 3, "explain": "Mục 2.6: nhấp chuột phải trên Desktop, chọn Personalize (hoặc Control Panel > Appearance and Personalization > Personalization)."}, {"topic": "2.6 Control Panel và máy in", "q": "Ngày và giờ của hệ thống được lấy từ đâu?", "options": ["Từ ổ đĩa cứng", "Từ card màn hình", "Từ đồng hồ hoạt động bằng pin bên trong máy tính", "Từ chuột và bàn phím"], "answer": 2, "explain": "Mục 2.6: ngày và thời gian thiết lập được lấy từ đồng hồ hoạt động bằng pin bên trong máy tính."}, {"topic": "2.6 Control Panel và máy in", "q": "Lệnh nào dùng để đặt một máy in làm máy in mặc định (máy in mặc định được đánh dấu kiểm trong danh sách)?", "options": ["Set as Default Printer", "Printing Preferences", "See what's printing", "Add a printer"], "answer": 0, "explain": "Mục 2.6: máy in có dấu kiểm là máy in mặc định; đổi bằng cách chọn Set as Default Printer."}, {"topic": "2.6 Control Panel và máy in", "q": "Sau khi gửi lệnh in, ta dùng công cụ nào để kiểm tra tình trạng in hoặc hủy yêu cầu in?", "options": ["Recycle Bin", "Folder Options", "Windows Registry", "Hàng đợi in (print queue)"], "answer": 3, "explain": "Mục 2.6: sau khi gửi tài liệu in, dùng hàng đợi in để kiểm tra tình trạng in ấn tài liệu hoặc hủy bỏ yêu cầu in."}, {"topic": "2.6 Control Panel và máy in", "q": "Trước khi thay đổi thiết lập trong Control Panel, nên làm gì?", "options": ["Đăng xuất tất cả các tài khoản người dùng khác", "Ghi lại các thiết lập ban đầu để có thể quay về nếu thay đổi không hiệu quả", "Tắt và bật lại máy in", "Gỡ bỏ toàn bộ phần mềm ứng dụng"], "answer": 1, "explain": "Mục 2.6: cần hiểu rõ từng tùy chọn và ghi lại các thiết lập ban đầu trước khi thay đổi để quay về khi thay đổi không đạt yêu cầu."}, {"topic": "2.7 Cài đặt và gỡ bỏ", "q": "Cách đúng để gỡ bỏ một chương trình đã cài đặt là gì?", "options": ["Dùng Uninstall a program trong Control Panel rồi chọn chương trình cần gỡ", "Xóa thư mục chương trình bằng Windows Explorer", "Kéo biểu tượng chương trình trên Desktop vào Recycle Bin", "Xóa shortcut của chương trình trong trình đơn Start"], "answer": 0, "explain": "Mục 2.7: luôn dùng Uninstall a program trong Control Panel, không chỉ xóa tập tin chương trình bằng Explorer."}, {"topic": "2.7 Cài đặt và gỡ bỏ", "q": "Vì sao không nên chỉ xóa các tập tin chương trình bằng Explorer để gỡ bỏ chương trình?", "options": ["Vì Explorer không cho phép xóa thư mục Program Files", "Vì làm vậy sẽ xóa luôn hệ điều hành", "Vì thông tin cấu hình trong Windows Registry cần được điều chỉnh, nếu không có thể gây lỗi cho phần mềm khác", "Vì các tập tin sẽ tự động được khôi phục từ Recycle Bin"], "answer": 2, "explain": "Mục 2.7: thông tin cấu hình trong Windows Registry cần được điều chỉnh; bỏ sót có thể gây vấn đề khi cài đặt lại, nâng cấp hoặc với phần mềm khác."}, {"topic": "2.7 Cài đặt và gỡ bỏ", "q": "Nếu không thể cài đặt hoặc tải về một chương trình, nguyên nhân có thể là gì?", "options": ["Recycle Bin đang trống", "Tài khoản người dùng không có đủ quyền cài đặt", "Màn hình Desktop có quá nhiều biểu tượng", "Chuột chưa được cấu hình tốc độ"], "answer": 1, "explain": "Mục 2.7: nếu không thể cài đặt hoặc tải chương trình, có thể tài khoản người dùng không có quyền; ngoài ra còn do bản sao lỗi hoặc xung đột phần cứng, phần mềm."}], "cards": [{"topic": "Phím tắt", "front": "Ctrl + C", "back": "Copy: sao chép mục đang chọn vào Clipboard."}, {"topic": "Phím tắt", "front": "Ctrl + X", "back": "Cut: cắt mục đang chọn; dùng cùng Ctrl + V để di chuyển."}, {"topic": "Phím tắt", "front": "Ctrl + V", "back": "Paste: dán nội dung trong Clipboard vào vị trí hiện tại."}, {"topic": "Phím tắt", "front": "Ctrl + Z", "back": "Undo: hoàn tác thao tác vừa thực hiện (Ctrl + Y là Redo, làm lại)."}, {"topic": "Phím tắt", "front": "Ctrl + A", "back": "Select All: chọn tất cả tập tin và thư mục trong cửa sổ."}, {"topic": "Phím tắt", "front": "Ctrl + S", "back": "Save: lưu tài liệu đang mở."}, {"topic": "Phím tắt", "front": "Alt + Tab", "back": "Chuyển qua lại giữa các chương trình/cửa sổ đang mở."}, {"topic": "Phím tắt", "front": "Alt + F4", "back": "Đóng cửa sổ hoặc chương trình đang hoạt động."}, {"topic": "Phím tắt", "front": "Windows + D", "back": "Thu nhỏ tất cả cửa sổ để hiện Desktop; nhấn lại để khôi phục."}, {"topic": "Phím tắt", "front": "Windows + E", "back": "Mở Windows Explorer (File Explorer)."}, {"topic": "Phím tắt", "front": "Windows + R", "back": "Mở hộp thoại Run."}, {"topic": "Phím tắt", "front": "Windows + L", "back": "Khóa máy (Lock), quay về màn hình đăng nhập."}, {"topic": "Phím tắt", "front": "Ctrl + Shift + Esc", "back": "Mở trực tiếp Task Manager."}, {"topic": "Phím tắt", "front": "Shift + Delete", "back": "Xóa vĩnh viễn mục đang chọn, bỏ qua Recycle Bin."}, {"topic": "Phím tắt", "front": "F2", "back": "Đổi tên (Rename) tập tin hoặc thư mục đang chọn."}, {"topic": "Phím tắt", "front": "F5", "back": "Làm mới (Refresh) nội dung cửa sổ hiện tại."}, {"topic": "Phím tắt", "front": "Alt + Enter", "back": "Mở hộp thoại Properties của mục đang chọn trong Explorer."}, {"topic": "Phím tắt", "front": "Ctrl + Shift + N", "back": "Tạo thư mục mới (New folder) trong Explorer."}, {"topic": "2.1 Hệ điều hành", "front": "MS-DOS khác Windows ở điểm nào?", "back": "MS-DOS dựa trên văn bản, thực hiện chức năng bằng dòng lệnh; Windows và Mac OS dùng giao diện đồ họa (GUI) với thiết bị trỏ và biểu tượng."}, {"topic": "2.1 Hệ điều hành", "front": "Ký tự không được dùng khi đặt tên tập tin trên máy PC (theo giáo trình)", "back": "\\ ? : < > |  (Windows còn cấm thêm / * và dấu nháy kép). Trên máy Mac không được dùng dấu :"}, {"topic": "2.2 Desktop và cửa sổ", "front": "Phân biệt Sleep và Hibernate", "back": "Sleep: giảm điện năng tiêu thụ, mất điện thì thông tin chưa lưu bị mất. Hibernate: lưu trạng thái làm việc rồi tắt máy, không tiêu thụ điện, bật lại trở về đúng nơi đã rời đi."}, {"topic": "2.2 Desktop và cửa sổ", "front": "Phân biệt Lock, Log Off và Switch User", "back": "Lock: ẩn màn hình làm việc sau màn hình đăng nhập. Log Off: đóng mọi mục và thoát tài khoản hiện hành. Switch User: sang tài khoản khác mà không đăng xuất tài khoản hiện tại."}, {"topic": "2.2 Desktop và cửa sổ", "front": "Alt + Space", "back": "Mở menu điều khiển cửa sổ (Move, Size, Minimize, Maximize, Close); chọn Move hoặc Size rồi dùng phím mũi tên. Chỉ di chuyển được khi cửa sổ không ở chế độ đầy màn hình."}, {"topic": "2.3 Chạy ứng dụng", "front": "Thư mục Startup dùng để làm gì?", "back": "Chương trình hoặc lối tắt đặt trong Startup tự động chạy mỗi khi khởi động Windows."}, {"topic": "2.3 Chạy ứng dụng", "front": "Cách mở Help của Windows", "back": "Nhấn F1 hoặc chọn Help and Support từ Start."}, {"topic": "2.3 Chạy ứng dụng", "front": "Cách xem phiên bản Windows đang dùng", "back": "Nhấn Windows + R, gõ winver rồi Enter: hộp About Windows hiển thị phiên bản."}, {"topic": "2.4 Tập tin và thư mục", "front": "Cách chọn nhiều tập tin liên tiếp và không liên tiếp", "back": "Liên tiếp: nhấp mục đầu, giữ Shift, nhấp mục cuối (hoặc kéo chuột quét vùng chọn - Lasso). Không liên tiếp: giữ Ctrl và nhấp từng mục."}, {"topic": "2.4 Tập tin và thư mục", "front": "Kéo thả tập tin: khi nào sao chép, khi nào di chuyển?", "back": "Cùng ổ đĩa: mặc định di chuyển, giữ Ctrl để sao chép. Khác ổ đĩa: mặc định sao chép, giữ Shift để di chuyển."}, {"topic": "2.4 Tập tin và thư mục", "front": "Cách hiển thị phần mở rộng (extension) của tập tin", "back": "Folder and Search Options > tab View > Advanced settings > bỏ chọn Hide extensions for known file types (mặc định Windows ẩn phần mở rộng)."}, {"topic": "2.4 Tập tin và thư mục", "front": "Ba loại tập tin: Application, Data, System", "back": "Application File: hướng dẫn cho bộ vi xử lý, lưu trong Program Files. Data File: thông tin người dùng nhập và lưu trong ứng dụng. System File: hướng dẫn chi tiết cho bộ vi xử lý, là một phần của hệ điều hành."}, {"topic": "2.4 Tập tin và thư mục", "front": "Nhận biết shortcut và hậu quả khi xóa", "back": "Biểu tượng có mũi tên nhỏ ở góc dưới bên trái; xóa shortcut chỉ xóa lối tắt, không xóa tập tin hoặc chương trình gốc."}, {"topic": "2.4 Tập tin và thư mục", "front": "Các chế độ xem (View) trong Explorer", "back": "Extra Large Icons, Large Icons, Medium Icons, Small Icons, List, Details, Tiles. Details: thông tin chi tiết, sắp xếp theo tiêu đề cột. Tiles: tên bên phải biểu tượng, kèm loại và kích thước."}, {"topic": "2.4 Tập tin và thư mục", "front": "Các tab trong Properties của thư mục và của tập tin", "back": "Thư mục: General, Sharing, Security, Previous Versions, Customize. Tập tin: General, Security, Details, Previous Versions. Mở bằng chuột phải > Properties."}, {"topic": "2.4 Tập tin và thư mục", "front": "Ký tự đại diện (wildcard) khi tìm tập tin", "back": "* thay cho nhiều ký tự bất kỳ, ? thay cho đúng một ký tự. Ví dụ *.jpg tìm mọi tập tin có đuôi .jpg."}, {"topic": "2.5 Recycle Bin", "front": "Recycle Bin: phạm vi, khôi phục, làm rỗng", "back": "Lưu tạm mục xóa từ đĩa cứng cục bộ; xóa từ ổ đĩa mạng hoặc đĩa ngoài là xóa vĩnh viễn. Khôi phục: chọn mục > Restore. Làm rỗng: Empty Recycle Bin. Khi đầy, Windows tự xóa các mục cũ."}, {"topic": "2.6 Control Panel và máy in", "front": "Đổi hình nền/screen saver và đổi ngày giờ/tiền tệ/khu vực nằm ở nhóm nào của Control Panel?", "back": "Appearance and Personalization (hình nền, screen saver). Clock, Language, and Region (ngày, giờ, tiền tệ, số theo khu vực hoặc ngôn ngữ)."}, {"topic": "2.6 Control Panel và máy in", "front": "Chuột, bàn phím, âm thanh, máy in nằm ở nhóm nào của Control Panel?", "back": "Hardware and Sound: Mouse, Keyboard, Sound, Printers."}, {"topic": "2.6 Control Panel và máy in", "front": "Cách đổi ngày giờ hệ thống", "back": "Nhấp vào đồng hồ ở vùng thông báo > Change date and time settings, hoặc Control Panel > Clock, Language, and Region > Date and Time. Ngày giờ lấy từ đồng hồ chạy pin trong máy; tab Internet Time đồng bộ với Internet."}, {"topic": "2.6 Control Panel và máy in", "front": "Máy in mặc định và hàng đợi in", "back": "Máy in mặc định có dấu kiểm; đặt bằng Set as Default Printer. Xem hoặc hủy lệnh in bằng See what's printing (hàng đợi in); chỉnh tính năng máy in bằng Printing Preferences hoặc Properties."}, {"topic": "2.7 Cài đặt và gỡ bỏ", "front": "Gỡ bỏ chương trình đúng cách", "back": "Control Panel > Uninstall a program > chọn chương trình > Uninstall. Không chỉ xóa tập tin bằng Explorer vì thông tin cấu hình còn nằm trong Windows Registry."}]}, "IU03": {"questions": [{"topic": "Tổng quan & gõ tiếng Việt", "q": "Theo giáo trình, hai bảng mã tiếng Việt thông dụng nhất hiện nay là:", "options": ["TCVN3 và VISCII", "Unicode và VNI Windows", "Unicode và TCVN3", "VNI Windows và VISCII"], "answer": 1, "explain": "Giáo trình mục 3.1 nêu Unicode (font Arial, Calibri, Tahoma...) và VNI Windows (font VNI-Times...) là hai bảng mã thông dụng nhất."}, {"topic": "Tổng quan & gõ tiếng Việt", "q": "Trong kiểu gõ Telex, để gõ chữ 'đ' ta nhấn liên tiếp các phím:", "options": ["d9", "dw", "df", "dd"], "answer": 3, "explain": "Telex: dd = đ (d9 là cách gõ của kiểu VNI), theo bảng quy tắc gõ ở mục 3.1."}, {"topic": "Tổng quan & gõ tiếng Việt", "q": "Trong kiểu gõ VNI, phím số nào dùng để đánh dấu nặng?", "options": ["5", "1", "3", "4"], "answer": 0, "explain": "VNI: 1 sắc, 2 huyền, 3 hỏi, 4 ngã, 5 nặng (mục 3.1; ví dụ 'Vie65t' = Việt)."}, {"topic": "Giao diện Word", "q": "Để khởi động Microsoft Word từ hộp thoại Run, ta gõ lệnh:", "options": ["excel", "powerpnt", "winword", "notepad"], "answer": 2, "explain": "Giáo trình mục 3.2, cách 2: Run rồi gõ winword (excel, powerpnt, notepad khởi động các chương trình khác)."}, {"topic": "Giao diện Word", "q": "Thanh nằm ở cuối cửa sổ Word, hiển thị thông tin như số trang, số từ, các nút chế độ xem và thanh Zoom là:", "options": ["Thanh tiêu đề (Title bar)", "Thanh trạng thái (Status bar)", "Thanh thước (Ruler)", "Thanh cuộn (Scroll bar)"], "answer": 1, "explain": "Status bar (thanh trạng thái) nằm dưới cùng cửa sổ Word (hình màn hình Word 2010, mục 3.2)."}, {"topic": "Thao tác tập tin", "q": "Phím tắt để mở một tài liệu Word có sẵn (File > Open) là:", "options": ["Ctrl+O", "Ctrl+N", "Ctrl+S", "Ctrl+P"], "answer": 0, "explain": "Giáo trình mục 3.2: mở văn bản bằng File > Open hoặc Ctrl+O (Ctrl+N tạo mới, Ctrl+S lưu, Ctrl+P in)."}, {"topic": "Thao tác tập tin", "q": "Phím tắt cho lệnh Save As (lưu tài liệu với tên hoặc định dạng khác) là:", "options": ["F4", "F7", "F5", "F12"], "answer": 3, "explain": "Giáo trình mục 3.2: File > Save As, phím tắt F12 (F7 là kiểm tra chính tả, F5 là Go To, F4 lặp lại thao tác cuối)."}, {"topic": "Thao tác tập tin", "q": "Khi lưu ở định dạng mặc định, tệp tài liệu Word 2010 có phần mở rộng là:", "options": [".doc", ".dotx", ".docx", ".rtf"], "answer": 2, "explain": "Giáo trình mục 3.2 lấy ví dụ Tailieu.docx; .doc là định dạng Word 97-2003, .dotx là Word Template."}, {"topic": "Thao tác tập tin", "q": "Để Word 2010 mặc định lưu theo định dạng Word 2003, vào File > Word Options > Save, tại mục 'Save files in this format' chọn:", "options": ["Word 97-2003 Document (*.doc)", "Word Template (*.dotx)", "Rich Text Format (*.rtf)", "Plain Text (*.txt)"], "answer": 0, "explain": "Đúng theo giáo trình mục 3.2 (lưu mặc định theo chương trình cũ)."}, {"topic": "Thao tác tập tin", "q": "Tùy chọn tự động sao lưu theo chu kỳ (AutoRecover) để giảm mất dữ liệu khi treo máy hoặc mất điện nằm ở nhóm nào của Word Options?", "options": ["Proofing", "Save", "Display", "Customize Ribbon"], "answer": 1, "explain": "Giáo trình mục 3.2: File > Word Options > Save (mục Save AutoRecover information every... minutes)."}, {"topic": "Quy tắc soạn thảo", "q": "Theo quy tắc soạn thảo văn bản, phím Enter được dùng để:", "options": ["Ngắt dòng trong cùng một đoạn", "Tạo khoảng trống giữa hai từ", "Canh giữa dòng văn bản", "Kết thúc một đoạn văn bản"], "answer": 3, "explain": "Giáo trình mục 3.2: không dùng Enter để ngắt dòng trong một đoạn; chỉ dùng Enter để kết thúc đoạn."}, {"topic": "Quy tắc soạn thảo", "q": "Câu nào sau đây được gõ đúng quy tắc về dấu câu?", "options": ["Hôm nay , tôi đi học .", "Hôm nay,tôi đi học.", "Hôm nay, tôi đi học.", "Hôm nay ,tôi đi học."], "answer": 2, "explain": "Giáo trình mục 3.2: dấu phẩy, chấm, chấm hỏi, chấm than, hai chấm gõ sát chữ bên trái và có một khoảng trắng bên phải."}, {"topic": "Di chuyển, chọn, xóa khối", "q": "Để đưa con trỏ về đầu văn bản, ta nhấn:", "options": ["Home", "Ctrl+Home", "Ctrl+End", "Page Up"], "answer": 1, "explain": "Giáo trình mục 3.2: Ctrl+Home về đầu văn bản, Ctrl+End về cuối văn bản; Home/End chỉ về đầu/cuối dòng."}, {"topic": "Di chuyển, chọn, xóa khối", "q": "Phím Backspace có tác dụng:", "options": ["Xóa ký tự liền bên trái vị trí con trỏ", "Xóa ký tự tại vị trí bên phải con trỏ", "Chuyển đổi giữa chế độ Insert và Overwrite", "Đưa con trỏ về đầu dòng"], "answer": 0, "explain": "Giáo trình mục 3.2: Backspace xóa ký tự liền trái con trỏ, còn Delete xóa ký tự bên phải con trỏ."}, {"topic": "Di chuyển, chọn, xóa khối", "q": "Tổ hợp phím chọn toàn bộ nội dung tài liệu là:", "options": ["Ctrl+Home", "Ctrl+E", "Ctrl+A", "Ctrl+D"], "answer": 2, "explain": "Kiến thức Word chuẩn (mục 3.2, chọn khối): Ctrl+A = Select All; Ctrl+E canh giữa, Ctrl+D mở hộp thoại Font."}, {"topic": "Di chuyển, chọn, xóa khối", "q": "Để chọn một khối văn bản liên tục bằng chuột: đặt con trỏ ở điểm đầu, giữ phím nào rồi click chuột ở điểm cuối?", "options": ["Ctrl", "Alt", "Tab", "Shift"], "answer": 3, "explain": "Giáo trình mục 3.2, chọn khối cách 2: giữ Shift rồi click ở điểm cuối của đoạn cần chọn."}, {"topic": "Chỉnh sửa văn bản", "q": "Tổ hợp phím hoàn tác (Undo) thao tác vừa thực hiện là:", "options": ["Ctrl+Y", "Ctrl+Z", "Ctrl+X", "Ctrl+V"], "answer": 1, "explain": "Kiến thức Word chuẩn: Ctrl+Z = Undo, Ctrl+Y = Redo (làm lại), Ctrl+X = cắt, Ctrl+V = dán."}, {"topic": "Định dạng ký tự", "q": "Phím tắt in nghiêng (Italic) là:", "options": ["Ctrl+I", "Ctrl+B", "Ctrl+U", "Ctrl+T"], "answer": 0, "explain": "Giáo trình mục 3.3.1: Ctrl+B in đậm, Ctrl+I in nghiêng, Ctrl+U gạch chân."}, {"topic": "Định dạng ký tự", "q": "Tổ hợp phím Ctrl+[ có tác dụng:", "options": ["Tăng cỡ chữ của vùng chọn lên 1 điểm", "Gạch chân vùng chọn", "Giảm cỡ chữ của vùng chọn đi 1 điểm", "Chuyển vùng chọn sang chữ thường"], "answer": 2, "explain": "Giáo trình mục 3.3.1: Ctrl+] và Ctrl+[ dùng để tăng và giảm cỡ chữ (mỗi lần 1 điểm)."}, {"topic": "Định dạng ký tự", "q": "Sau khi bật Text Highlight Color, muốn ngừng chế độ đánh dấu, ngoài việc chọn Stop Highlighting ta có thể nhấn phím:", "options": ["Enter", "Tab", "Delete", "Esc"], "answer": 3, "explain": "Giáo trình mục 3.3.1: ngừng chế độ đánh dấu bằng Stop Highlighting hoặc nhấn ESC."}, {"topic": "Định dạng ký tự", "q": "Hiệu ứng Superscript trong hộp thoại Font dùng để:", "options": ["Chuyển chữ thành dạng chỉ số trên (ví dụ m²)", "Chuyển chữ thành dạng chỉ số dưới (ví dụ H₂O)", "Kẻ một đường xuyên qua chữ", "Ẩn các ký tự đã chọn"], "answer": 0, "explain": "Giáo trình mục 3.3.1: Superscript = chỉ số trên, Subscript = chỉ số dưới, Strikethrough = kẻ đường xuyên qua chữ, Hidden = ẩn ký tự."}, {"topic": "Định dạng ký tự", "q": "Phím tắt mở hộp thoại Font là:", "options": ["Ctrl+F", "Ctrl+D", "Ctrl+H", "Ctrl+K"], "answer": 1, "explain": "Kiến thức Word chuẩn: Ctrl+D mở Font dialog (giáo trình mục 3.3.1 mở bằng mũi tên góc nhóm Font); Ctrl+F là Find, Ctrl+H là Replace, Ctrl+K là Hyperlink."}, {"topic": "Định dạng đoạn", "q": "Phím tắt đặt khoảng cách dòng 1.5 lines cho đoạn văn bản là:", "options": ["Ctrl+1", "Ctrl+2", "Ctrl+3", "Ctrl+5"], "answer": 3, "explain": "Kiến thức Word chuẩn (mục 3.3.2): Ctrl+1 = Single, Ctrl+5 = 1.5 lines, Ctrl+2 = Double."}, {"topic": "Định dạng đoạn", "q": "Phím tắt canh đều hai bên lề (Justify) cho đoạn văn bản là:", "options": ["Ctrl+E", "Ctrl+R", "Ctrl+J", "Ctrl+L"], "answer": 2, "explain": "Kiến thức Word chuẩn (mục 3.3.2): Ctrl+J = Justify, Ctrl+L = canh trái, Ctrl+E = canh giữa, Ctrl+R = canh phải."}, {"topic": "Định dạng đoạn", "q": "Trong Ribbon Page Layout, nhóm Paragraph, hai mục Before và After dùng để điều chỉnh:", "options": ["Khoảng cách trước và sau đoạn văn bản", "Thụt lề trái và thụt lề phải của đoạn", "Khoảng cách giữa các dòng trong đoạn", "Khoảng cách từ mép giấy đến nội dung"], "answer": 0, "explain": "Giáo trình mục 3.3.2: Before/After thay đổi khoảng cách trước hoặc sau đoạn; Left/Right mới là thụt lề trái/phải."}, {"topic": "Định dạng đoạn", "q": "Trong Drop Cap, chế độ 'In margin' đặt chữ cái đầu lớn ở vị trí nào?", "options": ["Bên trong khối văn bản, chiếm nhiều dòng", "Ở giữa trang giấy", "Nằm ngoài (bên trái) khối văn bản", "Ở cuối đoạn văn bản"], "answer": 2, "explain": "Giáo trình mục 3.3.2: Dropped = chữ nằm trong văn bản; In margin = chữ nằm ngoài (bên trái) văn bản."}, {"topic": "Định dạng đoạn", "q": "Để đóng khung và tô màu nền cho đoạn văn bản, trong nhóm Paragraph (tab Home) nhấn vào danh sách nút Border rồi chọn:", "options": ["Horizontal Line", "Borders and Shading", "Draw Table", "View Gridlines"], "answer": 1, "explain": "Giáo trình mục 3.3.2 (Border and Shading): chọn Borders and Shading trong danh sách của nút Border."}, {"topic": "Định dạng đoạn", "q": "Chức năng Columns của Word cho phép:", "options": ["Chèn bảng có nhiều cột", "Chia trang giấy thành nhiều trang", "Đánh số thứ tự cho các dòng trong đoạn", "Chia văn bản thành nhiều cột dạng cột báo chí"], "answer": 3, "explain": "Giáo trình mục 3.3.2: Column định dạng văn bản thành nhiều cột (dạng cột báo chí), khác với bảng (Table)."}, {"topic": "Định dạng đoạn", "q": "Để thuận tiện khi cài đặt điểm dừng Tab (Tab stops), nên bật hiển thị:", "options": ["Thước ngang (Ruler)", "Thanh trạng thái (Status bar)", "Thanh cuộn dọc (Scroll bar)", "Thanh tiêu đề (Title bar)"], "answer": 0, "explain": "Giáo trình mục 3.3.2: nên hiện thước ngang bằng nút View Ruler ở đầu trên thanh cuộn dọc rồi đặt tab trên thước."}, {"topic": "Bảng biểu", "q": "Trong bảng (Table), giao điểm của một dòng và một cột được gọi là:", "options": ["Trường (Field)", "Ô (Cell)", "Bản ghi (Record)", "Khung (Frame)"], "answer": 1, "explain": "Giáo trình mục 3.4.1: bảng gồm các cột (column) và dòng (row), giao giữa dòng và cột là ô (cell)."}, {"topic": "Bảng biểu", "q": "Khi nhấp chọn vào một bảng, các tab ngữ cảnh của Table Tools xuất hiện gồm:", "options": ["Home và Insert", "Format và Review", "Design và Layout", "References và Mailings"], "answer": 2, "explain": "Table Tools có hai tab ngữ cảnh Design và Layout (giáo trình mục 3.4.1 nhắc tab Design để chỉnh cấu trúc bảng)."}, {"topic": "Bảng biểu", "q": "Trong Table Style Options, tùy chọn Banded Rows có tác dụng:", "options": ["Nhấn mạnh hàng đầu tiên (tiêu đề)", "Nhấn mạnh hàng cuối cùng", "Nhấn mạnh cột đầu tiên", "Tô màu xen kẽ để phân biệt các hàng"], "answer": 3, "explain": "Giáo trình mục 3.4.1: Header Row nhấn mạnh hàng tiêu đề, Total Row nhấn mạnh hàng cuối, Banded Rows tô màu cách hàng."}, {"topic": "Bảng biểu", "q": "Trong nhóm Rows & Columns của bảng, lệnh Insert Left dùng để:", "options": ["Thêm hàng ở phía trên vị trí con trỏ", "Thêm cột ở bên trái vị trí con trỏ", "Thêm cột ở bên phải vị trí con trỏ", "Thêm hàng ở phía dưới vị trí con trỏ"], "answer": 1, "explain": "Giáo trình mục 3.4.1: Insert Above/Below thêm hàng trên/dưới; Insert Left/Right thêm cột bên trái/phải."}, {"topic": "Đối tượng đồ họa", "q": "Nút Shapes (chèn hình vẽ cơ bản) nằm trong nhóm nào của tab Insert (Word 2010)?", "options": ["Illustrations", "Text", "Symbols", "Header & Footer"], "answer": 0, "explain": "Giáo trình mục 3.4.3: Ribbon Insert, nhóm Illustrations, nhấn nút Shapes."}, {"topic": "Đối tượng đồ họa", "q": "Lệnh Send to Back trong nhóm Arrange của tab Format có tác dụng:", "options": ["Đặt đối tượng nằm trên các đối tượng khác", "Nhóm các đối tượng đã chọn", "Đặt đối tượng nằm dưới các đối tượng khác", "Chọn kiểu văn bản bao quanh đối tượng"], "answer": 2, "explain": "Giáo trình mục 3.4.2: Bring to Front đặt đối tượng lên trên, Send to Back đặt đối tượng xuống dưới; Text Wrapping mới là kiểu văn bản bao quanh."}, {"topic": "Đối tượng đồ họa", "q": "Nút WordArt (chữ nghệ thuật) nằm ở nhóm nào trên tab Insert?", "options": ["Illustrations", "Links", "Symbols", "Text"], "answer": 3, "explain": "Giáo trình mục 3.4.6: WordArt nằm trong nhóm Text của Ribbon Insert (WordArt được xử lý như một hình ảnh chèn vào văn bản)."}, {"topic": "Header/Footer & số trang", "q": "Để trang đầu tiên của tài liệu không hiển thị Header/Footer (hoặc số trang) giống các trang còn lại, trong Header & Footer Tools > Design ta chọn:", "options": ["Different First Page", "Different Odd & Even Pages", "Link to Previous", "Show Document Text"], "answer": 0, "explain": "Kiến thức Word chuẩn (mục 3.4.7): Different First Page cho phép trang đầu có Header/Footer riêng hoặc để trống."}, {"topic": "Header/Footer & số trang", "q": "Nút Page Number (chèn số trang) nằm trong nhóm nào của tab Insert?", "options": ["Pages", "Header & Footer", "Illustrations", "Text"], "answer": 1, "explain": "Kiến thức Word chuẩn (mục 3.4.7): Insert > nhóm Header & Footer gồm Header, Footer và Page Number."}, {"topic": "Header/Footer & số trang", "q": "Để mỗi section trong tài liệu có Header/Footer khác nhau, sau khi chèn Section Break ta cần tắt (bỏ chọn) nút nào trong Header & Footer Tools > Design?", "options": ["Different First Page", "Show Document Text", "Different Odd & Even Pages", "Link to Previous"], "answer": 3, "explain": "Khi Link to Previous còn bật, Header/Footer của section sau kế thừa nội dung section trước; tắt nó thì hai section độc lập (kiến thức Word chuẩn)."}, {"topic": "Page Setup & in ấn", "q": "Trong Word 2010, hộp thoại Page Setup được mở bằng mũi tên ở góc dưới bên phải nhóm Page Setup thuộc tab:", "options": ["Insert", "Home", "Page Layout", "References"], "answer": 2, "explain": "Giáo trình mục 3.5.1: Ribbon Page Layout, nhóm Page Setup, nhấn mũi tên góc dưới phải để mở hộp thoại Page Setup."}, {"topic": "Page Setup & in ấn", "q": "Khổ giấy A4 có kích thước là:", "options": ["210 mm × 297 mm", "216 mm × 279 mm", "148 mm × 210 mm", "297 mm × 420 mm"], "answer": 0, "explain": "A4 = 210 × 297 mm; 216 × 279 mm (8,5 × 11 in) là Letter, 148 × 210 mm là A5, 297 × 420 mm là A3."}, {"topic": "Page Setup & in ấn", "q": "Khi dùng Mirror Margins để làm sách (tạo tính đối xứng giữa các trang), các lề Left và Right sẽ trở thành:", "options": ["Top và Bottom", "Inside và Outside", "Gutter và Header", "Portrait và Landscape"], "answer": 1, "explain": "Giáo trình mục 3.5.1: với Mirror Margins, Left/Right đổi thành Inside/Outside; Gutter là khoảng cách dùng để đóng gáy."}, {"topic": "Page Setup & in ấn", "q": "Để mở màn hình in của Word, dùng lệnh File > Print hoặc phím tắt:", "options": ["Ctrl+O", "Ctrl+S", "Ctrl+P", "Ctrl+N"], "answer": 2, "explain": "Giáo trình mục 3.5.2: File > Print (phím tắt Ctrl+P), tại đây chọn số bản in ở Copies và máy in ở Printer."}, {"topic": "Page Setup & in ấn", "q": "Để giữ nguyên định dạng khi mở hoặc in tài liệu trên máy khác, có thể lưu tài liệu dưới dạng:", "options": ["TXT hoặc CSV", "DOC hoặc DOT", "XLSX hoặc PPTX", "PDF hoặc XPS"], "answer": 3, "explain": "Giáo trình mục 3.5.2: lưu tập tin dưới dạng .PDF hoặc .XPS để giữ nguyên định dạng khi đọc/in ở máy khác."}, {"topic": "Mail Merge", "q": "Mail Merge (trộn thư) kết hợp hai thành phần chính nào?", "options": ["Tài liệu chính (main document) và nguồn dữ liệu (data source)", "Header và Footer", "Bảng và biểu đồ", "Template và Macro"], "answer": 0, "explain": "Kiến thức Word chuẩn (tab Mailings): tài liệu chính chứa nội dung cố định, nguồn dữ liệu (Excel, Access, danh sách nhập tay...) cung cấp các trường thay đổi."}, {"topic": "Mail Merge", "q": "Trên tab Mailings, nút Insert Merge Field dùng để:", "options": ["Chọn tập tin Excel hoặc Access làm nguồn dữ liệu", "Xem trước kết quả trộn thư", "Chèn trường dữ liệu (tên cột của nguồn dữ liệu) vào tài liệu chính", "Xuất các thư đã trộn ra máy in"], "answer": 2, "explain": "Kiến thức Word chuẩn: Select Recipients chọn nguồn, Insert Merge Field chèn trường, Preview Results xem trước, Finish & Merge hoàn tất."}, {"topic": "Văn bản hành chính", "q": "Theo giáo trình mục 3.6, văn bản hành chính là:", "options": ["Các bản báo cáo, thông báo, bài viết thông thường", "Các văn bản có giá trị pháp lý theo quy ước, quy định", "Các văn bản được soạn bằng Microsoft Word", "Các tài liệu chỉ lưu hành nội bộ trong doanh nghiệp"], "answer": 1, "explain": "Giáo trình mục 3.6: báo cáo, thông báo, bài viết thuộc nhóm thông điệp; văn bản hành chính là văn bản có giá trị pháp lý theo quy ước, quy định."}, {"topic": "Văn bản hành chính", "q": "Theo Nghị định 30/2020/NĐ-CP, văn bản hành chính được trình bày với phông chữ và bộ mã nào?", "options": ["Arial, bộ mã VNI Windows", "Tahoma, bộ mã TCVN3", "VNI-Times, bộ mã VNI Windows", "Times New Roman, bộ mã Unicode (TCVN 6909:2001)"], "answer": 3, "explain": "Phụ lục I Nghị định 30/2020/NĐ-CP quy định phông Times New Roman, bộ mã Unicode theo TCVN 6909:2001, cỡ chữ 13-14."}, {"topic": "Văn bản hành chính", "q": "Khi định lề trang văn bản hành chính khổ A4 theo Nghị định 30/2020/NĐ-CP, lề nào rộng nhất (30-35 mm) để chừa chỗ đóng gáy?", "options": ["Lề trái", "Lề phải", "Lề trên", "Lề dưới"], "answer": 0, "explain": "Nghị định 30/2020/NĐ-CP: lề trên và dưới 20-25 mm, lề trái 30-35 mm, lề phải 15-20 mm."}, {"topic": "Văn bản hành chính", "q": "Theo Nghị định 30/2020/NĐ-CP, số trang của văn bản hành chính được đặt ở đâu?", "options": ["Cuối trang, canh phải, đánh từ trang 2", "Đầu trang, canh trái, hiển thị cả trang 1", "Giữa phần lề trên (Header), không hiển thị số ở trang thứ nhất", "Góc dưới bên phải, chỉ đánh cho trang cuối"], "answer": 2, "explain": "Nghị định 30/2020/NĐ-CP: số trang canh giữa theo chiều ngang trong phần lề trên (header), không hiển thị số trang thứ nhất - thao tác thực hiện bằng Different First Page."}], "cards": [{"topic": "Thao tác tập tin", "front": "Tạo mới, mở, lưu, lưu với tên khác và đóng tài liệu", "back": "Ctrl+N: tạo mới. Ctrl+O (File > Open): mở. Ctrl+S (File > Save): lưu, nếu chưa lưu lần nào Word hỏi tên và nơi lưu. F12 (File > Save As): lưu tên/định dạng khác. Ctrl+W: đóng tài liệu."}, {"topic": "Thao tác tập tin", "front": "Đặt mặc định lưu .doc (Word 2003) và bật tự động sao lưu", "back": "File > Word Options > Save: mục 'Save files in this format' chọn Word 97-2003 Document (*.doc); tích 'Save AutoRecover information every ... minutes' để tự sao lưu theo chu kỳ."}, {"topic": "Gõ tiếng Việt", "front": "Gõ tiếng Việt kiểu Telex (Unikey)", "back": "aa=â, ee=ê, oo=ô, aw=ă, ow=ơ, uw=ư, dd=đ. Dấu: s sắc, f huyền, r hỏi, x ngã, j nặng. VD: Vieejt = Việt. Bảng mã Unicode dùng font Arial, Calibri, Tahoma; VNI Windows dùng font VNI-Times."}, {"topic": "Gõ tiếng Việt", "front": "Gõ tiếng Việt kiểu VNI (Unikey)", "back": "a6=â, e6=ê, o6=ô, a8=ă, o7=ơ, u7=ư, d9=đ. Dấu: 1 sắc, 2 huyền, 3 hỏi, 4 ngã, 5 nặng. VD: Vie65t = Việt."}, {"topic": "Di chuyển & chọn", "front": "Di chuyển nhanh con trỏ trong văn bản", "back": "Home/End: đầu/cuối dòng. Ctrl+Home/Ctrl+End: đầu/cuối văn bản. Page Up/Page Down: lên/xuống một trang màn hình. Ctrl+mũi tên trái/phải: qua từng từ."}, {"topic": "Di chuyển & chọn", "front": "Chọn nhanh khối văn bản", "back": "Ctrl+A: chọn tất cả. Đặt con trỏ ở điểm đầu, giữ Shift và click ở điểm cuối. Giữ Shift + phím mũi tên/Home/End để mở rộng vùng chọn. Nhấp đúp: chọn từ; nhấp ba: chọn đoạn. Xóa khối: chọn rồi nhấn Delete."}, {"topic": "Chỉnh sửa văn bản", "front": "Hoàn tác, làm lại, cắt, sao chép, dán", "back": "Ctrl+Z: Undo. Ctrl+Y: Redo. Ctrl+X: cắt. Ctrl+C: sao chép. Ctrl+V: dán (nhóm Clipboard, tab Home). Ctrl+Alt+V: Paste Special."}, {"topic": "Định dạng ký tự", "front": "In đậm, in nghiêng, gạch chân văn bản", "back": "Chọn văn bản rồi nhấn nút B / I / U trong nhóm Font (tab Home) hoặc Ctrl+B / Ctrl+I / Ctrl+U; nhấn lần nữa để bỏ. Mũi tên cạnh nút U để chọn các kiểu gạch chân khác."}, {"topic": "Định dạng ký tự", "front": "Đổi kích cỡ chữ", "back": "Chọn văn bản, chọn cỡ ở ô Font Size (Home > Font). Ctrl+] tăng và Ctrl+[ giảm 1 điểm mỗi lần; Ctrl+Shift+> và Ctrl+Shift+< tăng/giảm theo các bậc cỡ chữ định sẵn."}, {"topic": "Định dạng ký tự", "front": "Tạo chỉ số trên (m²) và chỉ số dưới (H₂O)", "back": "Chọn ký tự rồi nhấn nút Superscript / Subscript trong nhóm Font, hoặc Ctrl+Shift+= (chỉ số trên) và Ctrl+= (chỉ số dưới)."}, {"topic": "Định dạng ký tự", "front": "Đổi chữ hoa/thường cho vùng chọn", "back": "Home > Font > Change Case (nút Aa): Sentence case, lowercase, UPPERCASE, Capitalize Each Word, tOGGLE cASE; hoặc nhấn Shift+F3."}, {"topic": "Định dạng ký tự", "front": "Mở hộp thoại Font để dùng hiệu ứng đặc biệt và gạch dưới chỉ từ", "back": "Ctrl+D hoặc mũi tên góc dưới phải nhóm Font (Home). Effects: Strikethrough, Double strikethrough, Superscript, Subscript, Small caps, All caps, Hidden. Gạch dưới không tính khoảng trắng: Underline style = Words only."}, {"topic": "Định dạng ký tự", "front": "Giãn hoặc thu hẹp khoảng cách giữa các ký tự", "back": "Chọn văn bản > Ctrl+D > thẻ Advanced > Character Spacing > Spacing: Expanded (mở rộng) hoặc Condensed (thu hẹp), nhập số đo ở mục By."}, {"topic": "Định dạng ký tự", "front": "Tô sáng (Highlight) đoạn text, ngừng và gỡ bỏ tô sáng", "back": "Home > Font > mũi tên cạnh Text Highlight Color, chọn màu rồi tô chọn văn bản. Ngừng chế độ tô: Stop Highlighting hoặc Esc. Gỡ tô: chọn văn bản rồi chọn No Color."}, {"topic": "Định dạng ký tự", "front": "Sao chép định dạng và xóa định dạng ký tự", "back": "Format Painter (Home > Clipboard): chọn vùng mẫu, bấm nút rồi quét lên vùng đích; nhấp đúp nút để dùng nhiều lần, Esc để thoát (Ctrl+Shift+C / Ctrl+Shift+V). Xóa định dạng ký tự: Ctrl+Space hoặc Home > Font > Clear Formatting."}, {"topic": "Văn bản hành chính", "front": "Trình bày trang văn bản hành chính theo Nghị định 30/2020/NĐ-CP", "back": "Khổ A4 (210 × 297 mm), font Times New Roman, bộ mã Unicode (TCVN 6909:2001), cỡ chữ 13-14. Lề trên/dưới 20-25 mm, trái 30-35 mm, phải 15-20 mm (Page Layout > Page Setup > Margins). Số trang canh giữa trong header, không hiển thị ở trang 1."}, {"topic": "Định dạng đoạn", "front": "Canh lề đoạn: trái, giữa, phải, đều hai bên", "back": "Nhóm Paragraph (Home): Ctrl+L canh trái, Ctrl+E canh giữa, Ctrl+R canh phải, Ctrl+J canh đều hai bên (Justify)."}, {"topic": "Định dạng đoạn", "front": "Đặt khoảng cách giữa các dòng trong đoạn (Line spacing)", "back": "Ctrl+1 (Single), Ctrl+5 (1.5 lines), Ctrl+2 (Double); hoặc hộp thoại Paragraph > thẻ Indents and Spacing > Line spacing (Single, 1.5 lines, Double, At least, Exactly, Multiple)."}, {"topic": "Định dạng đoạn", "front": "Thụt lề trái/phải toàn đoạn, thụt dòng đầu và dòng treo", "back": "Page Layout > Paragraph > Left/Right, hoặc hộp thoại Paragraph > Indentation: Left, Right, Special = First line (thụt dòng đầu) hoặc Hanging (dòng treo). Có thể kéo các marker trên Ruler; Ctrl+M / Ctrl+Shift+M tăng/giảm thụt lề."}, {"topic": "Định dạng đoạn", "front": "Đổi khoảng cách trước và sau đoạn", "back": "Chọn đoạn > Page Layout > Paragraph > Spacing: nhập giá trị ở Before (trước) và After (sau); hoặc hộp thoại Paragraph > Indents and Spacing > Spacing."}, {"topic": "Định dạng đoạn", "front": "Tạo chữ cái lớn đầu đoạn (Drop Cap)", "back": "Đặt con trỏ trong đoạn > Insert > Text > Drop Cap: Dropped (trong văn bản) hoặc In margin (ngoài, bên trái). Drop Cap Options: Font, Lines to drop (số dòng), Distance from text."}, {"topic": "Định dạng đoạn", "front": "Tạo danh sách tự động (ký hiệu, số thứ tự, đa cấp)", "back": "Home > Paragraph: Bullets (dấu chấm tròn, hoa thị...), Numbering (số/chữ thứ tự), Multilevel List (kết hợp số và chữ theo cấp); Increase/Decrease Indent để đổi cấp."}, {"topic": "Định dạng đoạn", "front": "Đóng khung và tô màu nền đoạn văn bản", "back": "Chọn đoạn > Home > Paragraph > mũi tên nút Border > Borders and Shading: thẻ Borders, Page Border, Shading; mục Apply to chọn Text hoặc Paragraph."}, {"topic": "Định dạng đoạn", "front": "Chia văn bản thành nhiều cột (dạng cột báo chí)", "back": "Chọn đoạn > Page Layout > Page Setup > Columns > More Columns: chọn số cột, Line between, độ rộng/khoảng cách cột, Apply to. Ctrl+Shift+Enter: ngắt sang cột kế tiếp."}, {"topic": "Định dạng đoạn", "front": "Cài đặt điểm dừng Tab (Tab stops)", "back": "Bật Ruler (View Ruler ở đầu thanh cuộn dọc), bấm ô chọn loại tab ở góc trái thước (Left, Center, Right, Decimal, Bar) rồi click lên thước; hoặc Paragraph > Tabs (có Leader). Nhấn Tab để nhảy tới tab stop."}, {"topic": "Bảng biểu", "front": "Chèn bảng và di chuyển giữa các ô", "back": "Insert > Tables > Table: rê chuột chọn số cột × dòng, hoặc Insert Table để nhập số liệu. Tab: sang ô kế tiếp; Shift+Tab: về ô trước; Tab ở ô cuối cùng: thêm dòng mới."}, {"topic": "Bảng biểu", "front": "Thêm hoặc xóa hàng, cột trong bảng", "back": "Đặt con trỏ vào ô > Table Tools > Layout > Rows & Columns: Insert Above/Below (thêm hàng), Insert Left/Right (thêm cột); Delete > Delete Cells/Columns/Rows/Table."}, {"topic": "Bảng biểu", "front": "Trộn ô, tách ô, tách bảng", "back": "Chọn ô > Table Tools > Layout > nhóm Merge: Merge Cells (trộn thành một ô), Split Cells (tách thành nhiều ô), Split Table (tách thành hai bảng, hoặc Ctrl+Shift+Enter)."}, {"topic": "Bảng biểu", "front": "Lặp lại dòng tiêu đề bảng ở các trang sau và tính tổng trong bảng", "back": "Chọn dòng tiêu đề > Table Tools > Layout > Data > Repeat Header Rows. Tính tổng: Layout > Data > Formula, dùng =SUM(ABOVE) hoặc =SUM(LEFT)."}, {"topic": "Đối tượng đồ họa", "front": "Đặt văn bản bao quanh hình, sắp xếp lớp và nhóm đối tượng", "back": "Chọn đối tượng > tab Format > Arrange: Text Wrapping (Square, Tight, Behind Text, In Front of Text...), Bring to Front / Send to Back, Group (chọn nhiều đối tượng bằng Shift/Ctrl+click), Align, Rotate."}, {"topic": "Đối tượng đồ họa", "front": "Chèn hình ảnh, Shapes, SmartArt, Chart và WordArt", "back": "Insert > nhóm Illustrations: Picture, Clip Art, Shapes, SmartArt, Chart; WordArt ở Insert > nhóm Text. Sau khi chèn, định dạng ở tab Format (SmartArt có thêm tab Design)."}, {"topic": "Header/Footer & số trang", "front": "Chèn Header và Footer", "back": "Insert > nhóm Header & Footer > Header hoặc Footer, chọn mẫu rồi nhập nội dung. Xong nhấn Close Header and Footer (tab Design) hoặc nhấp đúp vào vùng thân văn bản."}, {"topic": "Header/Footer & số trang", "front": "Đánh số trang", "back": "Insert > Header & Footer > Page Number > Top of Page / Bottom of Page / Current Position; Format Page Numbers để chọn kiểu số và Start at (số bắt đầu)."}, {"topic": "Header/Footer & số trang", "front": "Không hiển thị số trang ở trang đầu; mỗi section có Header/Footer riêng", "back": "Header & Footer Tools > Design > Options: tích Different First Page. Với section riêng: chèn Section Break rồi bỏ chọn Link to Previous ở section sau."}, {"topic": "Page Setup & in ấn", "front": "Ngắt trang và ngắt section", "back": "Ctrl+Enter: ngắt trang (page break). Page Layout > Page Setup > Breaks: Page, Column, Text Wrapping; Section Breaks gồm Next Page, Continuous, Even Page, Odd Page."}, {"topic": "Page Setup & in ấn", "front": "Thiết lập trang in: khổ giấy, lề, hướng giấy", "back": "Page Layout > Page Setup: Margins, Orientation (Portrait/Landscape), Size; hoặc mũi tên góc nhóm mở hộp thoại Page Setup: thẻ Margins (Top, Bottom, Left, Right, Gutter, Mirror margins), Paper (Paper size, Custom nhập Width/Height), Layout."}, {"topic": "Page Setup & in ấn", "front": "In tài liệu và chọn phạm vi trang in", "back": "File > Print (Ctrl+P): Copies (số bản), Printer (chọn máy in), Settings: Print All Pages / Print Selection / Print Current Page / Custom Print (ô Pages, ví dụ 1,3,5-8); xem trước ở khung bên phải."}, {"topic": "Page Setup & in ấn", "front": "Lưu tài liệu thành PDF/XPS và đặt mật khẩu", "back": "File > Save As > Save as type: PDF (*.pdf) hoặc XPS Document để giữ nguyên định dạng; nút Options để tùy chọn. Đặt mật khẩu mở tài liệu: File > Info > Protect Document > Encrypt with Password."}, {"topic": "Tìm kiếm & thay thế", "front": "Tìm kiếm, thay thế và nhảy tới vị trí trong tài liệu", "back": "Ctrl+F: Find (Navigation Pane). Ctrl+H: Replace (Find what / Replace with, Replace hoặc Replace All). Ctrl+G hoặc F5: Go To (trang, dòng...). Các lệnh cũng nằm ở Home > Editing."}, {"topic": "Mail Merge", "front": "Trộn thư (Mail Merge) cơ bản", "back": "Mailings > Start Mail Merge > Letters; Select Recipients (Use Existing List: Excel/Access, hoặc Type a New List); Insert Merge Field (chèn trường dạng «Ten»); Preview Results; Finish & Merge > Edit Individual Documents hoặc Print Documents."}]}, "IU04": {"questions": [{"topic": "Giới thiệu Excel", "q": "Một worksheet trong Microsoft Excel 2010 chứa tối đa bao nhiêu cột và dòng?", "options": ["256 cột và 65.536 dòng", "1.024 cột và 1.048.576 dòng", "16.384 cột và 1.048.576 dòng", "16.384 cột và 65.536 dòng"], "answer": 2, "explain": "Từ Excel 2007 trở đi mỗi worksheet có 16.384 cột (A–XFD) × 1.048.576 dòng; bản cũ chỉ có 256 cột × 65.536 dòng."}, {"topic": "Nhập dữ liệu", "q": "Khi đang nhập dữ liệu trong một ô, muốn xuống dòng ngay trong ô đó (ngắt dòng trong cùng ô) thì nhấn:", "options": ["Alt + Enter", "Ctrl + Enter", "Shift + Enter", "Tab"], "answer": 0, "explain": "Alt + Enter tạo ngắt dòng trong cùng một ô; Enter/Tab chỉ chuyển sang ô khác."}, {"topic": "Nhập dữ liệu", "q": "Tổ hợp phím Ctrl + Shift + ; (dấu chấm phẩy) trong Excel dùng để:", "options": ["Chèn ngày hiện tại vào ô", "Mở hộp thoại Go To", "Chèn công thức =NOW() vào ô", "Chèn thời gian (giờ) hiện tại vào ô"], "answer": 3, "explain": "Ctrl + Shift + ; nhập giờ hiện tại dưới dạng giá trị tĩnh; Ctrl + ; mới là ngày hiện tại."}, {"topic": "Công thức và toán tử", "q": "Kết quả của công thức =2+3*4^2 là:", "options": ["80", "50", "196", "26"], "answer": 1, "explain": "Tính ^ trước (4^2 = 16), rồi * (3*16 = 48), cuối cùng + (2+48 = 50)."}, {"topic": "Công thức và toán tử", "q": "Trong Excel, công thức =-2^2 trả về:", "options": ["4", "-4", "0", "#NUM!"], "answer": 0, "explain": "Toán tử số âm có độ ưu tiên cao hơn ^ nên Excel tính (-2)^2 = 4."}, {"topic": "Công thức và toán tử", "q": "Ô A1 chứa văn bản KNX, ô B1 chứa số 2026. Công thức =A1&B1 trả về:", "options": ["#VALUE!", "KNX 2026", "KNX2026", "2026KNX"], "answer": 2, "explain": "Toán tử & nối chuỗi trực tiếp, không tự chèn khoảng trắng; số 2026 được đổi thành văn bản khi nối."}, {"topic": "Địa chỉ tương đối/tuyệt đối", "q": "Ô C2 chứa công thức =A2*$B$1. Sao chép công thức từ C2 xuống C4, công thức tại C4 là:", "options": ["=A4*$B$3", "=A4*$B$1", "=A2*$B$1", "=A4*B1"], "answer": 1, "explain": "A2 là địa chỉ tương đối nên đổi thành A4; $B$1 là địa chỉ tuyệt đối nên giữ nguyên."}, {"topic": "Địa chỉ tương đối/tuyệt đối", "q": "Ô D2 chứa công thức =$A2+B$1. Sao chép D2 sang ô E3 (sang phải 1 cột, xuống 1 dòng), công thức tại E3 là:", "options": ["=$A3+B$1", "=$B3+C$1", "=$A3+C$2", "=$A3+C$1"], "answer": 3, "explain": "$A2 khóa cột A nên chỉ dòng đổi thành $A3; B$1 khóa dòng 1 nên chỉ cột đổi thành C$1."}, {"topic": "Địa chỉ tương đối/tuyệt đối", "q": "Khi con trỏ đang nằm trong tham chiếu A1 ở thanh công thức, nhấn phím F4 một lần sẽ đổi A1 thành:", "options": ["$A$1", "A$1", "$A1", "A1:A1"], "answer": 0, "explain": "F4 xoay vòng theo thứ tự A1 → $A$1 → A$1 → $A1 → A1."}, {"topic": "Địa chỉ tương đối/tuyệt đối", "q": "Điểm nằm ở B2:B6. Muốn xếp hạng ở C2 rồi sao chép công thức xuống C6 cho kết quả đúng, ta nhập ở C2:", "options": ["=RANK(B2,B2:B6)", "=RANK($B$2,B2:B6)", "=RANK(B2,$B$2:$B$6)", "=RANK(B2,$B2:$B6)"], "answer": 2, "explain": "number phải tương đối (B2) để mỗi dòng xét điểm riêng; vùng ref phải tuyệt đối $B$2:$B$6 để không bị trượt xuống khi sao chép."}, {"topic": "Định dạng", "q": "Ô A1 và A2 đều chứa công thức =5/2, được định dạng Number với 0 chữ số thập phân (nên mỗi ô hiển thị là 3). Ô A3 định dạng General chứa =A1+A2 sẽ hiển thị:", "options": ["6", "5", "3", "10"], "answer": 1, "explain": "Định dạng chỉ đổi cách hiển thị, giá trị lưu vẫn là 2.5 nên 2.5 + 2.5 = 5 (không phải 3 + 3 = 6)."}, {"topic": "Định dạng", "q": "Máy dùng cấu hình khu vực English (US). Ô chứa số 1234567.891 được áp dụng Custom format #,##0 sẽ hiển thị:", "options": ["1,234,567.891", "1,234,567", "1234568", "1,234,568"], "answer": 3, "explain": "Mã #,##0 bật dấu phân cách hàng nghìn và làm tròn đến hàng đơn vị: 1234567.891 → 1,234,568."}, {"topic": "Định dạng", "q": "Ô A1 chứa ngày 5 tháng 9 năm 2014 (kiểu Date). Áp dụng Custom format d/m/yy, ô A1 hiển thị:", "options": ["5/9/14", "05/09/14", "5/9/2014", "05/09/2014"], "answer": 0, "explain": "d và m không thêm số 0 đứng đầu, yy chỉ lấy 2 chữ số cuối của năm nên hiển thị 5/9/14."}, {"topic": "Hàm toán học", "q": "Kết quả của =INT(-5.6) là (dấu thập phân là dấu chấm):", "options": ["-5", "6", "-6", "5"], "answer": 2, "explain": "INT trả về số nguyên lớn nhất không vượt quá number; số nguyên lớn nhất không vượt quá -5.6 là -6."}, {"topic": "Hàm toán học", "q": "Kết quả của =MOD(17,5)+INT(7.9) là (dấu thập phân là dấu chấm):", "options": ["10", "9", "12", "8"], "answer": 1, "explain": "MOD(17,5) = 2 (17 = 3*5 + 2); INT(7.9) = 7; tổng = 9."}, {"topic": "Hàm toán học", "q": "Kết quả của =ABS(12-20)+SQRT(36)+PRODUCT(2,3) là:", "options": ["14", "4", "26", "20"], "answer": 3, "explain": "ABS(-8) = 8; SQRT(36) = 6; PRODUCT(2,3) = 6; 8 + 6 + 6 = 20."}, {"topic": "Hàm toán học", "q": "Kết quả của =ROUND(1234.5678,-2) là (dấu thập phân là dấu chấm):", "options": ["1200", "1234.57", "1235", "1300"], "answer": 0, "explain": "num_digits = -2 làm tròn đến hàng trăm: 1234.5678 → 1200."}, {"topic": "Hàm thống kê", "q": "Vùng A1:A6 chứa lần lượt: 8, 12, 5, (ô trống thật sự), chữ \"Hết\", 20. Kết quả =SUM(A1:A6) là:", "options": ["#VALUE!", "40", "45", "25"], "answer": 2, "explain": "SUM bỏ qua ô trống và văn bản trong vùng tham chiếu: 8 + 12 + 5 + 20 = 45."}, {"topic": "Hàm thống kê", "q": "Vùng A1:A6 chứa lần lượt: 8, 12, 5, (ô trống thật sự), chữ \"Hết\", 20. Kết quả =AVERAGE(A1:A6) là (dấu thập phân là dấu chấm):", "options": ["9", "11.25", "7.5", "#VALUE!"], "answer": 1, "explain": "AVERAGE bỏ qua ô trống và văn bản: (8+12+5+20)/4 = 45/4 = 11.25."}, {"topic": "Hàm thống kê", "q": "Vùng A1:A6 chứa lần lượt: 8, 12, 5, (ô trống thật sự), chữ \"Hết\", 20. Kết quả của =COUNT(A1:A6) và =COUNTA(A1:A6) lần lượt là:", "options": ["4 và 6", "5 và 5", "5 và 4", "4 và 5"], "answer": 3, "explain": "COUNT chỉ đếm ô chứa số (8, 12, 5, 20 → 4); COUNTA đếm ô không trống (8, 12, 5, Hết, 20 → 5)."}, {"topic": "Hàm thống kê", "q": "Vùng A1:A6 chứa lần lượt: 8, 12, 5, (ô trống thật sự), chữ \"Hết\", 20. Kết quả =MAX(A1:A6)-MIN(A1:A6) là:", "options": ["15", "20", "12", "#VALUE!"], "answer": 0, "explain": "MAX = 20 và MIN = 5 (ô trống và văn bản bị bỏ qua) nên 20 - 5 = 15."}, {"topic": "Hàm thống kê", "q": "Vùng B2:B6 chứa điểm: 70, 85, 85, 60, 90. Kết quả =RANK(70,B2:B6) (bỏ qua đối số order) là:", "options": ["2", "4", "3", "5"], "answer": 1, "explain": "Xếp giảm dần: 90, 85, 85, 70, 60; có 3 giá trị lớn hơn 70 nên 70 xếp hạng 4."}, {"topic": "Hàm thống kê", "q": "A2:A6 chứa: Nam, Nữ, Nam, Nữ, Nam; B2:B6 chứa: 10, 20, 30, 40, 50. Kết quả =SUMIF(A2:A6,\"Nữ\",B2:B6) là:", "options": ["40", "90", "60", "150"], "answer": 2, "explain": "Nữ nằm ở A3 và A5, ứng với B3 = 20 và B5 = 40; tổng = 60."}, {"topic": "Hàm thống kê", "q": "A2:A6 chứa: Nam, Nữ, Nam, Nữ, Nam; B2:B6 chứa: 10, 20, 30, 40, 50. Kết quả =COUNTIF(B2:B6,\">=30\")+COUNTIF(A2:A6,\"Nam\") là:", "options": ["5", "7", "4", "6"], "answer": 3, "explain": "Các giá trị >= 30 là 30, 40, 50 → 3; có 3 ô Nam; tổng = 3 + 3 = 6."}, {"topic": "Hàm logic", "q": "Ô B2 chứa 64. Công thức =IF(B2>=80,\"Giỏi\",IF(B2>=65,\"Khá\",\"Trung bình\")) trả về:", "options": ["Trung bình", "Khá", "Giỏi", "FALSE"], "answer": 0, "explain": "64 < 80 và 64 < 65 nên cả hai điều kiện đều sai, IF trả về nhánh cuối là \"Trung bình\"."}, {"topic": "Hàm logic", "q": "Ô A1 = 7, B1 = 4. Công thức =IF(AND(A1>=5,B1>=5),\"Đậu\",\"Rớt\")&\"-\"&IF(OR(A1>=5,B1>=5),\"Đậu\",\"Rớt\") trả về:", "options": ["Đậu-Rớt", "Đậu-Đậu", "Rớt-Đậu", "Rớt-Rớt"], "answer": 2, "explain": "AND(TRUE,FALSE) = FALSE → \"Rớt\"; OR(TRUE,FALSE) = TRUE → \"Đậu\"; nối lại thành \"Rớt-Đậu\"."}, {"topic": "Hàm logic", "q": "Ô A1 = 6, B1 = 3, C1 = 8. Công thức =IF(AND(A1>=5,OR(B1>=5,C1>=5)),\"Đạt\",\"Không đạt\") trả về:", "options": ["TRUE", "Không đạt", "#VALUE!", "Đạt"], "answer": 3, "explain": "OR(3>=5, 8>=5) = TRUE và A1>=5 = TRUE nên AND = TRUE → \"Đạt\"."}, {"topic": "Hàm logic", "q": "Ô A2 chứa mã \"A100\". Công thức =IF(AND(LEFT(A2,1)=\"A\",VALUE(RIGHT(A2,3))>100),\"Ưu tiên\",\"Thường\") trả về:", "options": ["Ưu tiên", "Thường", "FALSE", "#VALUE!"], "answer": 1, "explain": "LEFT = \"A\" (đúng) nhưng VALUE(\"100\") > 100 là sai, AND = FALSE nên trả về \"Thường\"."}, {"topic": "Hàm chuỗi", "q": "Kết quả của =MID(\"HS2024-A01\",3,4)&RIGHT(\"HS2024-A01\",2) là:", "options": ["202401", "2024A01", "S20201", "024-01"], "answer": 0, "explain": "MID lấy 4 ký tự từ vị trí 3 = \"2024\"; RIGHT lấy 2 ký tự cuối = \"01\"; nối lại thành \"202401\"."}, {"topic": "Hàm chuỗi", "q": "Ô A1 chứa chuỗi gồm: 2 dấu cách, \"Ha\", 2 dấu cách, \"Noi\", 2 dấu cách. Kết quả =LEN(A1)-LEN(TRIM(A1)) là:", "options": ["4", "6", "5", "11"], "answer": 2, "explain": "LEN(A1) = 2+2+2+3+2 = 11; TRIM còn \"Ha Noi\" có 6 ký tự; 11 - 6 = 5."}, {"topic": "Hàm chuỗi", "q": "Ô A1 chứa chuỗi \"KHOA2024\". Công thức =VALUE(RIGHT(A1,4))+1 trả về:", "options": ["KHOA2025", "20241", "#VALUE!", "2025"], "answer": 3, "explain": "RIGHT(A1,4) = \"2024\" (văn bản); VALUE đổi thành số 2024; cộng 1 được 2025."}, {"topic": "Hàm ngày giờ", "q": "Ô A1 chứa ngày 15/03/2023 (kiểu Date). Kết quả =YEAR(A1)-MONTH(A1)-DAY(A1) là:", "options": ["2005", "2035", "2041", "2011"], "answer": 0, "explain": "YEAR = 2023, MONTH = 3, DAY = 15; 2023 - 3 - 15 = 2005."}, {"topic": "Hàm ngày giờ", "q": "Ô A1 chứa ngày 15/03/2023 (kiểu Date). Ô B1 nhập =A1+30 và định dạng dd/mm/yyyy sẽ hiển thị:", "options": ["15/04/2023", "45/03/2023", "14/04/2023", "#VALUE!"], "answer": 2, "explain": "Ngày là số serial nên cộng 30 ngày: 15/03 + 16 ngày = 31/03, cộng thêm 14 ngày → 14/04/2023."}, {"topic": "Hàm ngày giờ", "q": "Ô A1 chứa 01/02/2024, ô A2 chứa 01/03/2024 (cùng kiểu Date). Công thức =A2-A1 trả về số ngày chênh lệch là:", "options": ["28", "29", "30", "1"], "answer": 1, "explain": "Năm 2024 là năm nhuận nên tháng 2 có 29 ngày; hiệu hai ngày = 29."}, {"topic": "Hàm ngày giờ", "q": "Ô A2 chứa ngày sinh (kiểu Date). Công thức nào tính đúng tuổi theo năm (lấy năm hiện tại trừ năm sinh) ở ô B2?", "options": ["=TODAY()-A2", "=YEAR(A2)-YEAR(TODAY())", "=DAY(TODAY())-DAY(A2)", "=YEAR(TODAY())-YEAR(A2)"], "answer": 3, "explain": "TODAY() trả về ngày hiện tại của hệ thống; YEAR() tách lấy năm; lấy năm hiện tại trừ năm sinh."}, {"topic": "Hàm tìm kiếm", "q": "Bảng dò E2:F4: cột E là A, B, C; cột F là 100, 150, 200. Ô A2 chứa mã \"C05\". Công thức =VLOOKUP(LEFT(A2,1),$E$2:$F$4,2,0)*VALUE(RIGHT(A2,2)) trả về:", "options": ["1000", "750", "500", "#N/A"], "answer": 0, "explain": "LEFT(A2,1) = \"C\" → tra ra 200; VALUE(\"05\") = 5; 200 * 5 = 1000."}, {"topic": "Hàm tìm kiếm", "q": "Bảng xếp loại E2:F5 (cột E sắp tăng dần): 0 - Yếu; 50 - TB; 65 - Khá; 80 - Giỏi. Công thức =VLOOKUP(79,$E$2:$F$5,2,1) trả về:", "options": ["Giỏi", "Khá", "TB", "#N/A"], "answer": 1, "explain": "range_lookup = 1 (dò gần đúng) lấy giá trị lớn nhất không vượt quá 79 trong cột E là 65 → \"Khá\"."}, {"topic": "Hàm tìm kiếm", "q": "Bảng E2:F4 (cột E sắp tăng dần): 50 - TB; 65 - Khá; 80 - Giỏi. Công thức =VLOOKUP(40,$E$2:$F$4,2,1) trả về:", "options": ["TB", "0", "#N/A", "#REF!"], "answer": 2, "explain": "Dò gần đúng nhưng 40 nhỏ hơn giá trị nhỏ nhất của cột E (50) nên không có kết quả → #N/A."}, {"topic": "Hàm tìm kiếm", "q": "Bảng dò E1:G2: hàng 1 là A, B, C; hàng 2 là 100, 150, 200 (E2 = 100, F2 = 150, G2 = 200). Ô A2 chứa \"B07-25\". Công thức =HLOOKUP(LEFT(A2,1),$E$1:$G$2,2,0)*3 trả về:", "options": ["300", "600", "150", "450"], "answer": 3, "explain": "LEFT(A2,1) = \"B\" → HLOOKUP trả về F2 = 150; 150 * 3 = 450."}, {"topic": "Lỗi thường gặp", "q": "Ô A1 chứa 10, ô B1 để trống. Công thức =A1/B1 trả về:", "options": ["#DIV/0!", "0", "#VALUE!", "#N/A"], "answer": 0, "explain": "Ô trống được coi là 0 nên phép chia cho 0 báo lỗi #DIV/0!."}, {"topic": "Lỗi thường gặp", "q": "Ô A1 chứa 7. Công thức =IF(A1>=5,Đạt,\"Rớt\") (thiếu dấu nháy kép quanh Đạt) trả về:", "options": ["Đạt", "#VALUE!", "#NAME?", "#REF!"], "answer": 2, "explain": "Đạt không có nháy kép nên Excel coi là một tên (name) không tồn tại → #NAME?."}, {"topic": "Lỗi thường gặp", "q": "Ô C1 chứa =A1+B1. Sau khi xóa cả cột B (Delete Column), công thức trong ô C1 (nay dịch thành B1) hiển thị:", "options": ["#NAME?", "#REF!", "#VALUE!", "0"], "answer": 1, "explain": "Tham chiếu tới cột B đã bị xóa không còn hợp lệ nên công thức thành =A1+#REF! và báo #REF!."}, {"topic": "Biểu đồ", "q": "Cần biểu diễn tỷ lệ phần trăm đóng góp của 4 sản phẩm vào tổng doanh thu của tháng (chỉ một dãy dữ liệu, không có giá trị âm). Loại biểu đồ phù hợp nhất là:", "options": ["Line", "Column (clustered)", "Scatter (XY)", "Pie"], "answer": 3, "explain": "Pie thể hiện tỷ lệ của từng phần trong tổng, chỉ dùng cho một dãy dữ liệu và không có giá trị âm."}, {"topic": "Biểu đồ", "q": "Trong Excel 2010, các lệnh chèn biểu đồ (Column, Line, Pie, ...) nằm ở:", "options": ["Insert > nhóm Charts", "Page Layout > nhóm Themes", "Data > nhóm Data Tools", "Formulas > nhóm Function Library"], "answer": 0, "explain": "Biểu đồ được chèn từ tab Insert, nhóm Charts."}, {"topic": "Sắp xếp và lọc", "q": "Chỉ chọn riêng một cột của bảng dữ liệu nhiều cột rồi Sort, Excel hiện hộp thoại Sort Warning. Để các cột khác đi theo và dữ liệu không bị lệch dòng, nên chọn:", "options": ["Continue with the current selection", "Expand the selection", "Cancel rồi dùng Data > Filter", "Đóng hộp thoại bằng nút X"], "answer": 1, "explain": "Expand the selection mở rộng vùng sắp xếp ra toàn bộ bảng, còn Continue with the current selection chỉ sắp cột đang chọn làm dữ liệu bị lệch."}, {"topic": "Sắp xếp và lọc", "q": "Khi dùng Data > Filter (AutoFilter) để lọc, các dòng không thỏa điều kiện sẽ:", "options": ["Bị xóa vĩnh viễn khỏi bảng tính", "Bị chuyển sang một sheet mới", "Chỉ bị ẩn tạm thời, dữ liệu vẫn còn trong sheet", "Bị đẩy xuống cuối bảng"], "answer": 2, "explain": "Filter chỉ ẩn các dòng không thỏa điều kiện; chọn Clear hoặc tắt Filter sẽ hiện lại toàn bộ dữ liệu."}, {"topic": "Sắp xếp và lọc", "q": "Muốn sắp bảng theo cột Khoa tăng dần, trong mỗi khoa lại sắp theo cột Điểm giảm dần, ta dùng:", "options": ["Data > Filter > Top 10 trên cột Điểm", "Sort A to Z trên cột Khoa rồi Sort Z to A trên cột Điểm", "Home > Format > AutoFit Column Width", "Data > Sort > Add Level: Sort by Khoa (A to Z), Then by Điểm (Largest to Smallest)"], "answer": 3, "explain": "Sắp nhiều cấp dùng hộp thoại Data > Sort với Add Level; hai lần Sort riêng lẻ sẽ làm lần sau ghi đè thứ tự của lần trước."}, {"topic": "Header/Footer và in ấn", "q": "Trong Header/Footer của Excel, mã &[Page] sẽ chèn:", "options": ["Số trang hiện tại", "Tổng số trang", "Tên sheet", "Ngày hiện tại"], "answer": 0, "explain": "&[Page] là số trang hiện tại; &[Pages] là tổng số trang; &[Tab] là tên sheet; &[Date] là ngày."}, {"topic": "Header/Footer và in ấn", "q": "Muốn dòng tiêu đề ở dòng 1 lặp lại ở đầu mỗi trang khi in một bảng dài, ta dùng:", "options": ["View > Freeze Panes", "Page Layout > Margins", "Page Layout > Print Titles > Rows to repeat at top ($1:$1)", "Insert > Header & Footer"], "answer": 2, "explain": "Rows to repeat at top trong Print Titles lặp dòng chọn ở đầu mọi trang in; Freeze Panes chỉ cố định dòng trên màn hình."}], "cards": [{"topic": "Hàm thống kê", "front": "SUM và AVERAGE: cú pháp và ví dụ?", "back": "SUM(number1, number2, ...) tính tổng; AVERAGE(number1, ...) tính trung bình cộng. =SUM(2,-6,8,4) → 8; =AVERAGE(4,6,8) → 6. Ô trống và văn bản trong vùng tham chiếu bị bỏ qua."}, {"topic": "Hàm thống kê", "front": "MAX và MIN: cú pháp và ví dụ?", "back": "MAX(number1, ...) giá trị lớn nhất; MIN(number1, ...) giá trị nhỏ nhất. =MAX(3,9,5) → 9; =MIN(3,9,5) → 3. Ô trống và văn bản trong vùng bị bỏ qua."}, {"topic": "Hàm thống kê", "front": "Phân biệt COUNT, COUNTA, COUNTBLANK?", "back": "COUNT đếm ô chứa số; COUNTA đếm ô không trống; COUNTBLANK đếm ô trống. Ví dụ A1:A4 = 5, \"x\", (trống), 7 → COUNT = 2, COUNTA = 3, COUNTBLANK = 1."}, {"topic": "Hàm thống kê", "front": "RANK(number, ref, [order]): ý nghĩa và ví dụ?", "back": "Trả về thứ hạng của number trong ref. order = 0 hoặc bỏ qua: hạng 1 là số lớn nhất; order = 1: hạng 1 là số nhỏ nhất. Với ref = 90, 85, 85, 70: =RANK(85,ref) → 2 (hai ô cùng hạng 2); =RANK(70,ref) → 4. Nên khóa ref bằng $."}, {"topic": "Hàm toán học", "front": "ROUND(number, num_digits): cách dùng và ví dụ?", "back": "num_digits > 0: làm tròn số lẻ; = 0: đến hàng đơn vị; < 0: làm tròn bên trái dấu thập phân. =ROUND(5.13687,2) → 5.14; =ROUND(145.13687,-2) → 100; =ROUND(2.5,0) → 3."}, {"topic": "Hàm logic", "front": "IF: cú pháp và ví dụ?", "back": "IF(logical_test, value_if_true, value_if_false). =IF(A1>=5,\"Đạt\",\"Rớt\") với A1 = 4 → Rớt. Có thể lồng nhiều IF (Excel 2007 trở lên tối đa 64 cấp)."}, {"topic": "Hàm logic", "front": "AND, OR, NOT: quy tắc và ví dụ?", "back": "AND đúng khi TẤT CẢ điều kiện đúng; OR đúng khi ÍT NHẤT MỘT điều kiện đúng; NOT đảo giá trị logic. =AND(3>1,2>5) → FALSE; =OR(3>1,2>5) → TRUE; =NOT(TRUE) → FALSE."}, {"topic": "Hàm thống kê", "front": "SUMIF(range, criteria, [sum_range]): cách dùng và ví dụ?", "back": "Cộng các ô trong sum_range tương ứng với ô ở range thỏa criteria; bỏ sum_range thì cộng chính range. A1:A3 = x, y, x; B1:B3 = 1, 2, 3 → =SUMIF(A1:A3,\"x\",B1:B3) → 4; =SUMIF(B1:B3,\">1\") → 5."}, {"topic": "Hàm thống kê", "front": "COUNTIF(range, criteria): cách dùng và ví dụ?", "back": "Đếm số ô trong range thỏa criteria. B1:B5 = 3, 5, 7, 5, 1 → =COUNTIF(B1:B5,\">=5\") → 3; =COUNTIF(B1:B5,5) → 2. Hỗ trợ ký tự đại diện: A1:A4 = KNX-01, DALI-02, KNX-03, DMX-04 → =COUNTIF(A1:A4,\"KNX*\") → 2."}, {"topic": "Hàm chuỗi", "front": "LEFT và RIGHT: cú pháp và ví dụ?", "back": "LEFT(text, [num_chars]) lấy từ đầu chuỗi; RIGHT(text, [num_chars]) lấy từ cuối chuỗi; num_chars mặc định là 1. =LEFT(\"KNXStore\",3) → KNX; =RIGHT(\"KNXStore\",5) → Store."}, {"topic": "Hàm chuỗi", "front": "MID(text, start_num, num_chars): cách dùng và ví dụ?", "back": "Lấy num_chars ký tự bắt đầu từ vị trí start_num. =MID(\"HS2024-A01\",3,4) → \"2024\". Kết quả luôn là văn bản; dùng VALUE() để đổi thành số."}, {"topic": "Hàm chuỗi", "front": "LEN và TRIM: chức năng và ví dụ?", "back": "LEN(text) đếm số ký tự, tính cả khoảng trắng: =LEN(\"Excel 2010\") → 10. TRIM(text) xóa khoảng trắng đầu/cuối và rút khoảng trắng giữa các từ còn 1: =TRIM(\"  Ha  Noi \") → \"Ha Noi\"."}, {"topic": "Hàm chuỗi", "front": "UPPER, LOWER, VALUE: chức năng và ví dụ?", "back": "UPPER(text) đổi thành chữ hoa: =UPPER(\"knx\") → KNX; LOWER(text) đổi thành chữ thường: =LOWER(\"KNX Store\") → knx store; VALUE(text) đổi chuỗi số thành số: =VALUE(RIGHT(\"KHOA2024\",4))+1 → 2025."}, {"topic": "Hàm ngày giờ", "front": "TODAY() và NOW() khác nhau thế nào?", "back": "TODAY() trả về ngày hiện tại của hệ thống (không có đối số); NOW() trả về ngày và giờ hiện tại. Cả hai tự cập nhật khi bảng tính được tính lại hoặc mở lại. Ctrl + ; chèn ngày tĩnh, Ctrl + Shift + ; chèn giờ tĩnh."}, {"topic": "Hàm ngày giờ", "front": "DAY, MONTH, YEAR, DATE: cú pháp và ví dụ?", "back": "DAY(date), MONTH(date), YEAR(date) tách ngày/tháng/năm; DATE(year, month, day) tạo ngày. A1 = 15/03/2023 → DAY = 15, MONTH = 3, YEAR = 2023. =DATE(2023,3,15)+30 → 14/04/2023."}, {"topic": "Hàm tìm kiếm", "front": "VLOOKUP(lookup_value, table_array, col_index_num, [range_lookup]): cách hoạt động?", "back": "Dò lookup_value ở CỘT TRÁI NHẤT của table_array, trả về giá trị ở cột thứ col_index_num của cùng dòng. Bảng E2:F4 = A/100, B/150, C/200 → =VLOOKUP(\"B\",E2:F4,2,0) → 150. Nên khóa bảng dò bằng $E$2:$F$4."}, {"topic": "Hàm tìm kiếm", "front": "VLOOKUP: range_lookup = TRUE/1 khác FALSE/0 thế nào?", "back": "FALSE hoặc 0: dò chính xác, không thấy → #N/A. TRUE hoặc 1 (mặc định khi bỏ qua): dò gần đúng, cột trái nhất phải sắp TĂNG dần, lấy giá trị lớn nhất không vượt quá lookup_value. Bảng 0/Yếu, 50/TB, 65/Khá, 80/Giỏi: =VLOOKUP(79,bảng,2,1) → Khá."}, {"topic": "Hàm tìm kiếm", "front": "HLOOKUP(lookup_value, table_array, row_index_num, [range_lookup]): cách hoạt động?", "back": "Dò lookup_value ở HÀNG TRÊN CÙNG của table_array, trả về giá trị ở hàng thứ row_index_num của cùng cột. Hàng 1 (E1:G1) = A, B, C; hàng 2 = 100, 150, 200 → =HLOOKUP(\"C\",E1:G2,2,0) → 200."}, {"topic": "Hàm toán học", "front": "ABS, SQRT, PRODUCT: chức năng và ví dụ?", "back": "ABS(number) giá trị tuyệt đối: =ABS(12-20) → 8. SQRT(number) căn bậc hai: =SQRT(36) → 6 (số âm → #NUM!). PRODUCT(n1, n2, ...) tích: =PRODUCT(2,3,4) → 24."}, {"topic": "Hàm toán học", "front": "INT, MOD, ODD: chức năng và ví dụ?", "back": "INT(number) là số nguyên lớn nhất không vượt quá number: INT(5.6) → 5, INT(-5.6) → -6. MOD(number, divisor) là số dư: MOD(5,3) → 2. ODD(number) làm tròn ra xa số 0 đến số nguyên lẻ gần nhất: ODD(3.6) → 5, ODD(-2.2) → -3."}, {"topic": "Công thức và toán tử", "front": "Thứ tự ưu tiên các toán tử trong Excel?", "back": "Cao → thấp: tham chiếu (: khoảng trắng ,) → số âm → % → ^ → * và / → + và - → & → so sánh (= < > <= >= <>). Cùng mức thì tính từ trái sang phải; dùng ngoặc () để đổi thứ tự. =2+3*4^2 → 50; =-2^2 → 4."}, {"topic": "Địa chỉ tương đối/tuyệt đối", "front": "Địa chỉ tương đối (A1) hoạt động thế nào khi sao chép công thức?", "back": "Địa chỉ tự thay đổi theo vị trí mới của công thức. C2 chứa =A2*B2, sao chép xuống C3 → =A3*B3."}, {"topic": "Địa chỉ tương đối/tuyệt đối", "front": "Địa chỉ tuyệt đối ($A$1) dùng khi nào?", "back": "$ khóa cả cột và dòng, sao chép không đổi. Dùng cho ô hằng số (thuế suất, tỷ giá) hoặc vùng dò/xếp hạng. C2 chứa =A2*$B$1, sao chép xuống C3 → =A3*$B$1."}, {"topic": "Địa chỉ tương đối/tuyệt đối", "front": "Địa chỉ hỗn hợp $A1 và A$1 khác nhau thế nào?", "back": "$A1 khóa cột A (dòng vẫn thay đổi); A$1 khóa dòng 1 (cột vẫn thay đổi). D2 chứa =$A2+B$1, sao chép sang E3 → =$A3+C$1."}, {"topic": "Địa chỉ tương đối/tuyệt đối", "front": "Phím nào đổi nhanh kiểu địa chỉ tương đối/tuyệt đối?", "back": "F4 khi con trỏ đang ở trong tham chiếu ở thanh công thức, xoay vòng: A1 → $A$1 → A$1 → $A1 → A1."}, {"topic": "Định dạng", "front": "Mở hộp thoại Format Cells bằng cách nào? Gồm các tab nào?", "back": "Nhấn Ctrl + 1, hoặc Home > nhóm Cells > Format > Format Cells... Gồm 6 tab: Number, Alignment, Font, Border, Fill, Protection."}, {"topic": "Định dạng", "front": "Excel lưu ngày tháng thế nào? Khi nào ô hiện #####?", "back": "Ngày là số nguyên (serial) tính từ 01/01/1900 = 1, giờ là phần thập phân (0.5 = 12:00), nên có thể cộng/trừ ngày: 01/03/2024 - 01/02/2024 = 29. Nhập ngày bằng / hoặc - (05/09/2014); ngày không hợp lệ (31/02/2014) bị coi là văn bản và canh trái. Ô hiện ##### khi cột quá hẹp hoặc ngày/giờ âm."}, {"topic": "Định dạng", "front": "Định dạng số và tiền tệ ở đâu? Ví dụ Custom format?", "back": "Format Cells > Number: Number (Use 1000 Separator), Currency, Accounting (chọn Symbol, Decimal places). Accounting canh thẳng ký hiệu tiền tệ. Custom #,##0 \"đ\" hiển thị 1500000 → 1,500,000 đ (máy cấu hình English-US; máy cấu hình Việt Nam dùng dấu chấm phân cách nghìn)."}, {"topic": "Định dạng", "front": "Định dạng ô có làm thay đổi giá trị thực không?", "back": "Không, chỉ đổi cách hiển thị; ROUND mới đổi giá trị thật. A1 = 2.5 hiển thị 0 số lẻ là 3 nhưng =A1*2 vẫn → 5 (không phải 6)."}, {"topic": "Định dạng", "front": "Làm sao giữ số 0 đứng đầu khi nhập số điện thoại?", "back": "Gõ dấu nháy đơn trước số ('0912345678) hoặc định dạng ô là Text (@) trước khi nhập. Dữ liệu thành văn bản (canh trái, COUNT không đếm). Nhập thường 0912345678 thì Excel lưu 912345678."}, {"topic": "Giao diện và phím tắt", "front": "Phím tắt Excel thường gặp trong đề thi?", "back": "Ctrl+N tạo mới; Ctrl+O mở; Ctrl+S lưu; F12 Save As; Ctrl+Home về A1; Ctrl+End tới ô dữ liệu cuối; F5 mở Go To; Ctrl+PageUp/PageDown chuyển sheet; Alt+Enter ngắt dòng trong ô; Ctrl+Shift+; chèn giờ hiện tại."}, {"topic": "Biểu đồ", "front": "Chọn loại biểu đồ nào cho từng mục đích?", "back": "Column/Bar: so sánh giá trị giữa các nhóm. Line: xu hướng theo thời gian. Pie: tỷ lệ phần trăm của các phần trong tổng (một dãy dữ liệu, không giá trị âm). XY (Scatter): quan hệ giữa hai biến số."}, {"topic": "Biểu đồ", "front": "Các bước tạo biểu đồ trong Excel 2010?", "back": "Chọn vùng dữ liệu (gồm cả tiêu đề hàng/cột) → Insert > nhóm Charts → chọn loại biểu đồ. F11 tạo biểu đồ trên chart sheet riêng; Alt + F1 tạo biểu đồ nhúng trong sheet."}, {"topic": "Biểu đồ", "front": "Thêm tiêu đề, chú giải, nhãn dữ liệu cho biểu đồ ở đâu (Excel 2010)?", "back": "Chọn biểu đồ → Chart Tools có 3 tab: Design, Layout, Format. Layout: Chart Title, Axis Titles, Legend, Data Labels, Gridlines. Design: Change Chart Type, Select Data, Switch Row/Column, Move Chart."}, {"topic": "Sắp xếp và lọc", "front": "Sắp xếp dữ liệu (Sort) trong Excel: các lệnh và sắp nhiều cấp?", "back": "Data > Sort & Filter: Sort A to Z (tăng dần: số nhỏ → lớn, chữ A → Z), Sort Z to A (giảm dần). Sắp nhiều cấp: Data > Sort > Add Level (Sort by cột chính, Then by cột phụ, chọn Order). Ví dụ: Khoa A → Z, rồi Điểm lớn → nhỏ."}, {"topic": "Sắp xếp và lọc", "front": "Hộp thoại Sort Warning xuất hiện khi nào và chọn gì?", "back": "Khi chỉ chọn một cột của bảng nhiều cột rồi Sort. Chọn Expand the selection để sắp cả bảng (các cột đi cùng nhau); Continue with the current selection chỉ sắp cột đang chọn làm dữ liệu bị lệch dòng."}, {"topic": "Sắp xếp và lọc", "front": "AutoFilter dùng thế nào?", "back": "Data > Filter (Ctrl + Shift + L) hiện mũi tên lọc ở tiêu đề cột: Text Filters (Equals, Begins With, Contains...), Number Filters (Greater Than, Between, Top 10...). Lọc chỉ ẩn dòng không thỏa điều kiện, không xóa dữ liệu; Clear để xóa bộ lọc."}, {"topic": "Header/Footer và in ấn", "front": "Chèn Header/Footer trong Excel 2010 bằng cách nào?", "back": "Insert > nhóm Text > Header & Footer (chuyển sang Page Layout view), hoặc Page Layout > Page Setup > tab Header/Footer. Có 3 vùng Left, Center, Right; tùy chọn Different First Page, Different Odd & Even Pages."}, {"topic": "Header/Footer và in ấn", "front": "Các mã trong Header/Footer là gì? Ví dụ hiển thị số trang?", "back": "&[Page] số trang hiện tại; &[Pages] tổng số trang; &[Date] ngày; &[Time] giờ; &[Tab] tên sheet; &[File] tên file. Chuỗi \"Trang &[Page] / &[Pages]\" ở trang 2 của tài liệu 5 trang → Trang 2 / 5."}, {"topic": "Header/Footer và in ấn", "front": "Thiết lập in: lặp tiêu đề, vùng in, hướng giấy?", "back": "Page Layout > Print Titles > Rows to repeat at top (ví dụ $1:$1) lặp tiêu đề mỗi trang; Print Area > Set Print Area chọn vùng in; Orientation (Portrait/Landscape); Size (A4). Xem trước khi in: Ctrl + P."}, {"topic": "Lỗi thường gặp", "front": "Lỗi #DIV/0! là gì? Cách khắc phục?", "back": "Chia cho 0 hoặc chia cho ô trống. =A1/B1 với B1 trống → #DIV/0!. Khắc phục: =IF(B1=0,0,A1/B1) hoặc =IFERROR(A1/B1,0)."}, {"topic": "Lỗi thường gặp", "front": "Lỗi #N/A xuất hiện khi nào?", "back": "Không tìm thấy giá trị cần dò: VLOOKUP/HLOOKUP dò chính xác mà không có giá trị đó, hoặc dò gần đúng với giá trị nhỏ hơn giá trị nhỏ nhất của bảng. =VLOOKUP(\"D\",E2:F4,2,0) với bảng A, B, C → #N/A. Bẫy lỗi: =IFERROR(VLOOKUP(...),\"Không có\")."}, {"topic": "Lỗi thường gặp", "front": "Lỗi #VALUE! xuất hiện khi nào?", "back": "Sai kiểu đối số/toán hạng, ví dụ tính toán với văn bản không đổi được sang số. =\"abc\"*2 → #VALUE!; =\"5\"+1 → 6 (chuỗi số tự đổi); VLOOKUP có col_index_num < 1 → #VALUE!."}, {"topic": "Lỗi thường gặp", "front": "Lỗi #REF! xuất hiện khi nào?", "back": "Tham chiếu không hợp lệ: xóa hàng/cột/ô mà công thức đang tham chiếu; hoặc VLOOKUP có col_index_num lớn hơn số cột của table_array. C1 = A1+B1, xóa cột B → #REF!."}, {"topic": "Lỗi thường gặp", "front": "Lỗi #NAME? xuất hiện khi nào?", "back": "Excel không nhận ra tên: gõ sai tên hàm (=SUMM(A1:A3)), thiếu dấu nháy kép quanh văn bản (=IF(A1>5,Đạt,\"Rớt\")), hoặc dùng tên vùng chưa được định nghĩa."}]}, "IU05": {"questions": [{"topic": "Khái niệm & phần mềm", "q": "Phần mềm nào sau đây KHÔNG phải là phần mềm thuyết trình?", "options": ["Microsoft PowerPoint", "Microsoft Access", "LibreOffice Impress", "Prezi"], "answer": 1, "explain": "Access là hệ quản trị cơ sở dữ liệu; PowerPoint, Impress, Prezi là phần mềm thuyết trình (GT mục 5.2)."}, {"topic": "Tạo bài thuyết trình", "q": "Khi khởi động Microsoft PowerPoint 2010, chương trình mặc định tạo ra bài trình diễn nào?", "options": ["Bài dựng sẵn từ mẫu (template) do người dùng chọn lần trước", "Bài trình diễn được mở gần nhất trong danh sách Recent", "Bài chứa sẵn 10 slide mẫu với Theme Office", "Bài trình diễn rỗng (blank) với một slide tiêu đề"], "answer": 3, "explain": "Khi khởi động, PowerPoint tự tạo một bài trình diễn rỗng chứa slide tựa đề với hai placeholder (GT mục 5.2 – Tạo bài thuyết trình rỗng)."}, {"topic": "Slide & Layout", "q": "Trong PowerPoint, 'placeholder' là gì?", "options": ["Khung giữ chỗ trên slide dùng để nhập văn bản hoặc chèn hình ảnh, bảng, biểu đồ, SmartArt", "Hiệu ứng áp dụng khi chuyển từ slide này sang slide khác", "Khung liệt kê danh sách các hiệu ứng đã thiết lập trên slide", "Tệp mẫu dùng để lưu Theme và Layout của bài thuyết trình"], "answer": 0, "explain": "Placeholder là các hộp giữ chỗ trên slide layout để nhập văn bản hoặc chèn hình ảnh, SmartArt, bảng biểu, đồ thị (GT mục 5.2 – Cấu trúc Layout)."}, {"topic": "Giao diện", "q": "Ribbon trong PowerPoint 2010 được tổ chức như thế nào?", "options": ["Thành một thanh menu duy nhất, mỗi menu là một danh sách lệnh thả xuống", "Thành các hộp công cụ nổi (floating toolbar) có thể kéo thả tùy ý", "Thành nhiều ngăn (tab) theo chức năng, mỗi ngăn chia thành các nhóm lệnh (group)", "Thành hai thanh công cụ cố định Standard và Formatting"], "answer": 2, "explain": "Ribbon gồm nhiều ngăn theo chức năng, mỗi ngăn có nhiều nhóm lệnh nhỏ (GT mục 5.2 – Ribbon)."}, {"topic": "Slide Master", "q": "Để chuyển sang cửa sổ Slide Master trong PowerPoint 2010, ta chọn:", "options": ["Home > Slides > Layout > Slide Master", "Design > Themes > Slide Master", "View > Master Views > Slide Master", "Slide Show > Set Up > Slide Master"], "answer": 2, "explain": "Vào ngăn View, nhóm Master Views và chọn Slide Master (GT mục 5.2 – Giới thiệu Slide Master)."}, {"topic": "Slide Master", "q": "Muốn logo công ty xuất hiện trên tất cả các slide của bài thuyết trình mà không phải chèn lặp lại, nên chèn logo vào đâu?", "options": ["Slide Master", "Notes Master", "Handout Master", "Từng slide, sao chép logo lần lượt"], "answer": 0, "explain": "Hình ảnh/thông tin muốn xuất hiện trên mọi slide nên thêm vào Slide Master để tránh nhập trùng lặp (GT mục 5.2 – Giới thiệu Slide Master)."}, {"topic": "Slide Master", "q": "Slide Master KHÔNG trực tiếp quy định thông tin nào sau đây?", "options": ["Theme và bố cục (layout) chung của bài thuyết trình", "Nền slide và bảng màu", "Kích thước và vị trí của các placeholder", "Nội dung văn bản riêng do người dùng nhập trên từng slide"], "answer": 3, "explain": "Slide Master chứa theme, layout, nền, màu, hiệu ứng, kích thước và vị trí placeholder, không chứa nội dung riêng của từng slide (GT mục 5.2)."}, {"topic": "Slide Master", "q": "Theo giáo trình, mỗi bài thuyết trình có tối thiểu bao nhiêu slide master?", "options": ["0, slide master là tùy chọn", "1", "2", "Bằng số layout đang sử dụng"], "answer": 1, "explain": "Mỗi bài thuyết trình có ít nhất một slide master (GT mục 5.2 – Giới thiệu Slide Master)."}, {"topic": "Animation", "q": "Hiệu ứng (Animation) trong PowerPoint được chia thành các nhóm chính nào?", "options": ["Entrance, Emphasis, Exit và Motion Paths", "Entrance, Exit và Transition", "Entrance, Exit, Emphasis và Transition", "Chỉ có hai nhóm: Entrance và Exit"], "answer": 0, "explain": "PowerPoint chia hiệu ứng thành 4 nhóm: Entrance, Exit, Emphasis và Motion Paths (GT mục 5.2 – Nhập văn bản vào slide)."}, {"topic": "Animation", "q": "Muốn làm nổi bật tiêu đề đã hiện sẵn trên slide (đổi màu, phóng to, nhấp nháy) mà không làm nó xuất hiện hay biến mất, nên chọn nhóm hiệu ứng nào?", "options": ["Entrance", "Exit", "Motion Paths", "Emphasis"], "answer": 3, "explain": "Hiệu ứng Emphasis dùng để nhấn mạnh nội dung đang hiển thị trên slide (GT mục 5.2)."}, {"topic": "Animation", "q": "Nút Animation Pane nằm trong nhóm nào của ngăn Animations?", "options": ["Animation", "Advanced Animation", "Timing", "Preview"], "answer": 1, "explain": "Vào nhóm Advanced Animation và chọn nút Animation Pane; khung này xuất hiện bên phải cửa sổ Normal View (GT mục 5.2 – Các tùy chọn hiệu ứng nâng cao)."}, {"topic": "Animation", "q": "Trong khung Animation Pane, các hiệu ứng được thực thi theo thứ tự nào?", "options": ["Từ dưới lên trên, hiệu ứng nằm dưới cùng chạy trước", "Theo thứ tự ngẫu nhiên do PowerPoint quyết định", "Từ trên xuống dưới, hiệu ứng nằm trên cùng có độ ưu tiên cao hơn và chạy trước", "Theo thứ tự bảng chữ cái tên của các đối tượng"], "answer": 2, "explain": "Hiệu ứng nằm trên cùng có độ ưu tiên cao hơn và được thực thi trước, do đó cần sắp xếp thứ tự theo ý đồ trình bày (GT mục 5.2)."}, {"topic": "Animation", "q": "Trong nhóm Timing của ngăn Animations, tùy chọn Start nào cho phép một hiệu ứng chạy đồng thời với hiệu ứng đứng ngay trước nó?", "options": ["On Click", "After Previous", "Trigger", "With Previous"], "answer": 3, "explain": "With Previous chạy cùng lúc với hiệu ứng trước, After Previous chạy ngay sau đó, On Click chạy khi bấm chuột (kiến thức PowerPoint chuẩn)."}, {"topic": "Transition", "q": "Transition (hiệu ứng chuyển slide) khác Animation ở điểm nào?", "options": ["Transition áp dụng cho từng đối tượng riêng lẻ, Animation áp dụng cho cả slide", "Transition là hiệu ứng khi chuyển từ slide này sang slide khác; Animation áp dụng cho từng đối tượng (văn bản, hình, biểu đồ...) trên slide", "Transition chỉ đặt được trong Slide Master, Animation chỉ đặt được trên từng slide", "Hai thuật ngữ đồng nghĩa, chỉ khác tên gọi giữa các phiên bản"], "answer": 1, "explain": "Transitions là hiệu ứng khi chuyển giữa các slide, còn animation là hiệu ứng cho các đối tượng trên slide (GT mục 5.2 – Hiệu ứng chuyển slide)."}, {"topic": "Transition", "q": "Để xóa hiệu ứng chuyển slide đồng loạt trên tất cả các slide, ta thực hiện:", "options": ["Home > Clear All Formatting", "Animations > Animation Pane > Remove, làm lần lượt trên từng slide", "Transitions > chọn None > Apply To All", "Design > Themes > Reset Slide Background"], "answer": 2, "explain": "Có thể xóa hiệu ứng chuyển slide cho từng slide riêng lẻ hoặc đồng loạt trên tất cả slide bằng cách chọn None rồi Apply To All (GT mục 5.2 – Xóa bỏ hiệu ứng chuyển slide)."}, {"topic": "Chèn đối tượng – liên kết Excel", "q": "Muốn chèn biểu đồ từ Excel vào slide sao cho khi dữ liệu trong file Excel gốc thay đổi thì biểu đồ trên slide cập nhật theo, ta thực hiện:", "options": ["Copy biểu đồ trong Excel, rồi trong PowerPoint dùng Paste Special > Paste link (hoặc tùy chọn Link Data)", "Copy biểu đồ trong Excel, rồi trong PowerPoint dán dưới dạng Picture (hình ảnh)", "Dùng Insert > Chart rồi nhập lại số liệu vào bảng dữ liệu của biểu đồ", "Dùng Insert > Screenshot để chụp lại biểu đồ trong Excel"], "answer": 0, "explain": "Chỉ Paste link/Link Data mới giữ liên kết với file Excel nguồn; Picture và Screenshot là ảnh tĩnh, Insert > Chart tạo dữ liệu nhúng riêng (kiến thức PowerPoint chuẩn)."}, {"topic": "Chèn đối tượng – liên kết Excel", "q": "Lệnh Insert > Table > Excel Spreadsheet trong PowerPoint có tác dụng gì?", "options": ["Chèn liên kết (link) đến một tệp Excel bất kỳ có sẵn trên máy", "Chèn một bảng tính Excel nhúng (embedded) vào slide, có thể chỉnh sửa bằng công cụ Excel", "Chuyển bảng PowerPoint hiện tại thành tệp .xlsx", "Chèn ảnh chụp của một vùng bảng tính Excel"], "answer": 1, "explain": "Lệnh này tạo một worksheet Excel nhúng ngay trong slide, nhấp đúp để sửa với Ribbon của Excel (kiến thức PowerPoint chuẩn)."}, {"topic": "Chèn đối tượng – liên kết Excel", "q": "Trong hộp thoại Insert Object, để chèn tệp Excel có sẵn dưới dạng liên kết (không nhúng), ta chọn Create from file, Browse tệp rồi:", "options": ["Chọn Create new", "Đánh dấu Display as icon", "Đánh dấu Link", "Nhấn Ctrl+K"], "answer": 2, "explain": "Không đánh dấu Link thì tệp được nhúng (embed); đánh dấu Link thì đối tượng liên kết tới tệp gốc (kiến thức PowerPoint chuẩn)."}, {"topic": "Chèn đối tượng – biểu đồ", "q": "Sau khi chèn biểu đồ bằng Insert > Chart, để sửa số liệu của biểu đồ ta dùng lệnh nào?", "options": ["Chart Tools > Design > Edit Data", "Chart Tools > Format > Shape Fill", "Design > Themes", "Review > Track Changes"], "answer": 0, "explain": "Edit Data mở lại bảng dữ liệu (bảng tính Excel) đi kèm để hiệu chỉnh số liệu của biểu đồ (kiến thức PowerPoint chuẩn)."}, {"topic": "Chèn đối tượng – SmartArt", "q": "SmartArt (Insert > SmartArt) dùng để làm gì?", "options": ["Chèn và phát tệp video hoặc âm thanh", "Tạo biểu đồ số liệu từ bảng tính Excel", "Tạo liên kết đến trang web hoặc slide khác", "Tạo sơ đồ đồ họa minh họa danh sách, quy trình, chu trình, sơ đồ tổ chức..."], "answer": 3, "explain": "SmartArt là loại placeholder/đối tượng dùng tạo sơ đồ đồ họa minh họa thông tin (GT mục 5.2 – Cấu trúc Layout)."}, {"topic": "Chế độ xem", "q": "Chế độ xem nào thuận tiện nhất để sắp xếp lại thứ tự các slide bằng cách kéo thả các hình thu nhỏ?", "options": ["Normal", "Notes Page", "Slide Sorter", "Reading View"], "answer": 2, "explain": "Slide Sorter hiển thị hình thu nhỏ của mọi slide để kéo thả, sao chép hoặc xóa (kiến thức PowerPoint chuẩn)."}, {"topic": "Chế độ xem", "q": "Trong chế độ Normal, ghi chú của người thuyết trình (speaker notes) được nhập ở đâu?", "options": ["Ngăn Notes nằm phía dưới slide", "Khung Animation Pane bên phải", "Thanh trạng thái (Status bar)", "Cửa sổ Slide Master"], "answer": 0, "explain": "Ngăn Notes bên dưới slide chứa ghi chú, sẽ được in cùng slide khi in dạng Notes Pages (GT mục 5.3 – Chế độ in Notes Pages)."}, {"topic": "Trình chiếu & phím tắt", "q": "Để bắt đầu trình chiếu từ slide đầu tiên bằng bàn phím, ta nhấn phím nào?", "options": ["Shift+F5", "F7", "Ctrl+F5", "F5"], "answer": 3, "explain": "F5 tương ứng lệnh From Beginning trong nhóm Start Slide Show của ngăn Slide Show (GT mục 5.3)."}, {"topic": "Trình chiếu & phím tắt", "q": "Đang ở slide số 7, muốn bắt đầu trình chiếu ngay từ slide này, ta nhấn:", "options": ["F5", "Shift+F5", "Ctrl+F5", "F7"], "answer": 1, "explain": "Shift+F5 tương ứng lệnh From Current Slide, còn F5 luôn chạy từ slide đầu tiên (kiến thức PowerPoint chuẩn)."}, {"topic": "Trình chiếu & phím tắt", "q": "Trong khi đang trình chiếu, phím nào dùng để thoát khỏi chế độ Slide Show?", "options": ["F5", "Tab", "Ctrl+S", "Esc"], "answer": 3, "explain": "Phím Esc kết thúc Slide Show và quay về chế độ soạn thảo (kiến thức PowerPoint chuẩn)."}, {"topic": "Chèn đối tượng – liên kết", "q": "Để tạo liên kết từ một đối tượng trên slide sang một slide khác trong cùng bài, ta chọn đối tượng rồi:", "options": ["Transitions > Advance Slide > On Mouse Click", "Animations > Trigger > On Click of", "Insert > Hyperlink (Ctrl+K) > Place in This Document, chọn slide đích", "Design > Background Styles > Format Background"], "answer": 2, "explain": "Hộp thoại Insert Hyperlink có mục Place in This Document để liên kết đến slide khác trong cùng bài trình chiếu (kiến thức PowerPoint chuẩn)."}, {"topic": "Trình chiếu", "q": "Để chọn màn hình trình chiếu, độ phân giải và bật Presenter View, ta vào ngăn Slide Show, nhóm nào?", "options": ["Start Slide Show", "Monitor", "Set Up", "Master Views"], "answer": 1, "explain": "Bước 2 của quy trình trình chiếu là vào ngăn Slide Show, nhóm Monitor (GT mục 5.3 – Trình chiếu bài thuyết trình)."}, {"topic": "Trình chiếu", "q": "Chức năng con trỏ laser (laser pointer) được bổ sung trong PowerPoint 2010 dùng để làm gì?", "options": ["Chiếu điểm sáng vào nội dung đang trình chiếu để người xem dễ theo dõi vấn đề đang thảo luận", "Vẽ nét bút hoặc tô sáng chữ để lưu lại trên slide", "Phóng to phần nội dung đang trình chiếu", "Tự động chuyển slide theo thời gian đã đặt"], "answer": 0, "explain": "Con trỏ laser giúp người thuyết trình chỉ vào nội dung trên slide để người xem theo dõi và nắm bắt tốt hơn (GT mục 5.3)."}, {"topic": "In ấn", "q": "Khi in Handout, có thể chọn in bao nhiêu slide trên một trang?", "options": ["1, 2, 3, 4, 6 hoặc 9 slide", "2, 4, 8 hoặc 16 slide", "1, 2, 5 hoặc 10 slide", "Số slide bất kỳ do người dùng tự nhập"], "answer": 0, "explain": "Handout cho phép chọn in 1, 2, 3, 4, 6 hoặc 9 slide trên một trang (GT mục 5.3 – Thực hiện in ấn Handout)."}, {"topic": "In ấn", "q": "Thông thường, người ta in Handout theo cách nào?", "options": ["1 slide trên một trang A4 nằm ngang", "4 slide trên một trang A4 nằm ngang", "9 slide trên một trang A3", "2 slide trên một trang giấy A4 chiều dọc"], "answer": 3, "explain": "Thông thường in handout là 2 slide trên một trang giấy khổ A4 chiều dọc (GT mục 5.3 – Thực hiện in ấn Handout)."}, {"topic": "In ấn", "q": "Bản in dạng Notes Pages thường dành cho ai và chứa nội dung gì?", "options": ["Dành cho người xem; chỉ chứa dàn ý văn bản của bài", "Dành cho người xem; chứa nhiều slide thu nhỏ trên một trang", "Dành cho người thuyết trình; chứa nội dung slide kèm ghi chú của slide", "Dành cho người thuyết trình; chỉ chứa ghi chú, không có hình slide"], "answer": 2, "explain": "Notes Pages chứa nội dung trên slide cùng ghi chú của slide, người thuyết trình đọc nhanh để xác định ý chính (GT mục 5.3 – Chế độ in Notes Pages)."}, {"topic": "In ấn", "q": "Kiểu in Full Page Slides in như thế nào?", "options": ["Nhiều slide thu nhỏ trên một trang", "Mỗi slide trên một trang in", "Chỉ in phần dàn ý văn bản", "Chỉ in ghi chú của các slide"], "answer": 1, "explain": "Full Page in mỗi slide trên một trang, thường dùng cho bài thuyết trình quan trọng để nội dung dễ đọc trên bản in (GT mục 5.3 – Chế độ Full Page)."}, {"topic": "In ấn", "q": "Kiểu in Outline trong PowerPoint in ra nội dung nào?", "options": ["Hình ảnh đầy đủ của từng slide kèm mọi đối tượng đồ họa", "Chỉ phần văn bản (tiêu đề và các ý chính) của các slide", "Ghi chú của người thuyết trình kèm hình slide", "Các slide thu nhỏ kèm dòng kẻ để người xem ghi chép"], "answer": 1, "explain": "Outline chỉ in dàn ý văn bản của bài, không in hình ảnh hay đồ họa (kiến thức PowerPoint chuẩn; GT mục 5.3 xếp Outline cùng nhóm bản in cho người thuyết trình)."}, {"topic": "Lưu tệp", "q": "Định dạng tệp nào khi mở lên sẽ chạy thẳng vào chế độ trình chiếu (Slide Show)?", "options": [".ppsx (PowerPoint Show)", ".pptx (PowerPoint Presentation)", ".potx (PowerPoint Template)", ".docx (Word Document)"], "answer": 0, "explain": ".ppsx là PowerPoint Show, mở ra là chạy Slide Show ngay, không vào chế độ soạn thảo (kiến thức PowerPoint chuẩn)."}, {"topic": "Lưu tệp", "q": "Để bài thuyết trình mở được bằng PowerPoint 2003, khi Save As ta chọn kiểu tệp nào?", "options": ["PowerPoint Presentation (.pptx)", "PowerPoint Show (.ppsx)", "PowerPoint Template (.potx)", "PowerPoint 97-2003 Presentation (.ppt)"], "answer": 3, "explain": "Định dạng .ppt là định dạng tương thích PowerPoint 97-2003, còn .pptx là định dạng mặc định từ PowerPoint 2007 (kiến thức PowerPoint chuẩn)."}, {"topic": "Trình chiếu", "q": "Lệnh Hide Slide trong ngăn Slide Show có tác dụng gì?", "options": ["Xóa vĩnh viễn slide khỏi bài thuyết trình", "Ẩn toàn bộ nội dung văn bản của slide", "Ẩn slide khỏi lúc trình chiếu nhưng slide vẫn còn trong tệp", "Ẩn ghi chú của slide khi in"], "answer": 2, "explain": "Slide bị Hide vẫn nằm trong tệp và ở chế độ soạn thảo nhưng bị bỏ qua khi trình chiếu (kiến thức PowerPoint chuẩn)."}, {"topic": "Trình chiếu", "q": "Chế độ 'Browsed at a kiosk (full screen)' trong hộp thoại Set Up Show có đặc điểm nào?", "options": ["Chỉ chạy khi người trình bày bấm chuột hoặc phím Enter", "Chạy trong cửa sổ có thanh cuộn để người xem tự điều khiển", "Tự chạy lặp lại liên tục theo thời gian đã đặt cho đến khi nhấn Esc", "Tự động xuất bài thành tệp video .mp4"], "answer": 2, "explain": "Kiosk tự chạy theo thời gian đặt sẵn và lặp lại liên tục cho tới khi nhấn Esc; chế độ cửa sổ là 'Browsed by an individual' (kiến thức PowerPoint chuẩn)."}, {"topic": "Trình chiếu", "q": "Lệnh Rehearse Timings trong ngăn Slide Show dùng để làm gì?", "options": ["Ghi âm giọng thuyết trình gắn vào từng slide", "Kiểm tra chính tả và ngữ pháp toàn bộ bài", "Chạy thử toàn bộ hiệu ứng animation trong Normal View", "Diễn tập và ghi lại thời gian hiển thị của từng slide để dùng cho chế độ tự chuyển slide"], "answer": 3, "explain": "Rehearse Timings lưu thời gian mỗi slide để khi trình chiếu có thể tự chuyển slide theo thời gian đã ghi (kiến thức PowerPoint chuẩn)."}, {"topic": "Theme & định dạng", "q": "Muốn áp dụng nhanh một Theme có sẵn (màu sắc, font, hiệu ứng nền) cho toàn bộ bài thuyết trình, ta dùng:", "options": ["Design > Themes", "Insert > Object", "Home > Layout", "Transitions > Transition to This Slide"], "answer": 0, "explain": "Các theme có sẵn nằm trong nhóm Themes của ngăn Design (GT mục 5.2 – Sử dụng Theme có sẵn)."}, {"topic": "Chèn đối tượng – Header & Footer", "q": "Để hiển thị số thứ tự slide trên tất cả các slide trừ slide tiêu đề, ta thực hiện:", "options": ["Insert > Header & Footer, chọn Slide number rồi nhấn Apply (chỉ áp dụng cho slide đang chọn)", "Insert > Header & Footer, chọn Slide number và Don't show on title slide rồi nhấn Apply to All", "Home > Layout > Slide number", "Design > Page Setup > Number slides from"], "answer": 1, "explain": "Apply to All áp dụng cho mọi slide và tùy chọn Don't show on title slide bỏ qua slide tiêu đề; 'Number slides from' chỉ đặt số bắt đầu (kiến thức PowerPoint chuẩn)."}], "cards": [{"topic": "Tạo bài & slide", "front": "Tạo bài trình chiếu mới, thêm slide mới, nhân bản slide", "back": "Ctrl+N: bài mới (mặc định là blank). Ctrl+M hoặc Home > New Slide: thêm slide (mũi tên New Slide để chọn layout). Nhân bản: chọn slide ở ngăn thumbnail > Ctrl+D hoặc New Slide > Duplicate Selected Slides."}, {"topic": "Slide & Layout", "front": "Đổi bố cục (Layout) của slide", "back": "Home > Slides > Layout, chọn layout (Title Slide, Title and Content, Two Content...). Home > Reset đưa placeholder về vị trí mặc định của layout."}, {"topic": "Theme", "front": "Áp dụng Theme có sẵn cho bài thuyết trình", "back": "Design > Themes, chọn theme (áp toàn bài). Chuột phải vào theme > Apply to Selected Slides để chỉ áp cho slide đang chọn. Chỉnh thêm Colors / Fonts / Effects cùng ngăn Design."}, {"topic": "Lưu tệp", "front": "Lưu bài với định dạng khác (Save As)", "back": "Ctrl+S: lưu; F12 hoặc File > Save As: lưu tên/định dạng khác. .pptx (mặc định 2007+), .ppt (97-2003), .ppsx (mở thẳng Slide Show), .potx (template), .pdf."}, {"topic": "Chèn bảng", "front": "Chèn bảng (Table) vào slide", "back": "Insert > Table, kéo chọn số hàng/cột (hoặc Insert Table nhập số cột/hàng). Chỉnh sửa ở Table Tools > Design / Layout (Merge Cells, Split Cells...)."}, {"topic": "Chèn bảng – Excel", "front": "Chèn bảng tính Excel NHÚNG vào slide", "back": "Insert > Table > Excel Spreadsheet: chèn worksheet Excel nhúng (embedded); nhấp đúp để sửa bằng công cụ Excel. Không liên kết đến tệp Excel bên ngoài."}, {"topic": "Chèn biểu đồ", "front": "Chèn biểu đồ (Chart) và sửa số liệu", "back": "Insert > Chart, chọn kiểu biểu đồ, nhập dữ liệu trong bảng tính Excel mở kèm. Sửa số liệu sau: Chart Tools > Design > Edit Data."}, {"topic": "Liên kết Excel", "front": "Chèn bảng/biểu đồ từ Excel dạng LIÊN KẾT (Paste link)", "back": "Trong Excel: copy vùng dữ liệu hoặc biểu đồ. Trong PowerPoint: Home > Paste > Paste Special > Paste link (Microsoft Excel Worksheet/Chart Object), hoặc chọn Link Data ở Paste Options. Dữ liệu gốc đổi thì cập nhật (chuột phải > Update Link; quản lý ở File > Info > Edit Links to Files)."}, {"topic": "Liên kết Excel", "front": "Chèn tệp Excel có sẵn bằng Insert > Object (liên kết hay nhúng)", "back": "Insert > Object > Create from file > Browse chọn tệp. Đánh dấu Link = liên kết tới tệp gốc; không đánh dấu = nhúng (embed). Display as icon: hiện biểu tượng thay vì nội dung."}, {"topic": "Chèn hình ảnh", "front": "Chèn hình ảnh và tạo liên kết tới tệp ảnh gốc", "back": "Insert > Picture > chọn tệp. Bấm mũi tên cạnh nút Insert > Link to File (hoặc Insert and Link) để ảnh liên kết, tệp nhỏ hơn nhưng phải giữ tệp ảnh gốc ở đúng vị trí. Chỉnh ảnh: Picture Tools > Format (Crop, Corrections, Remove Background)."}, {"topic": "Chèn SmartArt", "front": "Chèn sơ đồ SmartArt", "back": "Insert > SmartArt, chọn loại (List, Process, Cycle, Hierarchy, Relationship, Matrix, Pyramid), nhập văn bản ở Text Pane. Chỉnh ở SmartArt Tools > Design / Format."}, {"topic": "Video & âm thanh", "front": "Chèn video / âm thanh vào slide", "back": "Insert > Video > Video from File (hoặc Audio > Audio from File). Tùy chọn phát ở Playback: Start (Automatically / On Click), Loop until Stopped, Hide During Show."}, {"topic": "Hyperlink", "front": "Tạo hyperlink từ đối tượng tới trang web / slide khác", "back": "Chọn đối tượng > Insert > Hyperlink (Ctrl+K): Existing File or Web Page, Place in This Document (nhảy tới slide khác), E-mail Address. Insert > Action để gán hành động cho đối tượng."}, {"topic": "Header & Footer", "front": "Chèn số slide, ngày giờ, footer", "back": "Insert > Header & Footer > tab Slide: tick Date and time / Slide number / Footer. Apply to All: áp cho mọi slide; Don't show on title slide: bỏ qua slide tiêu đề."}, {"topic": "Định dạng đối tượng", "front": "Sao chép định dạng và nhóm đối tượng", "back": "Home > Clipboard > Format Painter (nhấp đúp để dán định dạng nhiều lần). Ctrl+G: nhóm đối tượng, Ctrl+Shift+G: bỏ nhóm. Arrange > Bring to Front / Send to Back: đổi thứ tự lớp."}, {"topic": "Animation", "front": "Áp dụng hiệu ứng (Animation) cho đối tượng", "back": "Chọn đối tượng > ngăn Animations > chọn hiệu ứng hoặc Add Animation. Bốn nhóm: Entrance (xanh lá), Emphasis (vàng), Exit (đỏ), Motion Paths (đường di chuyển)."}, {"topic": "Animation", "front": "Mở Animation Pane và đổi thứ tự hiệu ứng", "back": "Animations > Advanced Animation > Animation Pane: khung bên phải Normal View. Hiệu ứng trên cùng chạy trước; kéo thả hoặc dùng Reorder Animation để đổi thứ tự; chọn hiệu ứng > Remove/Delete để xóa."}, {"topic": "Animation", "front": "Các kiểu bắt đầu hiệu ứng (Start)", "back": "Animations > Timing > Start: On Click (khi bấm chuột), With Previous (cùng lúc hiệu ứng trước), After Previous (ngay sau hiệu ứng trước). Chỉnh thêm Duration, Delay."}, {"topic": "Transition", "front": "Đặt và xóa hiệu ứng chuyển slide (Transition)", "back": "Ngăn Transitions > chọn hiệu ứng ở Transition to This Slide; Advance Slide: On Mouse Click / After (số giây). Apply To All: áp cho mọi slide. Xóa: chọn None (rồi Apply To All nếu xóa toàn bộ)."}, {"topic": "Slide Master", "front": "Vào Slide Master để sửa bố cục chung / chèn logo cho mọi slide", "back": "View > Master Views > Slide Master. Sửa ở slide đầu (lớn nhất): theme, nền, font, placeholder, logo áp cho mọi layout. Xong bấm Close Master View."}, {"topic": "Chế độ xem", "front": "Chuyển giữa các chế độ xem", "back": "View > Presentation Views: Normal, Slide Sorter (kéo thả sắp xếp, xóa slide), Notes Page, Reading View; hoặc dùng các nút chế độ xem ở góc phải thanh trạng thái."}, {"topic": "Trình chiếu", "front": "Trình chiếu từ slide đầu tiên", "back": "F5 hoặc Slide Show > Start Slide Show > From Beginning."}, {"topic": "Trình chiếu", "front": "Trình chiếu từ slide hiện tại", "back": "Shift+F5 hoặc Slide Show > Start Slide Show > From Current Slide (hoặc nút Slide Show ở thanh trạng thái)."}, {"topic": "Trình chiếu", "front": "Các phím điều khiển khi đang trình chiếu", "back": "Esc: thoát. B hoặc dấu chấm: màn hình đen. W hoặc dấu phẩy: màn hình trắng (nhấn lại để quay về). Số + Enter: nhảy tới slide đó. N / Enter / phím mũi tên: slide kế; P / Backspace: slide trước."}, {"topic": "Trình chiếu", "front": "Ẩn một slide khi trình chiếu (Hide Slide)", "back": "Chọn slide > Slide Show > Set Up > Hide Slide (hoặc chuột phải thumbnail > Hide Slide). Slide vẫn nằm trong tệp nhưng bị bỏ qua khi trình chiếu; số thứ tự hiện gạch chéo."}, {"topic": "Trình chiếu", "front": "Ghi thời gian từng slide để tự chạy (Rehearse Timings)", "back": "Slide Show > Set Up > Rehearse Timings: diễn tập và lưu thời gian mỗi slide; khi trình chiếu chọn Advance slides: Using timings để tự chuyển slide."}, {"topic": "Trình chiếu", "front": "Chọn kiểu trình chiếu (Set Up Slide Show)", "back": "Slide Show > Set Up Slide Show: Presented by a speaker (toàn màn hình), Browsed by an individual (trong cửa sổ), Browsed at a kiosk (toàn màn hình, tự lặp đến khi nhấn Esc). Có thể chọn Show slides From...To."}, {"topic": "Trình chiếu", "front": "Con trỏ laser, bút vẽ và Presenter View", "back": "Khi trình chiếu: giữ Ctrl + nhấn giữ chuột trái = con trỏ laser (PowerPoint 2010 trở lên); Ctrl+P: bút; Ctrl+A: mũi tên; Ctrl+E: tẩy. Presenter View: Slide Show > Monitor > Use Presenter View (thường dùng với 2 màn hình)."}, {"topic": "In ấn", "front": "In Handout (tài liệu phát cho người xem)", "back": "File > Print > Settings > Handouts: chọn 1, 2, 3, 4, 6 hoặc 9 slide/trang (ngang/dọc). Thông dụng: 2 slide trên A4 chiều dọc."}, {"topic": "In ấn", "front": "In Notes Pages, Outline, Full Page Slides", "back": "File > Print > Settings > Print Layout: Full Page Slides (mỗi slide một trang), Notes Pages (slide kèm ghi chú, cho người thuyết trình), Outline (chỉ dàn ý văn bản)."}]}, "IU06": {"questions": [{"topic": "6.1 Kiến thức cơ bản về Internet", "q": "Theo giáo trình, Internet là gì?", "options": ["Một mạng LAN duy nhất của một doanh nghiệp, chỉ cho phép nhân viên nội bộ truy nhập", "Một phần mềm trình duyệt dùng để xem các trang web trên mạng", "Hệ thống thông tin toàn cầu, truy nhập công cộng, gồm các mạng máy tính được liên kết với nhau", "Một mạng máy tính riêng của các cơ quan chính phủ, không dành cho người dùng cá nhân"], "answer": 2, "explain": "Mục 6.1: Internet là hệ thống thông tin toàn cầu, có thể truy nhập công cộng, gồm các mạng máy tính được liên kết với nhau."}, {"topic": "6.1 Kiến thức cơ bản về Internet", "q": "Internet truyền thông tin theo kiểu chuyển mạch gói (packet switching) dựa trên bộ giao thức chuẩn hóa nào?", "options": ["TCP/IP", "IPX/SPX", "NetBEUI", "AppleTalk"], "answer": 0, "explain": "Mục 6.1: Internet truyền dữ liệu theo kiểu chuyển mạch gói dựa trên bộ giao thức chuẩn hóa TCP/IP."}, {"topic": "6.1 Kiến thức cơ bản về Internet", "q": "Địa chỉ IPv4 có chiều dài bao nhiêu bit?", "options": ["16 bit", "48 bit", "64 bit", "32 bit"], "answer": 3, "explain": "Mục 6.1: IPv4 dài 32 bit (biểu diễn bằng 4 số thập phân), còn IPv6 dài 128 bit."}, {"topic": "6.1 Kiến thức cơ bản về Internet", "q": "Vì sao Internet đang chuyển đổi dần từ IPv4 sang IPv6?", "options": ["Vì IPv6 cho phép truy cập Internet miễn phí mà không cần đăng ký với ISP", "Vì không gian địa chỉ IPv4 (32 bit) đã cạn kiệt trong khi Internet phát triển quá nhanh", "Vì IPv4 không truyền được dữ liệu dạng hình ảnh và video", "Vì IPv4 chỉ hoạt động được trong mạng LAN, không dùng được trên Internet"], "answer": 1, "explain": "Mục 6.1: do Internet phát triển quá nhanh, IPv4 (32 bit) đã cạn kiệt nên chuyển dần sang IPv6 (128 bit)."}, {"topic": "6.1 Kiến thức cơ bản về Internet", "q": "Địa chỉ nào sau đây là địa chỉ IPv4 hợp lệ?", "options": ["192.168.1.256", "172.16.19.5", "172.16.19", "172.16.19.5.1"], "answer": 1, "explain": "Mục 6.1: IPv4 gồm đúng 4 số thập phân, mỗi số từ 0 đến 255, phân cách bằng dấu chấm; 172.16.19.5 là ví dụ trong giáo trình."}, {"topic": "6.1 Kiến thức cơ bản về Internet", "q": "Chức năng chính của hệ thống tên miền DNS là gì?", "options": ["Mã hóa dữ liệu truyền giữa trình duyệt và website", "Cấp tài khoản và mật khẩu đăng nhập cho người dùng Internet", "Diệt virus và phần mềm gián điệp trên các máy chủ web", "Ánh xạ giữa tên miền và địa chỉ IP để người dùng dễ truy cập website hơn"], "answer": 3, "explain": "Mục 6.1: DNS ánh xạ giữa tên và IP, ví dụ www.tuoitre.vn dễ nhớ hơn địa chỉ IP 123.30.128.10."}, {"topic": "6.1 Kiến thức cơ bản về Internet", "q": "Trong tên miền www.tuoitre.vn, phần '.vn' cho biết điều gì?", "options": ["Tên miền cấp cao nhất (TLD) mã quốc gia của Việt Nam", "Giao thức truyền tập tin đang được sử dụng", "Tên nhà cung cấp dịch vụ Internet (ISP) của website", "Kiểu mã hóa bảo mật của trang web"], "answer": 0, "explain": "Kiến thức Internet phổ thông (liên quan mục 6.1 - Tên miền): .vn là tên miền cấp cao nhất mã quốc gia (ccTLD) của Việt Nam."}, {"topic": "6.1 Kiến thức cơ bản về Internet", "q": "Đơn vị nào thuê đường truyền và cổng kết nối quốc tế của IAP để cung cấp dịch vụ Internet cho tổ chức và cá nhân?", "options": ["DNS server", "Web server", "ISP (Internet Service Provider)", "Trình duyệt web"], "answer": 2, "explain": "Mục 6.1: ISP phải thuê đường truyền và cổng của một IAP (Internet Access Provider) rồi cung cấp dịch vụ cho người dùng."}, {"topic": "6.1 Kiến thức cơ bản về Internet", "q": "Khi đăng ký dịch vụ với một ISP, người dùng được cấp tài khoản gồm những thành phần nào?", "options": ["Địa chỉ MAC và tên miền riêng", "Địa chỉ email và số điện thoại di động", "Địa chỉ IP tĩnh và chứng chỉ số", "Tên đăng nhập (User name) và mật khẩu (Password)"], "answer": 3, "explain": "Mục 6.1: tài khoản ISP gồm User name và Password, dùng để quản lý truy cập và tính phí."}, {"topic": "6.1 Kiến thức cơ bản về Internet", "q": "Dịch vụ Internet được sử dụng nhiều nhất, chứa thông tin gồm văn bản, hình ảnh, âm thanh và video kết hợp với nhau là:", "options": ["FTP", "Thư điện tử (Email)", "WWW (World Wide Web)", "DNS"], "answer": 2, "explain": "Mục 6.1: dịch vụ Web (WWW) là dịch vụ được dùng nhiều nhất, giúp người dùng không chuyên vẫn sử dụng được Internet."}, {"topic": "6.1 Kiến thức cơ bản về Internet", "q": "Dịch vụ nào được dùng để truyền tập tin (nạp lên/tải xuống) giữa máy tính và máy chủ từ xa?", "options": ["FTP (File Transfer Protocol)", "DNS", "DHCP", "NTP"], "answer": 0, "explain": "Mục 6.1: FTP là dịch vụ chuyển tập tin giữa các máy; chép về máy là downloading, chép lên máy chủ là uploading."}, {"topic": "6.1 Kiến thức cơ bản về Internet", "q": "Dịch vụ nào sau đây là dịch vụ lưu trữ dữ liệu trực tuyến (cloud storage)?", "options": ["Mozilla Firefox", "Dropbox", "Microsoft Outlook", "Google Translate"], "answer": 1, "explain": "Mục 6.1 (Dịch vụ lưu trữ dữ liệu trực tuyến): Dropbox, Google Drive, OneDrive lưu dữ liệu trên máy chủ Internet; Firefox là trình duyệt, Outlook là email client, Translate là dịch vụ dịch."}, {"topic": "6.2 Bảo mật khi làm việc với Internet", "q": "Mật khẩu nào sau đây an toàn nhất?", "options": ["nguyenvana1995", "12345678", "Tv#8kQ!2mLp9xR", "matkhau@123"], "answer": 2, "explain": "Mục 6.2 (Bảo mật tài khoản): mật khẩu mạnh cần đủ dài, ngẫu nhiên, kết hợp chữ hoa, chữ thường, số, ký tự đặc biệt và không chứa thông tin cá nhân."}, {"topic": "6.2 Bảo mật khi làm việc với Internet", "q": "Xác thực hai yếu tố (2FA) giúp tăng bảo mật tài khoản bằng cách nào?", "options": ["Tự động đổi mật khẩu sau mỗi lần đăng nhập", "Mã hóa toàn bộ nội dung email đã gửi", "Chặn tất cả quảng cáo và cửa sổ pop-up trên website", "Yêu cầu thêm một yếu tố xác minh (như mã OTP) ngoài mật khẩu khi đăng nhập"], "answer": 3, "explain": "Mục 6.2 (Bảo mật tài khoản): 2FA đòi hỏi yếu tố thứ hai nên chỉ lộ mật khẩu vẫn chưa đủ để chiếm tài khoản."}, {"topic": "6.2 Bảo mật khi làm việc với Internet", "q": "Một email giả danh ngân hàng yêu cầu bấm vào liên kết để 'xác minh tài khoản' rồi nhập tên đăng nhập và mật khẩu. Đây là hình thức tấn công nào?", "options": ["DDoS", "Phishing (lừa đảo giả mạo)", "Brute force", "Ransomware"], "answer": 1, "explain": "Mục 6.2 (Tránh các trang web độc hại): phishing giả mạo tổ chức uy tín bằng email hoặc trang web giả để đánh cắp thông tin đăng nhập."}, {"topic": "6.2 Bảo mật khi làm việc với Internet", "q": "Phần mềm gián điệp (spyware) là loại phần mềm:", "options": ["Âm thầm theo dõi, thu thập thông tin của người dùng và gửi cho bên thứ ba", "Tự động sao lưu dữ liệu của người dùng lên máy chủ đám mây", "Tăng tốc độ tải tệp từ Internet về máy", "Lọc thư rác trong hộp thư đến"], "answer": 0, "explain": "Mục 6.2 (Tránh các phần mềm gián điệp): spyware theo dõi và thu thập thông tin người dùng mà người dùng không hay biết."}, {"topic": "6.2 Bảo mật khi làm việc với Internet", "q": "Trước khi nhập thông tin thẻ thanh toán trên một website, dấu hiệu nào cho thấy kết nối tới website được mã hóa?", "options": ["Địa chỉ website bắt đầu bằng http:// (không có chữ s)", "Tên miền kết thúc bằng .com", "Trang web có nhiều quảng cáo và ưu đãi hấp dẫn", "Địa chỉ website bắt đầu bằng https://"], "answer": 3, "explain": "Kiến thức Internet phổ thông (liên quan mục 6.2): HTTPS mã hóa kết nối bằng TLS/SSL, còn http:// truyền dữ liệu không mã hóa."}, {"topic": "6.2 Bảo mật khi làm việc với Internet", "q": "Biện pháp nào giúp giảm nguy cơ nhiễm phần mềm độc hại và phần mềm gián điệp khi dùng Internet?", "options": ["Tắt phần mềm diệt virus và tường lửa để máy chạy nhanh hơn", "Tải phần mềm bẻ khóa (crack) từ các trang chia sẻ không rõ nguồn gốc", "Cài phần mềm diệt virus/anti-spyware, cập nhật thường xuyên và chỉ tải phần mềm từ nguồn tin cậy", "Mở mọi tệp đính kèm nhận được qua email, kể cả từ người lạ"], "answer": 2, "explain": "Mục 6.2 (Tránh các phần mềm gián điệp): dùng phần mềm bảo vệ được cập nhật và chỉ tải phần mềm từ nguồn tin cậy."}, {"topic": "6.2 Bảo mật khi làm việc với Internet", "q": "Hành vi nào sau đây phù hợp với nguyên tắc bảo mật thông tin cá nhân khi dùng mạng xã hội?", "options": ["Thiết lập quyền riêng tư cho bài đăng và không công khai số điện thoại, địa chỉ nhà", "Đăng ảnh chụp CCCD lên trang cá nhân để mọi người xác nhận danh tính", "Chia sẻ mật khẩu tài khoản cho bạn bè thân để họ giúp quản lý", "Dùng chung một mật khẩu cho tất cả tài khoản để dễ nhớ"], "answer": 0, "explain": "Mục 6.2 (Bảo mật thông tin cá nhân): hạn chế công khai thông tin nhạy cảm và không chia sẻ mật khẩu."}, {"topic": "6.3 Sử dụng trình duyệt web", "q": "Phần mềm nào sau đây là trình duyệt web?", "options": ["Microsoft Outlook", "Mozilla Firefox", "FileZilla", "Google Drive"], "answer": 1, "explain": "Mục 6.3: trình duyệt web (Chrome, Firefox, Edge...) dùng để truy cập và hiển thị trang web; Outlook là email client, FileZilla là FTP client, Google Drive là dịch vụ lưu trữ."}, {"topic": "6.3 Sử dụng trình duyệt web", "q": "Trong địa chỉ https://www.tuoitre.vn/the-thao.htm, thành phần 'https' là:", "options": ["Tên miền của website", "Đường dẫn tới trang cần xem", "Tên tệp được yêu cầu", "Giao thức được dùng để truy cập tài nguyên"], "answer": 3, "explain": "Mục 6.3 (Nhập địa chỉ trang web): URL có dạng giao thức://tên miền/đường dẫn, trong đó https là giao thức."}, {"topic": "6.3 Sử dụng trình duyệt web", "q": "Trong Chrome, Edge và Firefox trên Windows, tổ hợp phím nào mở nhanh lịch sử duyệt web (History)?", "options": ["Ctrl+T", "Ctrl+P", "Ctrl+H", "Ctrl+F"], "answer": 2, "explain": "Mục 6.3 (Xem lịch sử duyệt web): Ctrl+H mở History; Ctrl+T mở tab mới, Ctrl+P in trang, Ctrl+F tìm trong trang."}, {"topic": "6.3 Sử dụng trình duyệt web", "q": "Chức năng Bookmarks (Đánh dấu trang) trong trình duyệt dùng để làm gì?", "options": ["Tải toàn bộ website về máy để xem khi không có mạng", "Lưu địa chỉ trang web yêu thích để mở lại nhanh mà không phải gõ lại địa chỉ", "Xóa lịch sử duyệt web và cookie sau mỗi lần đóng trình duyệt", "Chặn các trang web có nội dung độc hại"], "answer": 1, "explain": "Mục 6.3 (Đánh dấu trang): Bookmarks lưu lại địa chỉ trang web để truy cập lại nhanh (phím tắt thêm bookmark là Ctrl+D)."}, {"topic": "6.3 Sử dụng trình duyệt web", "q": "Để lưu trang web hiện tại về máy thành tệp (Save page as), ta dùng tổ hợp phím nào?", "options": ["Ctrl+S", "Ctrl+P", "Ctrl+N", "Ctrl+R"], "answer": 0, "explain": "Mục 6.3 (Lưu lại trang web): Ctrl+S mở hộp thoại lưu trang; Ctrl+P in, Ctrl+N mở cửa sổ mới, Ctrl+R tải lại trang."}, {"topic": "6.3 Sử dụng trình duyệt web", "q": "Để tải một hình ảnh trên trang web về máy, thao tác nhanh nhất là:", "options": ["Nhấp chuột phải vào hình và chọn Copy link address", "Nhấp đúp vào hình rồi nhấn phím F5", "Nhấp chuột phải vào hình và chọn Save image as...", "Nhấn Ctrl+D khi đang xem trang"], "answer": 2, "explain": "Mục 6.3 (Tải hình ảnh, dữ liệu, video): menu chuột phải có lệnh Save image as... (Lưu hình ảnh thành...)."}, {"topic": "6.3 Sử dụng trình duyệt web", "q": "Chế độ duyệt web ẩn danh (Incognito / InPrivate / Private) có đặc điểm nào sau đây?", "options": ["Che giấu hoàn toàn hoạt động duyệt web khỏi website và nhà cung cấp dịch vụ Internet (ISP)", "Mã hóa toàn bộ dữ liệu truyền đi nên không thể bị theo dõi", "Tự động chặn mọi phần mềm độc hại và trang lừa đảo", "Không lưu lịch sử duyệt web, cookie và dữ liệu biểu mẫu trên máy sau khi đóng cửa sổ"], "answer": 3, "explain": "Mục 6.3 (Xem lịch sử duyệt web): chế độ ẩn danh chỉ không lưu dấu vết cục bộ trên máy, website và ISP vẫn thấy được hoạt động."}, {"topic": "6.4 Sử dụng Website", "q": "Siêu liên kết (hyperlink) trên một trang web có tác dụng gì?", "options": ["Chuyển đến trang web hoặc tài nguyên khác khi người dùng nhấp vào", "Mã hóa nội dung trang web trước khi hiển thị", "Ghi lại lịch sử truy cập vào một tệp trên máy người dùng", "Tự động gửi email đến chủ sở hữu trang web"], "answer": 0, "explain": "Mục 6.4 (Truy cập các trang web thông thường): hyperlink là thành phần giúp điều hướng từ trang này sang trang hoặc tài nguyên khác."}, {"topic": "6.4 Sử dụng Website", "q": "Để công cụ tìm kiếm Google chỉ trả về kết quả chứa đúng nguyên cụm từ cần tìm (exact match), ta nên đặt cụm từ trong:", "options": ["Dấu ngoặc đơn", "Dấu ngoặc kép", "Dấu ngoặc nhọn", "Dấu sao (*)"], "answer": 1, "explain": "Mục 6.4 (Truy cập các trang web thông thường): đặt cụm từ trong dấu ngoặc kép yêu cầu Google khớp chính xác cụm từ đó."}, {"topic": "6.4 Sử dụng Website", "q": "Sau khi dùng xong tài khoản trên trang web yêu cầu đăng nhập ở máy tính công cộng (quán net, thư viện), cần làm gì?", "options": ["Chỉ cần đóng tab trình duyệt, vì phiên đăng nhập luôn tự hủy ngay", "Chọn Đăng xuất (Log out / Sign out) và không cho trình duyệt lưu mật khẩu", "Tắt màn hình nhưng vẫn để nguyên trình duyệt đang mở", "Chọn 'Ghi nhớ đăng nhập' để lần sau vào nhanh hơn"], "answer": 1, "explain": "Mục 6.4 (Truy cập các trang web yêu cầu đăng nhập): trên máy dùng chung phải đăng xuất và không lưu mật khẩu để tránh bị người khác dùng tài khoản."}, {"topic": "6.4 Sử dụng Website", "q": "Dịch vụ nào sau đây cho phép người dùng tự xây dựng trang web cá nhân miễn phí mà không cần biết lập trình?", "options": ["Google Sites", "Google Translate", "Google Drive", "Gmail"], "answer": 0, "explain": "Mục 6.4 (Tạo trang cá nhân): Google Sites cho phép dựng website cá nhân bằng giao diện kéo thả với tài khoản Google; Translate dịch văn bản, Drive lưu trữ, Gmail là email."}, {"topic": "6.4 Sử dụng Website", "q": "Trên mạng xã hội như Facebook, bài đăng ở chế độ 'Công khai' (Public) nghĩa là:", "options": ["Chỉ người đăng bài xem được", "Chỉ bạn bè của người đăng xem được", "Bất kỳ ai, kể cả người không phải bạn bè, đều có thể xem", "Chỉ những người được gắn thẻ (tag) trong bài mới xem được"], "answer": 2, "explain": "Mục 6.4 (Tạo trang cá nhân): khi quản lý trang cá nhân cần chọn đối tượng xem phù hợp; chế độ Công khai cho phép mọi người xem bài đăng."}, {"topic": "6.4 Sử dụng Website", "q": "Khi quên mật khẩu tài khoản trên một website, cách xử lý đúng là gì?", "options": ["Đăng ký thêm nhiều tài khoản mới bằng cùng một địa chỉ email", "Nhờ bạn bè đăng nhập giúp bằng tài khoản của họ", "Tải công cụ dò mật khẩu về để thử tự động", "Dùng chức năng 'Quên mật khẩu' (Forgot password) để đặt lại qua email hoặc số điện thoại đã đăng ký"], "answer": 3, "explain": "Mục 6.4 (Truy cập các trang web yêu cầu đăng nhập): website cung cấp chức năng Forgot password để đặt lại mật khẩu qua kênh đã đăng ký."}, {"topic": "6.5 Sử dụng thư điện tử", "q": "Đặc điểm nào sau đây đúng với thư điện tử (email)?", "options": ["Có thể chuyển thông tin từ một máy nguồn tới một hoặc nhiều máy nhận cùng lúc qua mạng máy tính", "Chỉ gửi được đến một người nhận tại một thời điểm", "Chỉ hoạt động trong mạng LAN nội bộ, không đi qua Internet", "Chỉ truyền được nội dung dạng hình ảnh, không truyền được văn bản"], "answer": 0, "explain": "Mục 6.5 (Giới thiệu Email): thư có thể chuyển từ một máy nguồn tới một hay rất nhiều máy nhận trong cùng lúc, đặc biệt qua Internet."}, {"topic": "6.5 Sử dụng thư điện tử", "q": "Web Mail (thư điện tử qua Web) có đặc điểm nào sau đây?", "options": ["Bắt buộc phải cài phần mềm chuyên dụng lên từng máy tính của người dùng", "Chỉ dùng được khi máy tính không kết nối Internet", "Không cần cài đặt phần mềm riêng, được cung ứng bởi máy chủ web trên Internet và truy cập qua trình duyệt", "Chỉ sử dụng được trên hệ điều hành Windows"], "answer": 2, "explain": "Mục 6.5 (Phân biệt Email): WebMail không cần cài đặt, do web server cung ứng, ví dụ gmail.com, hotmail.com, mail.yahoo.com."}, {"topic": "6.5 Sử dụng thư điện tử", "q": "Phần mềm nào sau đây là email client (còn gọi là MUA - Mail User Agent) được cài đặt trên máy tính người dùng?", "options": ["gmail.com", "Microsoft Outlook", "mail.yahoo.com", "hotmail.com"], "answer": 1, "explain": "Mục 6.5 (Email Client): Microsoft Outlook, Eudora... là email client (MUA), còn gmail.com, mail.yahoo.com, hotmail.com là WebMail."}, {"topic": "6.5 Sử dụng thư điện tử", "q": "Khi gửi email, người nhận được thêm vào trường Bcc sẽ:", "options": ["Là người nhận chính duy nhất của thư", "Được hiển thị địa chỉ cho tất cả những người nhận khác", "Chỉ nhận thông báo có thư mà không đọc được nội dung", "Nhận được thư nhưng địa chỉ không hiển thị cho những người nhận khác"], "answer": 3, "explain": "Kiến thức email phổ thông (mục 6.5 - Cách gửi và nhận email): Bcc (Blind carbon copy) là bản sao ẩn, địa chỉ không hiện với những người nhận khác."}, {"topic": "6.5 Sử dụng thư điện tử", "q": "Chức năng 'Trả lời tất cả' (Reply all) sẽ gửi thư trả lời đến:", "options": ["Chỉ người gửi thư gốc", "Người gửi thư gốc và tất cả người nhận khác ở các trường To và Cc", "Tất cả địa chỉ có trong danh bạ của người dùng", "Chỉ những người nhận ở trường Bcc"], "answer": 1, "explain": "Kiến thức email phổ thông (mục 6.5 - Cách gửi và nhận email): Reply all gửi đến người gửi và mọi người nhận trong To và Cc, còn Reply chỉ gửi cho người gửi."}, {"topic": "6.5 Sử dụng thư điện tử", "q": "Giao thức nào thường được dùng để gửi thư điện tử từ email client tới máy chủ mail?", "options": ["SMTP", "POP3", "IMAP", "FTP"], "answer": 0, "explain": "Kiến thức email phổ thông (mục 6.5): SMTP dùng để gửi thư, còn POP3 và IMAP dùng để nhận thư."}, {"topic": "6.5 Sử dụng thư điện tử", "q": "Theo giáo trình, sau khi đăng nhập tài khoản Google, người dùng được cấp không gian lưu trữ trực tuyến Google Drive miễn phí là bao nhiêu?", "options": ["1 GB", "5 GB", "50 GB", "15 GB"], "answer": 3, "explain": "Mục 6.5 (Sử dụng Google Drive): giáo trình nêu dung lượng miễn phí 15 GB (dung lượng dùng chung với Gmail và Google Photos)."}, {"topic": "6.5 Sử dụng thư điện tử", "q": "Tính năng Signature (chữ ký) trong cài đặt Gmail có tác dụng gì?", "options": ["Mã hóa nội dung thư để chỉ người nhận mới đọc được", "Xác nhận thư gửi đi không chứa virus", "Tự động chèn đoạn văn bản định sẵn (họ tên, chức danh, liên hệ) vào cuối thư khi soạn", "Tự động dịch thư sang ngôn ngữ của người nhận"], "answer": 2, "explain": "Mục 6.5 (Google Mail - Tạo chữ ký): signature là đoạn văn bản được thiết lập sẵn và tự động chèn vào cuối thư soạn mới."}], "cards": [{"topic": "6.1 Kiến thức cơ bản về Internet", "front": "Internet là gì?", "back": "Hệ thống thông tin toàn cầu, truy nhập công cộng, gồm các mạng máy tính liên kết với nhau; truyền dữ liệu theo kiểu chuyển mạch gói (packet switching) dựa trên bộ giao thức TCP/IP."}, {"topic": "6.1 Kiến thức cơ bản về Internet", "front": "IPv4 và IPv6 khác nhau thế nào?", "back": "IPv4: 32 bit, gồm 4 số thập phân 0-255 phân cách bằng dấu chấm (VD 172.16.19.5), đã cạn kiệt. IPv6: 128 bit, đang thay thế dần. Mỗi máy (host) tham gia Internet phải có một địa chỉ IP."}, {"topic": "6.1 Kiến thức cơ bản về Internet", "front": "DNS (Domain Name System) làm nhiệm vụ gì?", "back": "Ánh xạ giữa tên miền và địa chỉ IP, giúp dễ nhớ hơn (VD www.tuoitre.vn tương ứng 123.30.128.10)."}, {"topic": "6.1 Kiến thức cơ bản về Internet", "front": "IAP là gì?", "back": "Internet Access Provider: nhà cung cấp dịch vụ đường truyền để kết nối Internet, quản lý cổng (gateway) nối ra quốc tế."}, {"topic": "6.1 Kiến thức cơ bản về Internet", "front": "ISP là gì? Tài khoản ISP gồm gì?", "back": "Internet Service Provider: nhà cung cấp dịch vụ Internet cho tổ chức và cá nhân, thuê đường truyền và cổng của IAP (VD FPT, Viettel). Tài khoản gồm User name và Password."}, {"topic": "6.1 Kiến thức cơ bản về Internet", "front": "FTP là gì? Phân biệt downloading và uploading.", "back": "File Transfer Protocol: dịch vụ chuyển tập tin giữa các máy. Downloading: chép file từ máy chủ từ xa về máy tính. Uploading: chép file từ máy tính lên máy chủ từ xa."}, {"topic": "6.1 Kiến thức cơ bản về Internet", "front": "WWW (Web) là gì?", "back": "Dịch vụ Internet được dùng nhiều nhất; chứa văn bản, hình ảnh, âm thanh, video kết hợp với nhau; các điểm chứa dữ liệu gọi là website."}, {"topic": "6.2 Bảo mật khi làm việc với Internet", "front": "Đặc điểm của mật khẩu mạnh?", "back": "Nên dài từ 12 ký tự trở lên, kết hợp chữ hoa, chữ thường, số và ký tự đặc biệt; không dùng thông tin cá nhân; mỗi tài khoản dùng một mật khẩu riêng."}, {"topic": "6.2 Bảo mật khi làm việc với Internet", "front": "2FA là gì?", "back": "Two-factor authentication (xác thực hai yếu tố): ngoài mật khẩu còn cần thêm một yếu tố xác minh khác như mã OTP hoặc ứng dụng xác thực."}, {"topic": "6.2 Bảo mật khi làm việc với Internet", "front": "Phishing là gì?", "back": "Lừa đảo giả mạo: dùng email hoặc trang web giả danh tổ chức uy tín để đánh cắp thông tin đăng nhập, thông tin thẻ của người dùng."}, {"topic": "6.2 Bảo mật khi làm việc với Internet", "front": "Spyware là gì? Phòng ngừa thế nào?", "back": "Phần mềm gián điệp âm thầm theo dõi và thu thập thông tin người dùng gửi cho bên khác. Phòng ngừa: cài antivirus/anti-spyware và cập nhật, chỉ tải phần mềm từ nguồn tin cậy."}, {"topic": "6.2 Bảo mật khi làm việc với Internet", "front": "HTTPS khác HTTP ở điểm nào?", "back": "HTTPS mã hóa kết nối giữa trình duyệt và website bằng TLS/SSL; HTTP truyền dữ liệu không mã hóa. HTTPS chỉ bảo đảm kết nối được mã hóa, chưa chứng minh website uy tín."}, {"topic": "6.3 Sử dụng trình duyệt web", "front": "URL có cấu trúc như thế nào?", "back": "Uniform Resource Locator: giao thức://tên miền/đường dẫn (VD https://www.tuoitre.vn/the-thao.htm), nhập vào thanh địa chỉ của trình duyệt."}, {"topic": "6.3 Sử dụng trình duyệt web", "front": "Phím tắt thêm trang hiện tại vào Bookmarks?", "back": "Ctrl+D. Bookmarks (Đánh dấu trang) lưu địa chỉ trang web yêu thích để mở lại nhanh."}, {"topic": "6.3 Sử dụng trình duyệt web", "front": "Phím tắt mở lịch sử duyệt web (History)?", "back": "Ctrl+H (Chrome, Edge, Firefox trên Windows)."}, {"topic": "6.3 Sử dụng trình duyệt web", "front": "Phím tắt lưu trang web hiện tại về máy?", "back": "Ctrl+S (Save page as)."}, {"topic": "6.3 Sử dụng trình duyệt web", "front": "Chế độ ẩn danh (Incognito / InPrivate / Private) làm được gì và không làm được gì?", "back": "Không lưu lịch sử duyệt web, cookie, dữ liệu biểu mẫu trên máy sau khi đóng cửa sổ; nhưng website và ISP vẫn thấy được hoạt động, không tự chặn mã độc."}, {"topic": "6.4 Sử dụng Website", "front": "Hyperlink (siêu liên kết) là gì?", "back": "Thành phần trên trang web (chữ, hình) cho phép chuyển đến trang hoặc tài nguyên khác khi nhấp vào."}, {"topic": "6.4 Sử dụng Website", "front": "Dùng xong trang web yêu cầu đăng nhập trên máy công cộng cần làm gì?", "back": "Đăng xuất (Log out / Sign out) và không cho trình duyệt lưu mật khẩu."}, {"topic": "6.4 Sử dụng Website", "front": "Mạng xã hội và trang cá nhân: cần lưu ý gì?", "back": "Mạng xã hội (VD Facebook, Zalo) cho phép tạo trang cá nhân, kết nối và chia sẻ thông tin; cần thiết lập quyền riêng tư (Công khai, Bạn bè, Chỉ mình tôi) và không đăng thông tin nhạy cảm."}, {"topic": "6.5 Sử dụng thư điện tử", "front": "WebMail là gì? Cho ví dụ.", "back": "Phần mềm thư điện tử không cần cài đặt, do web server trên Internet cung ứng, truy cập qua trình duyệt. VD gmail.com, hotmail.com, mail.yahoo.com."}, {"topic": "6.5 Sử dụng thư điện tử", "front": "Email Client (MUA) là gì? Cho ví dụ.", "back": "Phần mềm thư điện tử cài đặt trên máy người dùng, còn gọi là MUA (Mail User Agent) hay email application. VD Microsoft Outlook, Eudora."}, {"topic": "6.5 Sử dụng thư điện tử", "front": "Phân biệt To, Cc và Bcc?", "back": "To: người nhận chính. Cc (Carbon copy): bản sao, mọi người nhận đều thấy địa chỉ. Bcc (Blind carbon copy): bản sao ẩn, địa chỉ không hiển thị cho người nhận khác."}, {"topic": "6.5 Sử dụng thư điện tử", "front": "SMTP, POP3, IMAP dùng để làm gì?", "back": "SMTP: gửi thư. POP3 và IMAP: nhận thư (IMAP đồng bộ hộp thư trên máy chủ)."}, {"topic": "6.5 Sử dụng thư điện tử", "front": "Google Drive và Google Translate là gì?", "back": "Google Drive: không gian lưu trữ trực tuyến gắn với tài khoản Google, miễn phí 15 GB theo giáo trình. Google Translate: dịch văn bản và trang web giữa nhiều ngôn ngữ."}]}}};
